INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(11, '1 Raj', '1 Kings', 1, 1, 'King David was old and advanced in years; and although they covered him with clothes, he could not get warm.', 'en', 'NRSV-CE', 'The Struggle for the Succession'),
(11, '1 Raj', '1 Kings', 1, 2, 'So his servants said to him, "Let a young virgin be sought for my lord the king, and let her wait on the king, and be his attendant; let her lie in your bosom, so that my lord the king may be warm."', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 1, 3, 'So they searched for a beautiful girl throughout all the territory of Israel, and found Abishag the Shunammite, and brought her to the king.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 1, 4, 'The girl was very beautiful. She became the king"s attendant and served him, but the king did not know her sexually.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 1, 5, 'Now Adonijah son of Haggith exalted himself, saying, "I will be king"; he prepared for himself chariots and horsemen, and fifty men to run before him.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 1, 6, 'His father had never at any time displeased him by asking, "Why have you done thus and so?" He was also a very handsome man, and he was born next after Absalom.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 1, 7, 'He conferred with Joab son of Zeruiah and with the priest Abiathar, and they supported Adonijah.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 1, 8, 'But the priest Zadok, and Benaiah son of Jehoiada, and the prophet Nathan, and Shimei, and Rei, and David"s own warriors did not side with Adonijah.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 1, 9, 'Adonijah sacrificed sheep, oxen, and fatted cattle by the stone Zoheleth, which is beside En-rogel, and he invited all his brothers, the king"s sons, and all the royal officials of Judah,', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 1, 10, 'but he did not invite the prophet Nathan or Benaiah or the warriors or his brother Solomon.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 1, 11, 'Then Nathan said to Bathsheba, Solomon"s mother, "Have you not heard that Adonijah son of Haggith has become king and our lord David does not know it?', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 1, 12, 'Now therefore come, let me give you advice, so that you may save your own life and the life of your son Solomon.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 1, 13, 'Go in at once to King David, and say to him, "Did you not, my lord the king, swear to your servant, saying: Your son Solomon shall succeed me as king, and he shall sit on my throne? Why then is Adonijah king?"', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 1, 14, 'Then while you are still there speaking with the king, I will come in after you and confirm your words."', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 1, 15, 'So Bathsheba went to the king in his room. The king was very old; Abishag the Shunammite was attending the king.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 1, 16, 'Bathsheba bowed and did obeisance to the king, and the king said, "What do you wish?"', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 1, 17, 'She said to him, "My lord, you swore to your servant by the LORD your God, saying: Your son Solomon shall succeed me as king, and he shall sit on my throne.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 1, 18, 'But now suddenly Adonijah has become king, though you, my lord the king, do not know it.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 1, 19, 'He has sacrificed oxen, fatted cattle, and sheep in abundance, and has invited all the children of the king, the priest Abiathar, and Joab the commander of the army; but your servant Solomon he has not invited.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 1, 20, 'But you, my lord the king--the eyes of all Israel are on you to tell them who shall sit on the throne of my lord the king after him.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 1, 21, 'Otherwise it will come to pass, when my lord the king sleeps with his ancestors, that my son Solomon and I will be counted offenders."', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 1, 22, 'While she was still speaking with the king, the prophet Nathan came in.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 1, 23, 'The king was told, "Here is the prophet Nathan." When he came in before the king, he did obeisance to the king, with his face to the ground.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 1, 24, 'Nathan said, "My lord the king, have you said, "Adonijah shall succeed me as king, and he shall sit on my throne"?', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 1, 25, 'For today he has gone down and has sacrificed oxen, fatted cattle, and sheep in abundance, and has invited all the king"s children, Joab the commander of the army, and the priest Abiathar, who are now eating and drinking before him, and saying, "Long live King Adonijah!"', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 1, 26, 'But he did not invite me, your servant, and the priest Zadok, and Benaiah son of Jehoiada, and your servant Solomon.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 1, 27, 'Has this thing been brought about by my lord the king and you have not let your servants know who should sit on the throne of my lord the king after him?"', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 1, 28, 'King David answered, "Summon Bathsheba to me." So she came into the king"s presence, and stood before the king.', 'en', 'NRSV-CE', 'The Accession of Solomon'),
(11, '1 Raj', '1 Kings', 1, 29, 'The king swore, saying, "As the LORD lives, who has saved my life from every adversity,', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 1, 30, 'as I swore to you by the LORD, the God of Israel, "Your son Solomon shall succeed me as king, and he shall sit on my throne in my place," so will I do this day."', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 1, 31, 'Then Bathsheba bowed with her face to the ground, and did obeisance to the king, and said, "May my lord King David live forever!"', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 1, 32, 'King David said, "Summon to me the priest Zadok, the prophet Nathan, and Benaiah son of Jehoiada." When they came before the king,', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 1, 33, 'the king said to them, "Take with you the servants of your lord, and have my son Solomon ride on my own mule, and bring him down to Gihon.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 1, 34, 'There let the priest Zadok and the prophet Nathan anoint him king over Israel; then blow the trumpet, and say, "Long live King Solomon!"', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 1, 35, 'You shall go up following him. Let him enter and sit on my throne; he shall be king in my place; for I have appointed him to be ruler over Israel and over Judah."', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 1, 36, 'Benaiah son of Jehoiada answered the king, "Amen! May the LORD, the God of my lord the king, so ordain.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 1, 37, 'As the LORD has been with my lord the king, so may he be with Solomon, and make his throne greater than the throne of my lord King David."', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 1, 38, 'So the priest Zadok, the prophet Nathan, and Benaiah son of Jehoiada, and the Cherethites and the Pelethites, went down and had Solomon ride on King David"s mule, and led him to Gihon.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 1, 39, 'There the priest Zadok took the horn of oil from the tent and anointed Solomon. Then they blew the trumpet, and all the people said, "Long live King Solomon!"', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 1, 40, 'And all the people went up following him, playing on pipes and rejoicing with great joy, so that the earth quaked at their noise.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 1, 41, 'Adonijah and all the guests who were with him heard it as they finished feasting. When Joab heard the sound of the trumpet, he said, "Why is the city in an uproar?"', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 1, 42, 'While he was still speaking, Jonathan son of the priest Abiathar arrived. Adonijah said, "Come in, for you are a worthy man and surely you bring good news."', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 1, 43, 'Jonathan answered Adonijah, "No, for our lord King David has made Solomon king;', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 1, 44, 'the king has sent with him the priest Zadok, the prophet Nathan, and Benaiah son of Jehoiada, and the Cherethites and the Pelethites; and they had him ride on the king"s mule;', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 1, 45, 'the priest Zadok and the prophet Nathan have anointed him king at Gihon; and they have gone up from there rejoicing, so that the city is in an uproar. This is the noise that you heard.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 1, 46, 'Solomon now sits on the royal throne.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 1, 47, 'Moreover the king"s servants came to congratulate our lord King David, saying, "May God make the name of Solomon more famous than yours, and make his throne greater than your throne." The king bowed in worship on the bed', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 1, 48, 'and went on to pray thus, "Blessed be the LORD, the God of Israel, who today has granted one of my offspring to sit on my throne and permitted me to witness it.""', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 1, 49, 'Then all the guests of Adonijah got up trembling and went their own ways.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 1, 50, 'Adonijah, fearing Solomon, got up and went to grasp the horns of the altar.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 1, 51, 'Solomon was informed, "Adonijah is afraid of King Solomon; see, he has laid hold of the horns of the altar, saying, "Let King Solomon swear to me first that he will not kill his servant with the sword.""', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 1, 52, 'So Solomon responded, "If he proves to be a worthy man, not one of his hairs shall fall to the ground; but if wickedness is found in him, he shall die."', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 1, 53, 'Then King Solomon sent to have him brought down from the altar. He came to do obeisance to King Solomon; and Solomon said to him, "Go home."', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(11, '1 Raj', '1 Kings', 2, 1, 'When David"s time to die drew near, he charged his son Solomon, saying:', 'en', 'NRSV-CE', 'David"s Instruction to Solomon'),
(11, '1 Raj', '1 Kings', 2, 2, '"I am about to go the way of all the earth. Be strong, be courageous,', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 2, 3, 'and keep the charge of the LORD your God, walking in his ways and keeping his statutes, his commandments, his ordinances, and his testimonies, as it is written in the law of Moses, so that you may prosper in all that you do and wherever you turn.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 2, 4, 'Then the LORD will establish his word that he spoke concerning me: "If your heirs take heed to their way, to walk before me in faithfulness with all their heart and with all their soul, there shall not fail you a successor on the throne of Israel."', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 2, 5, '"Moreover you know also what Joab son of Zeruiah did to me, how he dealt with the two commanders of the armies of Israel, Abner son of Ner, and Amasa son of Jether, whom he murdered, retaliating in time of peace for blood that had been shed in war, and putting the blood of war on the belt around his waist, and on the sandals on his feet.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 2, 6, 'Act therefore according to your wisdom, but do not let his gray head go down to Sheol in peace.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 2, 7, 'Deal loyally, however, with the sons of Barzillai the Gileadite, and let them be among those who eat at your table; for with such loyalty they met me when I fled from your brother Absalom.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 2, 8, 'There is also with you Shimei son of Gera, the Benjaminite from Bahurim, who cursed me with a terrible curse on the day when I went to Mahanaim; but when he came down to meet me at the Jordan, I swore to him by the LORD, "I will not put you to death with the sword."', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 2, 9, 'Therefore do not hold him guiltless, for you are a wise man; you will know what you ought to do to him, and you must bring his gray head down with blood to Sheol."', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 2, 10, 'Then David slept with his ancestors, and was buried in the city of David.', 'en', 'NRSV-CE', 'Death of David'),
(11, '1 Raj', '1 Kings', 2, 11, 'The time that David reigned over Israel was forty years; he reigned seven years in Hebron, and thirty-three years in Jerusalem.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 2, 12, 'So Solomon sat on the throne of his father David; and his kingdom was firmly established.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 2, 13, 'Then Adonijah son of Haggith came to Bathsheba, Solomon"s mother. She asked, "Do you come peaceably?" He said, "Peaceably."', 'en', 'NRSV-CE', 'Solomon Consolidates His Reign'),
(11, '1 Raj', '1 Kings', 2, 14, 'Then he said, "May I have a word with you?" She said, "Go on."', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 2, 15, 'He said, "You know that the kingdom was mine, and that all Israel expected me to reign; however, the kingdom has turned about and become my brother"s, for it was his from the LORD.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 2, 16, 'And now I have one request to make of you; do not refuse me." She said to him, "Go on."', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 2, 17, 'He said, "Please ask King Solomon--he will not refuse you--to give me Abishag the Shunammite as my wife."', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 2, 18, 'Bathsheba said, "Very well; I will speak to the king on your behalf."', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 2, 19, 'So Bathsheba went to King Solomon, to speak to him on behalf of Adonijah. The king rose to meet her, and bowed down to her; then he sat on his throne, and had a throne brought for the king"s mother, and she sat on his right.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 2, 20, 'Then she said, "I have one small request to make of you; do not refuse me." And the king said to her, "Make your request, my mother; for I will not refuse you."', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 2, 21, 'She said, "Let Abishag the Shunammite be given to your brother Adonijah as his wife."', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 2, 22, 'King Solomon answered his mother, "And why do you ask Abishag the Shunammite for Adonijah? Ask for him the kingdom as well! For he is my elder brother; ask not only for him but also for the priest Abiathar and for Joab son of Zeruiah!"', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 2, 23, 'Then King Solomon swore by the LORD, "So may God do to me, and more also, for Adonijah has devised this scheme at the risk of his life!', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 2, 24, 'Now therefore as the LORD lives, who has established me and placed me on the throne of my father David, and who has made me a house as he promised, today Adonijah shall be put to death."', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 2, 25, 'So King Solomon sent Benaiah son of Jehoiada; he struck him down, and he died.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 2, 26, 'The king said to the priest Abiathar, "Go to Anathoth, to your estate; for you deserve death. But I will not at this time put you to death, because you carried the ark of the Lord God before my father David, and because you shared in all the hardships my father endured."', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 2, 27, 'So Solomon banished Abiathar from being priest to the LORD, thus fulfilling the word of the LORD that he had spoken concerning the house of Eli in Shiloh.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 2, 28, 'When the news came to Joab--for Joab had supported Adonijah though he had not supported Absalom--Joab fled to the tent of the LORD and grasped the horns of the altar.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 2, 29, 'When it was told King Solomon, "Joab has fled to the tent of the LORD and now is beside the altar," Solomon sent Benaiah son of Jehoiada, saying, "Go, strike him down."', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 2, 30, 'So Benaiah came to the tent of the LORD and said to him, "The king commands, "Come out."" But he said, "No, I will die here." Then Benaiah brought the king word again, saying, "Thus said Joab, and thus he answered me."', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 2, 31, 'The king replied to him, "Do as he has said, strike him down and bury him; and thus take away from me and from my father"s house the guilt for the blood that Joab shed without cause.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 2, 32, 'The LORD will bring back his bloody deeds on his own head, because, without the knowledge of my father David, he attacked and killed with the sword two men more righteous and better than himself, Abner son of Ner, commander of the army of Israel, and Amasa son of Jether, commander of the army of Judah.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 2, 33, 'So shall their blood come back on the head of Joab and on the head of his descendants forever; but to David, and to his descendants, and to his house, and to his throne, there shall be peace from the LORD forevermore."', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 2, 34, 'Then Benaiah son of Jehoiada went up and struck him down and killed him; and he was buried at his own house near the wilderness.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 2, 35, 'The king put Benaiah son of Jehoiada over the army in his place, and the king put the priest Zadok in the place of Abiathar.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 2, 36, 'Then the king sent and summoned Shimei, and said to him, "Build yourself a house in Jerusalem, and live there, and do not go out from there to any place whatever.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 2, 37, 'For on the day you go out, and cross the Wadi Kidron, know for certain that you shall die; your blood shall be on your own head."', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 2, 38, 'And Shimei said to the king, "The sentence is fair; as my lord the king has said, so will your servant do." So Shimei lived in Jerusalem many days.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 2, 39, 'But it happened at the end of three years that two of Shimei"s slaves ran away to King Achish son of Maacah of Gath. When it was told Shimei, "Your slaves are in Gath,"', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 2, 40, 'Shimei arose and saddled a donkey, and went to Achish in Gath, to search for his slaves; Shimei went and brought his slaves from Gath.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 2, 41, 'When Solomon was told that Shimei had gone from Jerusalem to Gath and returned,', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 2, 42, 'the king sent and summoned Shimei, and said to him, "Did I not make you swear by the LORD, and solemnly adjure you, saying, "Know for certain that on the day you go out and go to any place whatever, you shall die"? And you said to me, "The sentence is fair; I accept."', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 2, 43, 'Why then have you not kept your oath to the LORD and the commandment with which I charged you?"', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 2, 44, 'The king also said to Shimei, "You know in your own heart all the evil that you did to my father David; so the LORD will bring back your evil on your own head.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 2, 45, 'But King Solomon shall be blessed, and the throne of David shall be established before the LORD forever."', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 2, 46, 'Then the king commanded Benaiah son of Jehoiada; and he went out and struck him down, and he died.
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(11, '1 Raj', '1 Kings', 3, 1, 'Solomon made a marriage alliance with Pharaoh king of Egypt; he took Pharaoh"s daughter and brought her into the city of David, until he had finished building his own house and the house of the LORD and the wall around Jerusalem.', 'en', 'NRSV-CE', 'Solomon"s Prayer for Wisdom'),
(11, '1 Raj', '1 Kings', 3, 2, 'The people were sacrificing at the high places, however, because no house had yet been built for the name of the LORD.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 3, 3, 'Solomon loved the LORD, walking in the statutes of his father David; only, he sacrificed and offered incense at the high places.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 3, 4, 'The king went to Gibeon to sacrifice there, for that was the principal high place; Solomon used to offer a thousand burnt offerings on that altar.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 3, 5, 'At Gibeon the LORD appeared to Solomon in a dream by night; and God said, "Ask what I should give you."', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 3, 6, 'And Solomon said, "You have shown great and steadfast love to your servant my father David, because he walked before you in faithfulness, in righteousness, and in uprightness of heart toward you; and you have kept for him this great and steadfast love, and have given him a son to sit on his throne today.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 3, 7, 'And now, O LORD my God, you have made your servant king in place of my father David, although I am only a little child; I do not know how to go out or come in.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 3, 8, 'And your servant is in the midst of the people whom you have chosen, a great people, so numerous they cannot be numbered or counted.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 3, 9, 'Give your servant therefore an understanding mind to govern your people, able to discern between good and evil; for who can govern this your great people?"', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 3, 10, 'It pleased the Lord that Solomon had asked this.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 3, 11, 'God said to him, "Because you have asked this, and have not asked for yourself long life or riches, or for the life of your enemies, but have asked for yourself understanding to discern what is right,', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 3, 12, 'I now do according to your word. Indeed I give you a wise and discerning mind; no one like you has been before you and no one like you shall arise after you.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 3, 13, 'I give you also what you have not asked, both riches and honor all your life; no other king shall compare with you.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 3, 14, 'If you will walk in my ways, keeping my statutes and my commandments, as your father David walked, then I will lengthen your life."', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 3, 15, 'Then Solomon awoke; it had been a dream. He came to Jerusalem where he stood before the ark of the covenant of the LORD. He offered up burnt offerings and offerings of well-being, and provided a feast for all his servants.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 3, 16, 'Later, two women who were prostitutes came to the king and stood before him.', 'en', 'NRSV-CE', 'Solomon"s Wisdom in Judgment'),
(11, '1 Raj', '1 Kings', 3, 17, 'The one woman said, "Please, my lord, this woman and I live in the same house; and I gave birth while she was in the house.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 3, 18, 'Then on the third day after I gave birth, this woman also gave birth. We were together; there was no one else with us in the house, only the two of us were in the house.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 3, 19, 'Then this woman"s son died in the night, because she lay on him.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 3, 20, 'She got up in the middle of the night and took my son from beside me while your servant slept. She laid him at her breast, and laid her dead son at my breast.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 3, 21, 'When I rose in the morning to nurse my son, I saw that he was dead; but when I looked at him closely in the morning, clearly it was not the son I had borne."', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 3, 22, 'But the other woman said, "No, the living son is mine, and the dead son is yours." The first said, "No, the dead son is yours, and the living son is mine." So they argued before the king.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 3, 23, 'Then the king said, "The one says, "This is my son that is alive, and your son is dead"; while the other says, "Not so! Your son is dead, and my son is the living one.""', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 3, 24, 'So the king said, "Bring me a sword," and they brought a sword before the king.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 3, 25, 'The king said, "Divide the living boy in two; then give half to the one, and half to the other."', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 3, 26, 'But the woman whose son was alive said to the king--because compassion for her son burned within her--"Please, my lord, give her the living boy; certainly do not kill him!" The other said, "It shall be neither mine nor yours; divide it."', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 3, 27, 'Then the king responded: "Give the first woman the living boy; do not kill him. She is his mother."', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 3, 28, 'All Israel heard of the judgment that the king had rendered; and they stood in awe of the king, because they perceived that the wisdom of God was in him, to execute justice.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(11, '1 Raj', '1 Kings', 4, 1, 'King Solomon was king over all Israel,', 'en', 'NRSV-CE', 'Solomon"s Administrative Officers'),
(11, '1 Raj', '1 Kings', 4, 2, 'and these were his high officials: Azariah son of Zadok was the priest;', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 4, 3, 'Elihoreph and Ahijah sons of Shisha were secretaries; Jehoshaphat son of Ahilud was recorder;', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 4, 4, 'Benaiah son of Jehoiada was in command of the army; Zadok and Abiathar were priests;', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 4, 5, 'Azariah son of Nathan was over the officials; Zabud son of Nathan was priest and king"s friend;', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 4, 6, 'Ahishar was in charge of the palace; and Adoniram son of Abda was in charge of the forced labor.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 4, 7, 'Solomon had twelve officials over all Israel, who provided food for the king and his household; each one had to make provision for one month in the year.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 4, 8, 'These were their names: Ben-hur, in the hill country of Ephraim;', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 4, 9, 'Ben-deker, in Makaz, Shaalbim, Beth-shemesh, and Elon-beth-hanan;', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 4, 10, 'Ben-hesed, in Arubboth (to him belonged Socoh and all the land of Hepher);', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 4, 11, 'Ben-abinadab, in all Naphath-dor (he had Taphath, Solomon"s daughter, as his wife);', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 4, 12, 'Baana son of Ahilud, in Taanach, Megiddo, and all Beth-shean, which is beside Zarethan below Jezreel, and from Beth-shean to Abel-meholah, as far as the other side of Jokmeam;', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 4, 13, 'Ben-geber, in Ramoth-gilead (he had the villages of Jair son of Manasseh, which are in Gilead, and he had the region of Argob, which is in Bashan, sixty great cities with walls and bronze bars);', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 4, 14, 'Ahinadab son of Iddo, in Mahanaim;', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 4, 15, 'Ahimaaz, in Naphtali (he had taken Basemath, Solomon"s daughter, as his wife);', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 4, 16, 'Baana son of Hushai, in Asher and Bealoth;', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 4, 17, 'Jehoshaphat son of Paruah, in Issachar;', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 4, 18, 'Shimei son of Ela, in Benjamin;', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 4, 19, 'Geber son of Uri, in the land of Gilead, the country of King Sihon of the Amorites and of King Og of Bashan. And there was one official in the land of Judah.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 4, 20, 'Judah and Israel were as numerous as the sand by the sea; they ate and drank and were happy.', 'en', 'NRSV-CE', 'Magnificence of Solomon"s Rule'),
(11, '1 Raj', '1 Kings', 4, 21, 'Solomon was sovereign over all the kingdoms from the Euphrates to the land of the Philistines, even to the border of Egypt; they brought tribute and served Solomon all the days of his life.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 4, 22, 'Solomon"s provision for one day was thirty cors of choice flour, and sixty cors of meal,', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 4, 23, 'ten fat oxen, and twenty pasture-fed cattle, one hundred sheep, besides deer, gazelles, roebucks, and fatted fowl.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 4, 24, 'For he had dominion over all the region west of the Euphrates from Tiphsah to Gaza, over all the kings west of the Euphrates; and he had peace on all sides.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 4, 25, 'During Solomon"s lifetime Judah and Israel lived in safety, from Dan even to Beer-sheba, all of them under their vines and fig trees.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 4, 26, 'Solomon also had forty thousand stalls of horses for his chariots, and twelve thousand horsemen.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 4, 27, 'Those officials supplied provisions for King Solomon and for all who came to King Solomon"s table, each one in his month; they let nothing be lacking.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 4, 28, 'They also brought to the required place barley and straw for the horses and swift steeds, each according to his charge.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 4, 29, 'God gave Solomon very great wisdom, discernment, and breadth of understanding as vast as the sand on the seashore,', 'en', 'NRSV-CE', 'Fame of Solomon"s Wisdom'),
(11, '1 Raj', '1 Kings', 4, 30, 'so that Solomon"s wisdom surpassed the wisdom of all the people of the east, and all the wisdom of Egypt.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 4, 31, 'He was wiser than anyone else, wiser than Ethan the Ezrahite, and Heman, Calcol, and Darda, children of Mahol; his fame spread throughout all the surrounding nations.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 4, 32, 'He composed three thousand proverbs, and his songs numbered a thousand and five.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 4, 33, 'He would speak of trees, from the cedar that is in the Lebanon to the hyssop that grows in the wall; he would speak of animals, and birds, and reptiles, and fish.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 4, 34, 'People came from all the nations to hear the wisdom of Solomon; they came from all the kings of the earth who had heard of his wisdom.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(11, '1 Raj', '1 Kings', 5, 1, 'Now King Hiram of Tyre sent his servants to Solomon, when he heard that they had anointed him king in place of his father; for Hiram had always been a friend to David.', 'en', 'NRSV-CE', 'Preparations and Materials for the Temple'),
(11, '1 Raj', '1 Kings', 5, 2, 'Solomon sent word to Hiram, saying,', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 5, 3, '"You know that my father David could not build a house for the name of the LORD his God because of the warfare with which his enemies surrounded him, until the LORD put them under the soles of his feet.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 5, 4, 'But now the LORD my God has given me rest on every side; there is neither adversary nor misfortune.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 5, 5, 'So I intend to build a house for the name of the LORD my God, as the LORD said to my father David, "Your son, whom I will set on your throne in your place, shall build the house for my name."', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 5, 6, 'Therefore command that cedars from the Lebanon be cut for me. My servants will join your servants, and I will give you whatever wages you set for your servants; for you know that there is no one among us who knows how to cut timber like the Sidonians."', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 5, 7, 'When Hiram heard the words of Solomon, he rejoiced greatly, and said, "Blessed be the LORD today, who has given to David a wise son to be over this great people."', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 5, 8, 'Hiram sent word to Solomon, "I have heard the message that you have sent to me; I will fulfill all your needs in the matter of cedar and cypress timber.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 5, 9, 'My servants shall bring it down to the sea from the Lebanon; I will make it into rafts to go by sea to the place you indicate. I will have them broken up there for you to take away. And you shall meet my needs by providing food for my household."', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 5, 10, 'So Hiram supplied Solomon"s every need for timber of cedar and cypress.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 5, 11, 'Solomon in turn gave Hiram twenty thousand cors of wheat as food for his household, and twenty cors of fine oil. Solomon gave this to Hiram year by year.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 5, 12, 'So the LORD gave Solomon wisdom, as he promised him. There was peace between Hiram and Solomon; and the two of them made a treaty.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 5, 13, 'King Solomon conscripted forced labor out of all Israel; the levy numbered thirty thousand men.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 5, 14, 'He sent them to the Lebanon, ten thousand a month in shifts; they would be a month in the Lebanon and two months at home; Adoniram was in charge of the forced labor.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 5, 15, 'Solomon also had seventy thousand laborers and eighty thousand stonecutters in the hill country,', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 5, 16, 'besides Solomon"s three thousand three hundred supervisors who were over the work, having charge of the people who did the work.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 5, 17, 'At the king"s command, they quarried out great, costly stones in order to lay the foundation of the house with dressed stones.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 5, 18, 'So Solomon"s builders and Hiram"s builders and the Gebalites did the stonecutting and prepared the timber and the stone to build the house.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(11, '1 Raj', '1 Kings', 6, 1, 'In the four hundred eightieth year after the Israelites came out of the land of Egypt, in the fourth year of Solomon"s reign over Israel, in the month of Ziv, which is the second month, he began to build the house of the LORD.', 'en', 'NRSV-CE', 'Solomon Builds the Temple'),
(11, '1 Raj', '1 Kings', 6, 2, 'The house that King Solomon built for the LORD was sixty cubits long, twenty cubits wide, and thirty cubits high.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 6, 3, 'The vestibule in front of the nave of the house was twenty cubits wide, across the width of the house. Its depth was ten cubits in front of the house.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 6, 4, 'For the house he made windows with recessed frames.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 6, 5, 'He also built a structure against the wall of the house, running around the walls of the house, both the nave and the inner sanctuary; and he made side chambers all around.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 6, 6, 'The lowest story was five cubits wide, the middle one was six cubits wide, and the third was seven cubits wide; for around the outside of the house he made offsets on the wall in order that the supporting beams should not be inserted into the walls of the house.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 6, 7, 'The house was built with stone finished at the quarry, so that neither hammer nor ax nor any tool of iron was heard in the temple while it was being built.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 6, 8, 'The entrance for the middle story was on the south side of the house: one went up by winding stairs to the middle story, and from the middle story to the third.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 6, 9, 'So he built the house, and finished it; he roofed the house with beams and planks of cedar.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 6, 10, 'He built the structure against the whole house, each story five cubits high, and it was joined to the house with timbers of cedar.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 6, 11, 'Now the word of the LORD came to Solomon,', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 6, 12, '"Concerning this house that you are building, if you will walk in my statutes, obey my ordinances, and keep all my commandments by walking in them, then I will establish my promise with you, which I made to your father David.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 6, 13, 'I will dwell among the children of Israel, and will not forsake my people Israel."', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 6, 14, 'So Solomon built the house, and finished it.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 6, 15, 'He lined the walls of the house on the inside with boards of cedar; from the floor of the house to the rafters of the ceiling, he covered them on the inside with wood; and he covered the floor of the house with boards of cypress.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 6, 16, 'He built twenty cubits of the rear of the house with boards of cedar from the floor to the rafters, and he built this within as an inner sanctuary, as the most holy place.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 6, 17, 'The house, that is, the nave in front of the inner sanctuary, was forty cubits long.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 6, 18, 'The cedar within the house had carvings of gourds and open flowers; all was cedar, no stone was seen.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 6, 19, 'The inner sanctuary he prepared in the innermost part of the house, to set there the ark of the covenant of the LORD.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 6, 20, 'The interior of the inner sanctuary was twenty cubits long, twenty cubits wide, and twenty cubits high; he overlaid it with pure gold. He also overlaid the altar with cedar.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 6, 21, 'Solomon overlaid the inside of the house with pure gold, then he drew chains of gold across, in front of the inner sanctuary, and overlaid it with gold.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 6, 22, 'Next he overlaid the whole house with gold, in order that the whole house might be perfect; even the whole altar that belonged to the inner sanctuary he overlaid with gold.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 6, 23, 'In the inner sanctuary he made two cherubim of olivewood, each ten cubits high.', 'en', 'NRSV-CE', 'The Furnishings of the Temple'),
(11, '1 Raj', '1 Kings', 6, 24, 'Five cubits was the length of one wing of the cherub, and five cubits the length of the other wing of the cherub; it was ten cubits from the tip of one wing to the tip of the other.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 6, 25, 'The other cherub also measured ten cubits; both cherubim had the same measure and the same form.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 6, 26, 'The height of one cherub was ten cubits, and so was that of the other cherub.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 6, 27, 'He put the cherubim in the innermost part of the house; the wings of the cherubim were spread out so that a wing of one was touching the one wall, and a wing of the other cherub was touching the other wall; their other wings toward the center of the house were touching wing to wing.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 6, 28, 'He also overlaid the cherubim with gold.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 6, 29, 'He carved the walls of the house all around about with carved engravings of cherubim, palm trees, and open flowers, in the inner and outer rooms.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 6, 30, 'The floor of the house he overlaid with gold, in the inner and outer rooms.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 6, 31, 'For the entrance to the inner sanctuary he made doors of olivewood; the lintel and the doorposts were five-sided.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 6, 32, 'He covered the two doors of olivewood with carvings of cherubim, palm trees, and open flowers; he overlaid them with gold, and spread gold on the cherubim and on the palm trees.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 6, 33, 'So also he made for the entrance to the nave doorposts of olivewood, four-sided each,', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 6, 34, 'and two doors of cypress wood; the two leaves of the one door were folding, and the two leaves of the other door were folding.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 6, 35, 'He carved cherubim, palm trees, and open flowers, overlaying them with gold evenly applied upon the carved work.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 6, 36, 'He built the inner court with three courses of dressed stone to one course of cedar beams.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 6, 37, 'In the fourth year the foundation of the house of the LORD was laid, in the month of Ziv.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 6, 38, 'In the eleventh year, in the month of Bul, which is the eighth month, the house was finished in all its parts, and according to all its specifications. He was seven years in building it.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(11, '1 Raj', '1 Kings', 7, 1, 'Solomon was building his own house thirteen years, and he finished his entire house.', 'en', 'NRSV-CE', 'Solomon"s Palace and Other Buildings'),
(11, '1 Raj', '1 Kings', 7, 2, 'He built the House of the Forest of the Lebanon one hundred cubits long, fifty cubits wide, and thirty cubits high, built on four rows of cedar pillars, with cedar beams on the pillars.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 7, 3, 'It was roofed with cedar on the forty-five rafters, fifteen in each row, which were on the pillars.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 7, 4, 'There were window frames in the three rows, facing each other in the three rows.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 7, 5, 'All the doorways and doorposts had four-sided frames, opposite, facing each other in the three rows.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 7, 6, 'He made the Hall of Pillars fifty cubits long and thirty cubits wide. There was a porch in front with pillars, and a canopy in front of them.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 7, 7, 'He made the Hall of the Throne where he was to pronounce judgment, the Hall of Justice, covered with cedar from floor to floor.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 7, 8, 'His own house where he would reside, in the other court back of the hall, was of the same construction. Solomon also made a house like this hall for Pharaoh"s daughter, whom he had taken in marriage.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 7, 9, 'All these were made of costly stones, cut according to measure, sawed with saws, back and front, from the foundation to the coping, and from outside to the great court.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 7, 10, 'The foundation was of costly stones, huge stones, stones of eight and ten cubits.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 7, 11, 'There were costly stones above, cut to measure, and cedarwood.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 7, 12, 'The great court had three courses of dressed stone to one layer of cedar beams all around; so had the inner court of the house of the LORD, and the vestibule of the house.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 7, 13, 'Now King Solomon invited and received Hiram from Tyre.', 'en', 'NRSV-CE', 'Products of Hiram the Bronzeworker'),
(11, '1 Raj', '1 Kings', 7, 14, 'He was the son of a widow of the tribe of Naphtali, whose father, a man of Tyre, had been an artisan in bronze; he was full of skill, intelligence, and knowledge in working bronze. He came to King Solomon, and did all his work.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 7, 15, 'He cast two pillars of bronze. Eighteen cubits was the height of the one, and a cord of twelve cubits would encircle it; the second pillar was the same.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 7, 16, 'He also made two capitals of molten bronze, to set on the tops of the pillars; the height of the one capital was five cubits, and the height of the other capital was five cubits.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 7, 17, 'There were nets of checker work with wreaths of chain work for the capitals on the tops of the pillars; seven for the one capital, and seven for the other capital.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 7, 18, 'He made the columns with two rows around each latticework to cover the capitals that were above the pomegranates; he did the same with the other capital.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 7, 19, 'Now the capitals that were on the tops of the pillars in the vestibule were of lily-work, four cubits high.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 7, 20, 'The capitals were on the two pillars and also above the rounded projection that was beside the latticework; there were two hundred pomegranates in rows all around; and so with the other capital.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 7, 21, 'He set up the pillars at the vestibule of the temple; he set up the pillar on the south and called it Jachin; and he set up the pillar on the north and called it Boaz.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 7, 22, 'On the tops of the pillars was lily-work. Thus the work of the pillars was finished.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 7, 23, 'Then he made the molten sea; it was round, ten cubits from brim to brim, and five cubits high. A line of thirty cubits would encircle it completely.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 7, 24, 'Under its brim were panels all around it, each of ten cubits, surrounding the sea; there were two rows of panels, cast when it was cast.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 7, 25, 'It stood on twelve oxen, three facing north, three facing west, three facing south, and three facing east; the sea was set on them. The hindquarters of each were toward the inside.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 7, 26, 'Its thickness was a handbreadth; its brim was made like the brim of a cup, like the flower of a lily; it held two thousand baths.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 7, 27, 'He also made the ten stands of bronze; each stand was four cubits long, four cubits wide, and three cubits high.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 7, 28, 'This was the construction of the stands: they had borders; the borders were within the frames;', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 7, 29, 'on the borders that were set in the frames were lions, oxen, and cherubim. On the frames, both above and below the lions and oxen, there were wreaths of beveled work.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 7, 30, 'Each stand had four bronze wheels and axles of bronze; at the four corners were supports for a basin. The supports were cast with wreaths at the side of each.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 7, 31, 'Its opening was within the crown whose height was one cubit; its opening was round, as a pedestal is made; it was a cubit and a half wide. At its opening there were carvings; its borders were four-sided, not round.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 7, 32, 'The four wheels were underneath the borders; the axles of the wheels were in the stands; and the height of a wheel was a cubit and a half.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 7, 33, 'The wheels were made like a chariot wheel; their axles, their rims, their spokes, and their hubs were all cast.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 7, 34, 'There were four supports at the four corners of each stand; the supports were of one piece with the stands.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 7, 35, 'On the top of the stand there was a round band half a cubit high; on the top of the stand, its stays and its borders were of one piece with it.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 7, 36, 'On the surfaces of its stays and on its borders he carved cherubim, lions, and palm trees, where each had space, with wreaths all around.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 7, 37, 'In this way he made the ten stands; all of them were cast alike, with the same size and the same form.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 7, 38, 'He made ten basins of bronze; each basin held forty baths, each basin measured four cubits; there was a basin for each of the ten stands.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 7, 39, 'He set five of the stands on the south side of the house, and five on the north side of the house; he set the sea on the southeast corner of the house.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 7, 40, 'Hiram also made the pots, the shovels, and the basins. So Hiram finished all the work that he did for King Solomon on the house of the LORD:', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 7, 41, 'the two pillars, the two bowls of the capitals that were on the tops of the pillars, the two latticeworks to cover the two bowls of the capitals that were on the tops of the pillars;', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 7, 42, 'the four hundred pomegranates for the two latticeworks, two rows of pomegranates for each latticework, to cover the two bowls of the capitals that were on the pillars;', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 7, 43, 'the ten stands, the ten basins on the stands;', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 7, 44, 'the one sea, and the twelve oxen underneath the sea.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 7, 45, 'The pots, the shovels, and the basins, all these vessels that Hiram made for King Solomon for the house of the LORD were of burnished bronze.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 7, 46, 'In the plain of the Jordan the king cast them, in the clay ground between Succoth and Zarethan.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 7, 47, 'Solomon left all the vessels unweighed, because there were so many of them; the weight of the bronze was not determined.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 7, 48, 'So Solomon made all the vessels that were in the house of the LORD: the golden altar, the golden table for the bread of the Presence,', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 7, 49, 'the lampstands of pure gold, five on the south side and five on the north, in front of the inner sanctuary; the flowers, the lamps, and the tongs, of gold;', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 7, 50, 'the cups, snuffers, basins, dishes for incense, and firepans, of pure gold; the sockets for the doors of the innermost part of the house, the most holy place, and for the doors of the nave of the temple, of gold.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 7, 51, 'Thus all the work that King Solomon did on the house of the LORD was finished. Solomon brought in the things that his father David had dedicated, the silver, the gold, and the vessels, and stored them in the treasuries of the house of the LORD.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(11, '1 Raj', '1 Kings', 8, 1, 'Then Solomon assembled the elders of Israel and all the heads of the tribes, the leaders of the ancestral houses of the Israelites, before King Solomon in Jerusalem, to bring up the ark of the covenant of the LORD out of the city of David, which is Zion.', 'en', 'NRSV-CE', 'Dedication of the Temple'),
(11, '1 Raj', '1 Kings', 8, 2, 'All the people of Israel assembled to King Solomon at the festival in the month Ethanim, which is the seventh month.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 8, 3, 'And all the elders of Israel came, and the priests carried the ark.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 8, 4, 'So they brought up the ark of the LORD, the tent of meeting, and all the holy vessels that were in the tent; the priests and the Levites brought them up.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 8, 5, 'King Solomon and all the congregation of Israel, who had assembled before him, were with him before the ark, sacrificing so many sheep and oxen that they could not be counted or numbered.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 8, 6, 'Then the priests brought the ark of the covenant of the LORD to its place, in the inner sanctuary of the house, in the most holy place, underneath the wings of the cherubim.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 8, 7, 'For the cherubim spread out their wings over the place of the ark, so that the cherubim made a covering above the ark and its poles.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 8, 8, 'The poles were so long that the ends of the poles were seen from the holy place in front of the inner sanctuary; but they could not be seen from outside; they are there to this day.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 8, 9, 'There was nothing in the ark except the two tablets of stone that Moses had placed there at Horeb, where the LORD made a covenant with the Israelites, when they came out of the land of Egypt.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 8, 10, 'And when the priests came out of the holy place, a cloud filled the house of the LORD,', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 8, 11, 'so that the priests could not stand to minister because of the cloud; for the glory of the LORD filled the house of the LORD.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 8, 12, 'Then Solomon said,
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(11, '1 Raj', '1 Kings', 9, 1, 'When Solomon had finished building the house of the LORD and the king"s house and all that Solomon desired to build,', 'en', 'NRSV-CE', 'God Appears Again to Solomon'),
(11, '1 Raj', '1 Kings', 9, 2, 'the LORD appeared to Solomon a second time, as he had appeared to him at Gibeon.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 9, 3, 'The LORD said to him, "I have heard your prayer and your plea, which you made before me; I have consecrated this house that you have built, and put my name there forever; my eyes and my heart will be there for all time.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 9, 4, 'As for you, if you will walk before me, as David your father walked, with integrity of heart and uprightness, doing according to all that I have commanded you, and keeping my statutes and my ordinances,', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 9, 5, 'then I will establish your royal throne over Israel forever, as I promised your father David, saying, "There shall not fail you a successor on the throne of Israel."', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 9, 6, '"If you turn aside from following me, you or your children, and do not keep my commandments and my statutes that I have set before you, but go and serve other gods and worship them,', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 9, 7, 'then I will cut Israel off from the land that I have given them; and the house that I have consecrated for my name I will cast out of my sight; and Israel will become a proverb and a taunt among all peoples.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 9, 8, 'This house will become a heap of ruins; everyone passing by it will be astonished, and will hiss; and they will say, "Why has the LORD done such a thing to this land and to this house?"', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 9, 9, 'Then they will say, "Because they have forsaken the LORD their God, who brought their ancestors out of the land of Egypt, and embraced other gods, worshiping them and serving them; therefore the LORD has brought this disaster upon them.""', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 9, 10, 'At the end of twenty years, in which Solomon had built the two houses, the house of the LORD and the king"s house,', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 9, 11, 'King Hiram of Tyre having supplied Solomon with cedar and cypress timber and gold, as much as he desired, King Solomon gave to Hiram twenty cities in the land of Galilee.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 9, 12, 'But when Hiram came from Tyre to see the cities that Solomon had given him, they did not please him.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 9, 13, 'Therefore he said, "What kind of cities are these that you have given me, my brother?" So they are called the land of Cabul to this day.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 9, 14, 'But Hiram had sent to the king one hundred twenty talents of gold.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 9, 15, 'This is the account of the forced labor that King Solomon conscripted to build the house of the LORD and his own house, the Millo and the wall of Jerusalem, Hazor, Megiddo, Gezer', 'en', 'NRSV-CE', 'Other Acts of Solomon'),
(11, '1 Raj', '1 Kings', 9, 16, '(Pharaoh king of Egypt had gone up and captured Gezer and burned it down, had killed the Canaanites who lived in the city, and had given it as dowry to his daughter, Solomon"s wife;', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 9, 17, 'so Solomon rebuilt Gezer), Lower Beth-horon,', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 9, 18, 'Baalath, Tamar in the wilderness, within the land,', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 9, 19, 'as well as all of Solomon"s storage cities, the cities for his chariots, the cities for his cavalry, and whatever Solomon desired to build, in Jerusalem, in Lebanon, and in all the land of his dominion.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 9, 20, 'All the people who were left of the Amorites, the Hittites, the Perizzites, the Hivites, and the Jebusites, who were not of the people of Israel--', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 9, 21, 'their descendants who were still left in the land, whom the Israelites were unable to destroy completely--these Solomon conscripted for slave labor, and so they are to this day.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 9, 22, 'But of the Israelites Solomon made no slaves; they were the soldiers, they were his officials, his commanders, his captains, and the commanders of his chariotry and cavalry.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 9, 23, 'These were the chief officers who were over Solomon"s work: five hundred fifty, who had charge of the people who carried on the work.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 9, 24, 'But Pharaoh"s daughter went up from the city of David to her own house that Solomon had built for her; then he built the Millo.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 9, 25, 'Three times a year Solomon used to offer up burnt offerings and sacrifices of well-being on the altar that he built for the LORD, offering incense before the LORD. So he completed the house.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 9, 26, 'King Solomon built a fleet of ships at Ezion-geber, which is near Eloth on the shore of the Red Sea, in the land of Edom.', 'en', 'NRSV-CE', 'Solomon"s Commercial Activity'),
(11, '1 Raj', '1 Kings', 9, 27, 'Hiram sent his servants with the fleet, sailors who were familiar with the sea, together with the servants of Solomon.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 9, 28, 'They went to Ophir, and imported from there four hundred twenty talents of gold, which they delivered to King Solomon.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(11, '1 Raj', '1 Kings', 10, 1, 'When the queen of Sheba heard of the fame of Solomon (fame due to the name of the LORD), she came to test him with hard questions.', 'en', 'NRSV-CE', 'Visit of the Queen of Sheba'),
(11, '1 Raj', '1 Kings', 10, 2, 'She came to Jerusalem with a very great retinue, with camels bearing spices, and very much gold, and precious stones; and when she came to Solomon, she told him all that was on her mind.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 10, 3, 'Solomon answered all her questions; there was nothing hidden from the king that he could not explain to her.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 10, 4, 'When the queen of Sheba had observed all the wisdom of Solomon, the house that he had built,', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 10, 5, 'the food of his table, the seating of his officials, and the attendance of his servants, their clothing, his valets, and his burnt offerings that he offered at the house of the LORD, there was no more spirit in her.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 10, 6, 'So she said to the king, "The report was true that I heard in my own land of your accomplishments and of your wisdom,', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 10, 7, 'but I did not believe the reports until I came and my own eyes had seen it. Not even half had been told me; your wisdom and prosperity far surpass the report that I had heard.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 10, 8, 'Happy are your wives! Happy are these your servants, who continually attend you and hear your wisdom!', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 10, 9, 'Blessed be the LORD your God, who has delighted in you and set you on the throne of Israel! Because the LORD loved Israel forever, he has made you king to execute justice and righteousness."', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 10, 10, 'Then she gave the king one hundred twenty talents of gold, a great quantity of spices, and precious stones; never again did spices come in such quantity as that which the queen of Sheba gave to King Solomon.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 10, 11, 'Moreover, the fleet of Hiram, which carried gold from Ophir, brought from Ophir a great quantity of almug wood and precious stones.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 10, 12, 'From the almug wood the king made supports for the house of the LORD, and for the king"s house, lyres also and harps for the singers; no such almug wood has come or been seen to this day.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 10, 13, 'Meanwhile King Solomon gave to the queen of Sheba every desire that she expressed, as well as what he gave her out of Solomon"s royal bounty. Then she returned to her own land, with her servants.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 10, 14, 'The weight of gold that came to Solomon in one year was six hundred sixty-six talents of gold,', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 10, 15, 'besides that which came from the traders and from the business of the merchants, and from all the kings of Arabia and the governors of the land.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 10, 16, 'King Solomon made two hundred large shields of beaten gold; six hundred shekels of gold went into each large shield.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 10, 17, 'He made three hundred shields of beaten gold; three minas of gold went into each shield; and the king put them in the House of the Forest of Lebanon.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 10, 18, 'The king also made a great ivory throne, and overlaid it with the finest gold.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 10, 19, 'The throne had six steps. The top of the throne was rounded in the back, and on each side of the seat were arm rests and two lions standing beside the arm rests,', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 10, 20, 'while twelve lions were standing, one on each end of a step on the six steps. Nothing like it was ever made in any kingdom.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 10, 21, 'All King Solomon"s drinking vessels were of gold, and all the vessels of the House of the Forest of Lebanon were of pure gold; none were of silver--it was not considered as anything in the days of Solomon.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 10, 22, 'For the king had a fleet of ships of Tarshish at sea with the fleet of Hiram. Once every three years the fleet of ships of Tarshish used to come bringing gold, silver, ivory, apes, and peacocks.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 10, 23, 'Thus King Solomon excelled all the kings of the earth in riches and in wisdom.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 10, 24, 'The whole earth sought the presence of Solomon to hear his wisdom, which God had put into his mind.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 10, 25, 'Every one of them brought a present, objects of silver and gold, garments, weaponry, spices, horses, and mules, so much year by year.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 10, 26, 'Solomon gathered together chariots and horses; he had fourteen hundred chariots and twelve thousand horses, which he stationed in the chariot cities and with the king in Jerusalem.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 10, 27, 'The king made silver as common in Jerusalem as stones, and he made cedars as numerous as the sycamores of the Shephelah.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 10, 28, 'Solomon"s import of horses was from Egypt and Kue, and the king"s traders received them from Kue at a price.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 10, 29, 'A chariot could be imported from Egypt for six hundred shekels of silver, and a horse for one hundred fifty; so through the king"s traders they were exported to all the kings of the Hittites and the kings of Aram.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(11, '1 Raj', '1 Kings', 11, 1, 'King Solomon loved many foreign women along with the daughter of Pharaoh: Moabite, Ammonite, Edomite, Sidonian, and Hittite women,', 'en', 'NRSV-CE', 'Solomon"s Errors'),
(11, '1 Raj', '1 Kings', 11, 2, 'from the nations concerning which the LORD had said to the Israelites, "You shall not enter into marriage with them, neither shall they with you; for they will surely incline your heart to follow their gods"; Solomon clung to these in love.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 11, 3, 'Among his wives were seven hundred princesses and three hundred concubines; and his wives turned away his heart.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 11, 4, 'For when Solomon was old, his wives turned away his heart after other gods; and his heart was not true to the LORD his God, as was the heart of his father David.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 11, 5, 'For Solomon followed Astarte the goddess of the Sidonians, and Milcom the abomination of the Ammonites.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 11, 6, 'So Solomon did what was evil in the sight of the LORD, and did not completely follow the LORD, as his father David had done.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 11, 7, 'Then Solomon built a high place for Chemosh the abomination of Moab, and for Molech the abomination of the Ammonites, on the mountain east of Jerusalem.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 11, 8, 'He did the same for all his foreign wives, who offered incense and sacrificed to their gods.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 11, 9, 'Then the LORD was angry with Solomon, because his heart had turned away from the LORD, the God of Israel, who had appeared to him twice,', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 11, 10, 'and had commanded him concerning this matter, that he should not follow other gods; but he did not observe what the LORD commanded.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 11, 11, 'Therefore the LORD said to Solomon, "Since this has been your mind and you have not kept my covenant and my statutes that I have commanded you, I will surely tear the kingdom from you and give it to your servant.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 11, 12, 'Yet for the sake of your father David I will not do it in your lifetime; I will tear it out of the hand of your son.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 11, 13, 'I will not, however, tear away the entire kingdom; I will give one tribe to your son, for the sake of my servant David and for the sake of Jerusalem, which I have chosen."', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 11, 14, 'Then the LORD raised up an adversary against Solomon, Hadad the Edomite; he was of the royal house in Edom.', 'en', 'NRSV-CE', 'Adversaries of Solomon'),
(11, '1 Raj', '1 Kings', 11, 15, 'For when David was in Edom, and Joab the commander of the army went up to bury the dead, he killed every male in Edom', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 11, 16, '(for Joab and all Israel remained there six months, until he had eliminated every male in Edom);', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 11, 17, 'but Hadad fled to Egypt with some Edomites who were servants of his father. He was a young boy at that time.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 11, 18, 'They set out from Midian and came to Paran; they took people with them from Paran and came to Egypt, to Pharaoh king of Egypt, who gave him a house, assigned him an allowance of food, and gave him land.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 11, 19, 'Hadad found great favor in the sight of Pharaoh, so that he gave him his sister-in-law for a wife, the sister of Queen Tahpenes.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 11, 20, 'The sister of Tahpenes gave birth by him to his son Genubath, whom Tahpenes weaned in Pharaoh"s house; Genubath was in Pharaoh"s house among the children of Pharaoh.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 11, 21, 'When Hadad heard in Egypt that David slept with his ancestors and that Joab the commander of the army was dead, Hadad said to Pharaoh, "Let me depart, that I may go to my own country."', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 11, 22, 'But Pharaoh said to him, "What do you lack with me that you now seek to go to your own country?" And he said, "No, do let me go."', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 11, 23, 'God raised up another adversary against Solomon, Rezon son of Eliada, who had fled from his master, King Hadadezer of Zobah.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 11, 24, 'He gathered followers around him and became leader of a marauding band, after the slaughter by David; they went to Damascus, settled there, and made him king in Damascus.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 11, 25, 'He was an adversary of Israel all the days of Solomon, making trouble as Hadad did; he despised Israel and reigned over Aram.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 11, 26, 'Jeroboam son of Nebat, an Ephraimite of Zeredah, a servant of Solomon, whose mother"s name was Zeruah, a widow, rebelled against the king.', 'en', 'NRSV-CE', 'Jeroboam"s Rebellion'),
(11, '1 Raj', '1 Kings', 11, 27, 'The following was the reason he rebelled against the king. Solomon built the Millo, and closed up the gap in the wall of the city of his father David.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 11, 28, 'The man Jeroboam was very able, and when Solomon saw that the young man was industrious he gave him charge over all the forced labor of the house of Joseph.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 11, 29, 'About that time, when Jeroboam was leaving Jerusalem, the prophet Ahijah the Shilonite found him on the road. Ahijah had clothed himself with a new garment. The two of them were alone in the open country', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 11, 30, 'when Ahijah laid hold of the new garment he was wearing and tore it into twelve pieces.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 11, 31, 'He then said to Jeroboam: Take for yourself ten pieces; for thus says the LORD, the God of Israel, "See, I am about to tear the kingdom from the hand of Solomon, and will give you ten tribes.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 11, 32, 'One tribe will remain his, for the sake of my servant David and for the sake of Jerusalem, the city that I have chosen out of all the tribes of Israel.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 11, 33, 'This is because he has forsaken me, worshiped Astarte the goddess of the Sidonians, Chemosh the god of Moab, and Milcom the god of the Ammonites, and has not walked in my ways, doing what is right in my sight and keeping my statutes and my ordinances, as his father David did.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 11, 34, 'Nevertheless I will not take the whole kingdom away from him but will make him ruler all the days of his life, for the sake of my servant David whom I chose and who did keep my commandments and my statutes;', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 11, 35, 'but I will take the kingdom away from his son and give it to you--that is, the ten tribes.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 11, 36, 'Yet to his son I will give one tribe, so that my servant David may always have a lamp before me in Jerusalem, the city where I have chosen to put my name.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 11, 37, 'I will take you, and you shall reign over all that your soul desires; you shall be king over Israel.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 11, 38, 'If you will listen to all that I command you, walk in my ways, and do what is right in my sight by keeping my statutes and my commandments, as David my servant did, I will be with you, and will build you an enduring house, as I built for David, and I will give Israel to you.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 11, 39, 'For this reason I will punish the descendants of David, but not forever."', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 11, 40, 'Solomon sought therefore to kill Jeroboam; but Jeroboam promptly fled to Egypt, to King Shishak of Egypt, and remained in Egypt until the death of Solomon.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 11, 41, 'Now the rest of the acts of Solomon, all that he did as well as his wisdom, are they not written in the Book of the Acts of Solomon?', 'en', 'NRSV-CE', 'Death of Solomon'),
(11, '1 Raj', '1 Kings', 11, 42, 'The time that Solomon reigned in Jerusalem over all Israel was forty years.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 11, 43, 'Solomon slept with his ancestors and was buried in the city of his father David; and his son Rehoboam succeeded him.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(11, '1 Raj', '1 Kings', 12, 1, 'Rehoboam went to Shechem, for all Israel had come to Shechem to make him king.', 'en', 'NRSV-CE', 'The Northern Tribes Secede'),
(11, '1 Raj', '1 Kings', 12, 2, 'When Jeroboam son of Nebat heard of it (for he was still in Egypt, where he had fled from King Solomon), then Jeroboam returned from Egypt.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 12, 3, 'And they sent and called him; and Jeroboam and all the assembly of Israel came and said to Rehoboam,', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 12, 4, '"Your father made our yoke heavy. Now therefore lighten the hard service of your father and his heavy yoke that he placed on us, and we will serve you."', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 12, 5, 'He said to them, "Go away for three days, then come again to me." So the people went away.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 12, 6, 'Then King Rehoboam took counsel with the older men who had attended his father Solomon while he was still alive, saying, "How do you advise me to answer this people?"', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 12, 7, 'They answered him, "If you will be a servant to this people today and serve them, and speak good words to them when you answer them, then they will be your servants forever."', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 12, 8, 'But he disregarded the advice that the older men gave him, and consulted with the young men who had grown up with him and now attended him.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 12, 9, 'He said to them, "What do you advise that we answer this people who have said to me, "Lighten the yoke that your father put on us"?"', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 12, 10, 'The young men who had grown up with him said to him, "Thus you should say to this people who spoke to you, "Your father made our yoke heavy, but you must lighten it for us"; thus you should say to them, "My little finger is thicker than my father"s loins.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 12, 11, 'Now, whereas my father laid on you a heavy yoke, I will add to your yoke. My father disciplined you with whips, but I will discipline you with scorpions.""', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 12, 12, 'So Jeroboam and all the people came to Rehoboam the third day, as the king had said, "Come to me again the third day."', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 12, 13, 'The king answered the people harshly. He disregarded the advice that the older men had given him', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 12, 14, 'and spoke to them according to the advice of the young men, "My father made your yoke heavy, but I will add to your yoke; my father disciplined you with whips, but I will discipline you with scorpions."', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 12, 15, 'So the king did not listen to the people, because it was a turn of affairs brought about by the LORD that he might fulfill his word, which the LORD had spoken by Ahijah the Shilonite to Jeroboam son of Nebat.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 12, 16, 'When all Israel saw that the king would not listen to them, the people answered the king,
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(11, '1 Raj', '1 Kings', 13, 1, 'While Jeroboam was standing by the altar to offer incense, a man of God came out of Judah by the word of the LORD to Bethel', 'en', 'NRSV-CE', 'A Man of God from Judah'),
(11, '1 Raj', '1 Kings', 13, 2, 'and proclaimed against the altar by the word of the LORD, and said, "O altar, altar, thus says the LORD: "A son shall be born to the house of David, Josiah by name; and he shall sacrifice on you the priests of the high places who offer incense on you, and human bones shall be burned on you.""', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 13, 3, 'He gave a sign the same day, saying, "This is the sign that the LORD has spoken: "The altar shall be torn down, and the ashes that are on it shall be poured out.""', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 13, 4, 'When the king heard what the man of God cried out against the altar at Bethel, Jeroboam stretched out his hand from the altar, saying, "Seize him!" But the hand that he stretched out against him withered so that he could not draw it back to himself.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 13, 5, 'The altar also was torn down, and the ashes poured out from the altar, according to the sign that the man of God had given by the word of the LORD.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 13, 6, 'The king said to the man of God, "Entreat now the favor of the LORD your God, and pray for me, so that my hand may be restored to me." So the man of God entreated the LORD; and the king"s hand was restored to him, and became as it was before.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 13, 7, 'Then the king said to the man of God, "Come home with me and dine, and I will give you a gift."', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 13, 8, 'But the man of God said to the king, "If you give me half your kingdom, I will not go in with you; nor will I eat food or drink water in this place.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 13, 9, 'For thus I was commanded by the word of the LORD: You shall not eat food, or drink water, or return by the way that you came."', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 13, 10, 'So he went another way, and did not return by the way that he had come to Bethel.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 13, 11, 'Now there lived an old prophet in Bethel. One of his sons came and told him all that the man of God had done that day in Bethel; the words also that he had spoken to the king, they told to their father.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 13, 12, 'Their father said to them, "Which way did he go?" And his sons showed him the way that the man of God who came from Judah had gone.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 13, 13, 'Then he said to his sons, "Saddle a donkey for me." So they saddled a donkey for him, and he mounted it.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 13, 14, 'He went after the man of God, and found him sitting under an oak tree. He said to him, "Are you the man of God who came from Judah?" He answered, "I am."', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 13, 15, 'Then he said to him, "Come home with me and eat some food."', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 13, 16, 'But he said, "I cannot return with you, or go in with you; nor will I eat food or drink water with you in this place;', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 13, 17, 'for it was said to me by the word of the LORD: You shall not eat food or drink water there, or return by the way that you came."', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 13, 18, 'Then the other said to him, "I also am a prophet as you are, and an angel spoke to me by the word of the LORD: Bring him back with you into your house so that he may eat food and drink water." But he was deceiving him.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 13, 19, 'Then the man of God went back with him, and ate food and drank water in his house.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 13, 20, 'As they were sitting at the table, the word of the LORD came to the prophet who had brought him back;', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 13, 21, 'and he proclaimed to the man of God who came from Judah, "Thus says the LORD: Because you have disobeyed the word of the LORD, and have not kept the commandment that the LORD your God commanded you,', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 13, 22, 'but have come back and have eaten food and drunk water in the place of which he said to you, "Eat no food, and drink no water," your body shall not come to your ancestral tomb."', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 13, 23, 'After the man of God had eaten food and had drunk, they saddled for him a donkey belonging to the prophet who had brought him back.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 13, 24, 'Then as he went away, a lion met him on the road and killed him. His body was thrown in the road, and the donkey stood beside it; the lion also stood beside the body.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 13, 25, 'People passed by and saw the body thrown in the road, with the lion standing by the body. And they came and told it in the town where the old prophet lived.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 13, 26, 'When the prophet who had brought him back from the way heard of it, he said, "It is the man of God who disobeyed the word of the LORD; therefore the LORD has given him to the lion, which has torn him and killed him according to the word that the LORD spoke to him."', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 13, 27, 'Then he said to his sons, "Saddle a donkey for me." So they saddled one,', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 13, 28, 'and he went and found the body thrown in the road, with the donkey and the lion standing beside the body. The lion had not eaten the body or attacked the donkey.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 13, 29, 'The prophet took up the body of the man of God, laid it on the donkey, and brought it back to the city, to mourn and to bury him.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 13, 30, 'He laid the body in his own grave; and they mourned over him, saying, "Alas, my brother!"', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 13, 31, 'After he had buried him, he said to his sons, "When I die, bury me in the grave in which the man of God is buried; lay my bones beside his bones.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 13, 32, 'For the saying that he proclaimed by the word of the LORD against the altar in Bethel, and against all the houses of the high places that are in the cities of Samaria, shall surely come to pass."', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 13, 33, 'Even after this event Jeroboam did not turn from his evil way, but made priests for the high places again from among all the people; any who wanted to be priests he consecrated for the high places.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 13, 34, 'This matter became sin to the house of Jeroboam, so as to cut it off and to destroy it from the face of the earth.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(11, '1 Raj', '1 Kings', 14, 1, 'At that time Abijah son of Jeroboam fell sick.', 'en', 'NRSV-CE', 'Judgment on the House of Jeroboam'),
(11, '1 Raj', '1 Kings', 14, 2, 'Jeroboam said to his wife, "Go, disguise yourself, so that it will not be known that you are the wife of Jeroboam, and go to Shiloh; for the prophet Ahijah is there, who said of me that I should be king over this people.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 14, 3, 'Take with you ten loaves, some cakes, and a jar of honey, and go to him; he will tell you what shall happen to the child."', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 14, 4, 'Jeroboam"s wife did so; she set out and went to Shiloh, and came to the house of Ahijah. Now Ahijah could not see, for his eyes were dim because of his age.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 14, 5, 'But the LORD said to Ahijah, "The wife of Jeroboam is coming to inquire of you concerning her son; for he is sick. Thus and thus you shall say to her."
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(11, '1 Raj', '1 Kings', 15, 1, 'Now in the eighteenth year of King Jeroboam son of Nebat, Abijam began to reign over Judah.', 'en', 'NRSV-CE', 'Abijam Reigns over Judah: Idolatry and War'),
(11, '1 Raj', '1 Kings', 15, 2, 'He reigned for three years in Jerusalem. His mother"s name was Maacah daughter of Abishalom.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 15, 3, 'He committed all the sins that his father did before him; his heart was not true to the LORD his God, like the heart of his father David.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 15, 4, 'Nevertheless for David"s sake the LORD his God gave him a lamp in Jerusalem, setting up his son after him, and establishing Jerusalem;', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 15, 5, 'because David did what was right in the sight of the LORD, and did not turn aside from anything that he commanded him all the days of his life, except in the matter of Uriah the Hittite.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 15, 6, 'The war begun between Rehoboam and Jeroboam continued all the days of his life.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 15, 7, 'The rest of the acts of Abijam, and all that he did, are they not written in the Book of the Annals of the Kings of Judah? There was war between Abijam and Jeroboam.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 15, 8, 'Abijam slept with his ancestors, and they buried him in the city of David. Then his son Asa succeeded him.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 15, 9, 'In the twentieth year of King Jeroboam of Israel, Asa began to reign over Judah;', 'en', 'NRSV-CE', 'Asa Reigns over Judah'),
(11, '1 Raj', '1 Kings', 15, 10, 'he reigned forty-one years in Jerusalem. His mother"s name was Maacah daughter of Abishalom.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 15, 11, 'Asa did what was right in the sight of the LORD, as his father David had done.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 15, 12, 'He put away the male temple prostitutes out of the land, and removed all the idols that his ancestors had made.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 15, 13, 'He also removed his mother Maacah from being queen mother, because she had made an abominable image for Asherah; Asa cut down her image and burned it at the Wadi Kidron.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 15, 14, 'But the high places were not taken away. Nevertheless the heart of Asa was true to the LORD all his days.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 15, 15, 'He brought into the house of the LORD the votive gifts of his father and his own votive gifts--silver, gold, and utensils.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 15, 16, 'There was war between Asa and King Baasha of Israel all their days.', 'en', 'NRSV-CE', 'Alliance with Aram against Israel'),
(11, '1 Raj', '1 Kings', 15, 17, 'King Baasha of Israel went up against Judah, and built Ramah, to prevent anyone from going out or coming in to King Asa of Judah.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 15, 18, 'Then Asa took all the silver and the gold that were left in the treasures of the house of the LORD and the treasures of the king"s house, and gave them into the hands of his servants. King Asa sent them to King Ben-hadad son of Tabrimmon son of Hezion of Aram, who resided in Damascus, saying,', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 15, 19, '"Let there be an alliance between me and you, like that between my father and your father: I am sending you a present of silver and gold; go, break your alliance with King Baasha of Israel, so that he may withdraw from me."', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 15, 20, 'Ben-hadad listened to King Asa, and sent the commanders of his armies against the cities of Israel. He conquered Ijon, Dan, Abel-beth-maacah, and all Chinneroth, with all the land of Naphtali.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 15, 21, 'When Baasha heard of it, he stopped building Ramah and lived in Tirzah.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 15, 22, 'Then King Asa made a proclamation to all Judah, none was exempt: they carried away the stones of Ramah and its timber, with which Baasha had been building; with them King Asa built Geba of Benjamin and Mizpah.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 15, 23, 'Now the rest of all the acts of Asa, all his power, all that he did, and the cities that he built, are they not written in the Book of the Annals of the Kings of Judah? But in his old age he was diseased in his feet.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 15, 24, 'Then Asa slept with his ancestors, and was buried with his ancestors in the city of his father David; his son Jehoshaphat succeeded him.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 15, 25, 'Nadab son of Jeroboam began to reign over Israel in the second year of King Asa of Judah; he reigned over Israel two years.', 'en', 'NRSV-CE', 'Nadab Reigns over Israel'),
(11, '1 Raj', '1 Kings', 15, 26, 'He did what was evil in the sight of the LORD, walking in the way of his ancestor and in the sin that he caused Israel to commit.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 15, 27, 'Baasha son of Ahijah, of the house of Issachar, conspired against him; and Baasha struck him down at Gibbethon, which belonged to the Philistines; for Nadab and all Israel were laying siege to Gibbethon.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 15, 28, 'So Baasha killed Nadab in the third year of King Asa of Judah, and succeeded him.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 15, 29, 'As soon as he was king, he killed all the house of Jeroboam; he left to the house of Jeroboam not one that breathed, until he had destroyed it, according to the word of the LORD that he spoke by his servant Ahijah the Shilonite--', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 15, 30, 'because of the sins of Jeroboam that he committed and that he caused Israel to commit, and because of the anger to which he provoked the LORD, the God of Israel.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 15, 31, 'Now the rest of the acts of Nadab, and all that he did, are they not written in the Book of the Annals of the Kings of Israel?', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 15, 32, 'There was war between Asa and King Baasha of Israel all their days.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 15, 33, 'In the third year of King Asa of Judah, Baasha son of Ahijah began to reign over all Israel at Tirzah; he reigned twenty-four years.', 'en', 'NRSV-CE', 'Second Dynasty: Baasha Reigns over Israel'),
(11, '1 Raj', '1 Kings', 15, 34, 'He did what was evil in the sight of the LORD, walking in the way of Jeroboam and in the sin that he caused Israel to commit.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(11, '1 Raj', '1 Kings', 16, 1, 'The word of the LORD came to Jehu son of Hanani against Baasha, saying,', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 16, 2, '"Since I exalted you out of the dust and made you leader over my people Israel, and you have walked in the way of Jeroboam, and have caused my people Israel to sin, provoking me to anger with their sins,', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 16, 3, 'therefore, I will consume Baasha and his house, and I will make your house like the house of Jeroboam son of Nebat.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 16, 4, 'Anyone belonging to Baasha who dies in the city the dogs shall eat; and anyone of his who dies in the field the birds of the air shall eat."', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 16, 5, 'Now the rest of the acts of Baasha, what he did, and his power, are they not written in the Book of the Annals of the Kings of Israel?', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 16, 6, 'Baasha slept with his ancestors, and was buried at Tirzah; and his son Elah succeeded him.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 16, 7, 'Moreover the word of the LORD came by the prophet Jehu son of Hanani against Baasha and his house, both because of all the evil that he did in the sight of the LORD, provoking him to anger with the work of his hands, in being like the house of Jeroboam, and also because he destroyed it.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 16, 8, 'In the twenty-sixth year of King Asa of Judah, Elah son of Baasha began to reign over Israel in Tirzah; he reigned two years.', 'en', 'NRSV-CE', 'Elah Reigns over Israel'),
(11, '1 Raj', '1 Kings', 16, 9, 'But his servant Zimri, commander of half his chariots, conspired against him. When he was at Tirzah, drinking himself drunk in the house of Arza, who was in charge of the palace at Tirzah,', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 16, 10, 'Zimri came in and struck him down and killed him, in the twenty-seventh year of King Asa of Judah, and succeeded him.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 16, 11, 'When he began to reign, as soon as he had seated himself on his throne, he killed all the house of Baasha; he did not leave him a single male of his kindred or his friends.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 16, 12, 'Thus Zimri destroyed all the house of Baasha, according to the word of the LORD, which he spoke against Baasha by the prophet Jehu--', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 16, 13, 'because of all the sins of Baasha and the sins of his son Elah that they committed, and that they caused Israel to commit, provoking the LORD God of Israel to anger with their idols.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 16, 14, 'Now the rest of the acts of Elah, and all that he did, are they not written in the Book of the Annals of the Kings of Israel?', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 16, 15, 'In the twenty-seventh year of King Asa of Judah, Zimri reigned seven days in Tirzah. Now the troops were encamped against Gibbethon, which belonged to the Philistines,', 'en', 'NRSV-CE', 'Third Dynasty: Zimri Reigns over Israel'),
(11, '1 Raj', '1 Kings', 16, 16, 'and the troops who were encamped heard it said, "Zimri has conspired, and he has killed the king"; therefore all Israel made Omri, the commander of the army, king over Israel that day in the camp.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 16, 17, 'So Omri went up from Gibbethon, and all Israel with him, and they besieged Tirzah.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 16, 18, 'When Zimri saw that the city was taken, he went into the citadel of the king"s house; he burned down the king"s house over himself with fire, and died--', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 16, 19, 'because of the sins that he committed, doing evil in the sight of the LORD, walking in the way of Jeroboam, and for the sin that he committed, causing Israel to sin.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 16, 20, 'Now the rest of the acts of Zimri, and the conspiracy that he made, are they not written in the Book of the Annals of the Kings of Israel?', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 16, 21, 'Then the people of Israel were divided into two parts; half of the people followed Tibni son of Ginath, to make him king, and half followed Omri.', 'en', 'NRSV-CE', 'Fourth Dynasty: Omri Reigns over Israel'),
(11, '1 Raj', '1 Kings', 16, 22, 'But the people who followed Omri overcame the people who followed Tibni son of Ginath; so Tibni died, and Omri became king.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 16, 23, 'In the thirty-first year of King Asa of Judah, Omri began to reign over Israel; he reigned for twelve years, six of them in Tirzah.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 16, 24, 'He bought the hill of Samaria from Shemer for two talents of silver; he fortified the hill, and called the city that he built, Samaria, after the name of Shemer, the owner of the hill.', 'en', 'NRSV-CE', 'Samaria the New Capital'),
(11, '1 Raj', '1 Kings', 16, 25, 'Omri did what was evil in the sight of the LORD; he did more evil than all who were before him.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 16, 26, 'For he walked in all the way of Jeroboam son of Nebat, and in the sins that he caused Israel to commit, provoking the LORD, the God of Israel, to anger by their idols.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 16, 27, 'Now the rest of the acts of Omri that he did, and the power that he showed, are they not written in the Book of the Annals of the Kings of Israel?', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 16, 28, 'Omri slept with his ancestors, and was buried in Samaria; his son Ahab succeeded him.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 16, 29, 'In the thirty-eighth year of King Asa of Judah, Ahab son of Omri began to reign over Israel; Ahab son of Omri reigned over Israel in Samaria twenty-two years.', 'en', 'NRSV-CE', 'Ahab Reigns over Israel'),
(11, '1 Raj', '1 Kings', 16, 30, 'Ahab son of Omri did evil in the sight of the LORD more than all who were before him.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 16, 31, 'And as if it had been a light thing for him to walk in the sins of Jeroboam son of Nebat, he took as his wife Jezebel daughter of King Ethbaal of the Sidonians, and went and served Baal, and worshiped him.', 'en', 'NRSV-CE', 'Ahab Marries Jezebel and Worships Baal'),
(11, '1 Raj', '1 Kings', 16, 32, 'He erected an altar for Baal in the house of Baal, which he built in Samaria.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 16, 33, 'Ahab also made a sacred pole. Ahab did more to provoke the anger of the LORD, the God of Israel, than had all the kings of Israel who were before him.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 16, 34, 'In his days Hiel of Bethel built Jericho; he laid its foundation at the cost of Abiram his firstborn, and set up its gates at the cost of his youngest son Segub, according to the word of the LORD, which he spoke by Joshua son of Nun.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(11, '1 Raj', '1 Kings', 17, 1, 'Now Elijah the Tishbite, of Tishbe in Gilead, said to Ahab, "As the LORD the God of Israel lives, before whom I stand, there shall be neither dew nor rain these years, except by my word."', 'en', 'NRSV-CE', 'Elijah Predicts a Drought'),
(11, '1 Raj', '1 Kings', 17, 2, 'The word of the LORD came to him, saying,', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 17, 3, '"Go from here and turn eastward, and hide yourself by the Wadi Cherith, which is east of the Jordan.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 17, 4, 'You shall drink from the wadi, and I have commanded the ravens to feed you there."', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 17, 5, 'So he went and did according to the word of the LORD; he went and lived by the Wadi Cherith, which is east of the Jordan.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 17, 6, 'The ravens brought him bread and meat in the morning, and bread and meat in the evening; and he drank from the wadi.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 17, 7, 'But after a while the wadi dried up, because there was no rain in the land.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 17, 8, 'Then the word of the LORD came to him, saying,', 'en', 'NRSV-CE', 'The Widow of Zarephath'),
(11, '1 Raj', '1 Kings', 17, 9, '"Go now to Zarephath, which belongs to Sidon, and live there; for I have commanded a widow there to feed you."', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 17, 10, 'So he set out and went to Zarephath. When he came to the gate of the town, a widow was there gathering sticks; he called to her and said, "Bring me a little water in a vessel, so that I may drink."', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 17, 11, 'As she was going to bring it, he called to her and said, "Bring me a morsel of bread in your hand."', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 17, 12, 'But she said, "As the LORD your God lives, I have nothing baked, only a handful of meal in a jar, and a little oil in a jug; I am now gathering a couple of sticks, so that I may go home and prepare it for myself and my son, that we may eat it, and die."', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 17, 13, 'Elijah said to her, "Do not be afraid; go and do as you have said; but first make me a little cake of it and bring it to me, and afterwards make something for yourself and your son.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 17, 14, 'For thus says the LORD the God of Israel: The jar of meal will not be emptied and the jug of oil will not fail until the day that the LORD sends rain on the earth."', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 17, 15, 'She went and did as Elijah said, so that she as well as he and her household ate for many days.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 17, 16, 'The jar of meal was not emptied, neither did the jug of oil fail, according to the word of the LORD that he spoke by Elijah.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 17, 17, 'After this the son of the woman, the mistress of the house, became ill; his illness was so severe that there was no breath left in him.', 'en', 'NRSV-CE', 'Elijah Revives the Widow"s Son'),
(11, '1 Raj', '1 Kings', 17, 18, 'She then said to Elijah, "What have you against me, O man of God? You have come to me to bring my sin to remembrance, and to cause the death of my son!"', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 17, 19, 'But he said to her, "Give me your son." He took him from her bosom, carried him up into the upper chamber where he was lodging, and laid him on his own bed.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 17, 20, 'He cried out to the LORD, "O LORD my God, have you brought calamity even upon the widow with whom I am staying, by killing her son?"', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 17, 21, 'Then he stretched himself upon the child three times, and cried out to the LORD, "O LORD my God, let this child"s life come into him again."', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 17, 22, 'The LORD listened to the voice of Elijah; the life of the child came into him again, and he revived.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 17, 23, 'Elijah took the child, brought him down from the upper chamber into the house, and gave him to his mother; then Elijah said, "See, your son is alive."', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 17, 24, 'So the woman said to Elijah, "Now I know that you are a man of God, and that the word of the LORD in your mouth is truth."', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(11, '1 Raj', '1 Kings', 18, 1, 'After many days the word of the LORD came to Elijah, in the third year of the drought, saying, "Go, present yourself to Ahab; I will send rain on the earth."', 'en', 'NRSV-CE', 'Elijah"s Message to Ahab'),
(11, '1 Raj', '1 Kings', 18, 2, 'So Elijah went to present himself to Ahab. The famine was severe in Samaria.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 18, 3, 'Ahab summoned Obadiah, who was in charge of the palace. (Now Obadiah revered the LORD greatly;', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 18, 4, 'when Jezebel was killing off the prophets of the LORD, Obadiah took a hundred prophets, hid them fifty to a cave, and provided them with bread and water.)', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 18, 5, 'Then Ahab said to Obadiah, "Go through the land to all the springs of water and to all the wadis; perhaps we may find grass to keep the horses and mules alive, and not lose some of the animals."', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 18, 6, 'So they divided the land between them to pass through it; Ahab went in one direction by himself, and Obadiah went in another direction by himself.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 18, 7, 'As Obadiah was on the way, Elijah met him; Obadiah recognized him, fell on his face, and said, "Is it you, my lord Elijah?"', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 18, 8, 'He answered him, "It is I. Go, tell your lord that Elijah is here."', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 18, 9, 'And he said, "How have I sinned, that you would hand your servant over to Ahab, to kill me?', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 18, 10, 'As the LORD your God lives, there is no nation or kingdom to which my lord has not sent to seek you; and when they would say, "He is not here," he would require an oath of the kingdom or nation, that they had not found you.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 18, 11, 'But now you say, "Go, tell your lord that Elijah is here."', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 18, 12, 'As soon as I have gone from you, the spirit of the LORD will carry you I know not where; so, when I come and tell Ahab and he cannot find you, he will kill me, although I your servant have revered the LORD from my youth.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 18, 13, 'Has it not been told my lord what I did when Jezebel killed the prophets of the LORD, how I hid a hundred of the LORD"s prophets fifty to a cave, and provided them with bread and water?', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 18, 14, 'Yet now you say, "Go, tell your lord that Elijah is here"; he will surely kill me."', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 18, 15, 'Elijah said, "As the LORD of hosts lives, before whom I stand, I will surely show myself to him today."', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 18, 16, 'So Obadiah went to meet Ahab, and told him; and Ahab went to meet Elijah.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 18, 17, 'When Ahab saw Elijah, Ahab said to him, "Is it you, you troubler of Israel?"', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 18, 18, 'He answered, "I have not troubled Israel; but you have, and your father"s house, because you have forsaken the commandments of the LORD and followed the Baals.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 18, 19, 'Now therefore have all Israel assemble for me at Mount Carmel, with the four hundred fifty prophets of Baal and the four hundred prophets of Asherah, who eat at Jezebel"s table."', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 18, 20, 'So Ahab sent to all the Israelites, and assembled the prophets at Mount Carmel.', 'en', 'NRSV-CE', 'Elijah"s Triumph over the Priests of Baal'),
(11, '1 Raj', '1 Kings', 18, 21, 'Elijah then came near to all the people, and said, "How long will you go limping with two different opinions? If the LORD is God, follow him; but if Baal, then follow him." The people did not answer him a word.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 18, 22, 'Then Elijah said to the people, "I, even I only, am left a prophet of the LORD; but Baal"s prophets number four hundred fifty.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 18, 23, 'Let two bulls be given to us; let them choose one bull for themselves, cut it in pieces, and lay it on the wood, but put no fire to it; I will prepare the other bull and lay it on the wood, but put no fire to it.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 18, 24, 'Then you call on the name of your god and I will call on the name of the LORD; the god who answers by fire is indeed God." All the people answered, "Well spoken!"', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 18, 25, 'Then Elijah said to the prophets of Baal, "Choose for yourselves one bull and prepare it first, for you are many; then call on the name of your god, but put no fire to it."', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 18, 26, 'So they took the bull that was given them, prepared it, and called on the name of Baal from morning until noon, crying, "O Baal, answer us!" But there was no voice, and no answer. They limped about the altar that they had made.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 18, 27, 'At noon Elijah mocked them, saying, "Cry aloud! Surely he is a god; either he is meditating, or he has wandered away, or he is on a journey, or perhaps he is asleep and must be awakened."', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 18, 28, 'Then they cried aloud and, as was their custom, they cut themselves with swords and lances until the blood gushed out over them.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 18, 29, 'As midday passed, they raved on until the time of the offering of the oblation, but there was no voice, no answer, and no response.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 18, 30, 'Then Elijah said to all the people, "Come closer to me"; and all the people came closer to him. First he repaired the altar of the LORD that had been thrown down;', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 18, 31, 'Elijah took twelve stones, according to the number of the tribes of the sons of Jacob, to whom the word of the LORD came, saying, "Israel shall be your name";', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 18, 32, 'with the stones he built an altar in the name of the LORD. Then he made a trench around the altar, large enough to contain two measures of seed.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 18, 33, 'Next he put the wood in order, cut the bull in pieces, and laid it on the wood. He said, "Fill four jars with water and pour it on the burnt offering and on the wood."', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 18, 34, 'Then he said, "Do it a second time"; and they did it a second time. Again he said, "Do it a third time"; and they did it a third time,', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 18, 35, 'so that the water ran all around the altar, and filled the trench also with water.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 18, 36, 'At the time of the offering of the oblation, the prophet Elijah came near and said, "O LORD, God of Abraham, Isaac, and Israel, let it be known this day that you are God in Israel, that I am your servant, and that I have done all these things at your bidding.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 18, 37, 'Answer me, O LORD, answer me, so that this people may know that you, O LORD, are God, and that you have turned their hearts back."', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 18, 38, 'Then the fire of the LORD fell and consumed the burnt offering, the wood, the stones, and the dust, and even licked up the water that was in the trench.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 18, 39, 'When all the people saw it, they fell on their faces and said, "The LORD indeed is God; the LORD indeed is God."', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 18, 40, 'Elijah said to them, "Seize the prophets of Baal; do not let one of them escape." Then they seized them; and Elijah brought them down to the Wadi Kishon, and killed them there.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 18, 41, 'Elijah said to Ahab, "Go up, eat and drink; for there is a sound of rushing rain."', 'en', 'NRSV-CE', 'The Drought Ends'),
(11, '1 Raj', '1 Kings', 18, 42, 'So Ahab went up to eat and to drink. Elijah went up to the top of Carmel; there he bowed himself down upon the earth and put his face between his knees.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 18, 43, 'He said to his servant, "Go up now, look toward the sea." He went up and looked, and said, "There is nothing." Then he said, "Go again seven times."', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 18, 44, 'At the seventh time he said, "Look, a little cloud no bigger than a person"s hand is rising out of the sea." Then he said, "Go say to Ahab, "Harness your chariot and go down before the rain stops you.""', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 18, 45, 'In a little while the heavens grew black with clouds and wind; there was a heavy rain. Ahab rode off and went to Jezreel.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 18, 46, 'But the hand of the LORD was on Elijah; he girded up his loins and ran in front of Ahab to the entrance of Jezreel.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(11, '1 Raj', '1 Kings', 19, 1, 'Ahab told Jezebel all that Elijah had done, and how he had killed all the prophets with the sword.', 'en', 'NRSV-CE', 'Elijah Flees from Jezebel'),
(11, '1 Raj', '1 Kings', 19, 2, 'Then Jezebel sent a messenger to Elijah, saying, "So may the gods do to me, and more also, if I do not make your life like the life of one of them by this time tomorrow."', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 19, 3, 'Then he was afraid; he got up and fled for his life, and came to Beer-sheba, which belongs to Judah; he left his servant there.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 19, 4, 'But he himself went a day"s journey into the wilderness, and came and sat down under a solitary broom tree. He asked that he might die: "It is enough; now, O LORD, take away my life, for I am no better than my ancestors."', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 19, 5, 'Then he lay down under the broom tree and fell asleep. Suddenly an angel touched him and said to him, "Get up and eat."', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 19, 6, 'He looked, and there at his head was a cake baked on hot stones, and a jar of water. He ate and drank, and lay down again.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 19, 7, 'The angel of the LORD came a second time, touched him, and said, "Get up and eat, otherwise the journey will be too much for you."', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 19, 8, 'He got up, and ate and drank; then he went in the strength of that food forty days and forty nights to Horeb the mount of God.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 19, 9, 'At that place he came to a cave, and spent the night there.
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(11, '1 Raj', '1 Kings', 20, 1, 'King Ben-hadad of Aram gathered all his army together; thirty-two kings were with him, along with horses and chariots. He marched against Samaria, laid siege to it, and attacked it.', 'en', 'NRSV-CE', 'Ahab"s Wars with the Arameans'),
(11, '1 Raj', '1 Kings', 20, 2, 'Then he sent messengers into the city to King Ahab of Israel, and said to him: "Thus says Ben-hadad:', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 20, 3, 'Your silver and gold are mine; your fairest wives and children also are mine."', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 20, 4, 'The king of Israel answered, "As you say, my lord, O king, I am yours, and all that I have."', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 20, 5, 'The messengers came again and said: "Thus says Ben-hadad: I sent to you, saying, "Deliver to me your silver and gold, your wives and children";', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 20, 6, 'nevertheless I will send my servants to you tomorrow about this time, and they shall search your house and the houses of your servants, and lay hands on whatever pleases them, and take it away."', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 20, 7, 'Then the king of Israel called all the elders of the land, and said, "Look now! See how this man is seeking trouble; for he sent to me for my wives, my children, my silver, and my gold; and I did not refuse him."', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 20, 8, 'Then all the elders and all the people said to him, "Do not listen or consent."', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 20, 9, 'So he said to the messengers of Ben-hadad, "Tell my lord the king: All that you first demanded of your servant I will do; but this thing I cannot do." The messengers left and brought him word again.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 20, 10, 'Ben-hadad sent to him and said, "The gods do so to me, and more also, if the dust of Samaria will provide a handful for each of the people who follow me."', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 20, 11, 'The king of Israel answered, "Tell him: One who puts on armor should not brag like one who takes it off."', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 20, 12, 'When Ben-hadad heard this message--now he had been drinking with the kings in the booths--he said to his men, "Take your positions!" And they took their positions against the city.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 20, 13, 'Then a certain prophet came up to King Ahab of Israel and said, "Thus says the LORD, Have you seen all this great multitude? Look, I will give it into your hand today; and you shall know that I am the LORD."', 'en', 'NRSV-CE', 'Prophetic Opposition to Ahab'),
(11, '1 Raj', '1 Kings', 20, 14, 'Ahab said, "By whom?" He said, "Thus says the LORD, By the young men who serve the district governors." Then he said, "Who shall begin the battle?" He answered, "You."', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 20, 15, 'Then he mustered the young men who served the district governors, two hundred thirty-two; after them he mustered all the people of Israel, seven thousand.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 20, 16, 'They went out at noon, while Ben-hadad was drinking himself drunk in the booths, he and the thirty-two kings allied with him.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 20, 17, 'The young men who served the district governors went out first. Ben-hadad had sent out scouts, and they reported to him, "Men have come out from Samaria."', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 20, 18, 'He said, "If they have come out for peace, take them alive; if they have come out for war, take them alive."', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 20, 19, 'But these had already come out of the city: the young men who served the district governors, and the army that followed them.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 20, 20, 'Each killed his man; the Arameans fled and Israel pursued them, but King Ben-hadad of Aram escaped on a horse with the cavalry.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 20, 21, 'The king of Israel went out, attacked the horses and chariots, and defeated the Arameans with a great slaughter.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 20, 22, 'Then the prophet approached the king of Israel and said to him, "Come, strengthen yourself, and consider well what you have to do; for in the spring the king of Aram will come up against you."', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 20, 23, 'The servants of the king of Aram said to him, "Their gods are gods of the hills, and so they were stronger than we; but let us fight against them in the plain, and surely we shall be stronger than they.', 'en', 'NRSV-CE', 'The Arameans Are Defeated'),
(11, '1 Raj', '1 Kings', 20, 24, 'Also do this: remove the kings, each from his post, and put commanders in place of them;', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 20, 25, 'and muster an army like the army that you have lost, horse for horse, and chariot for chariot; then we will fight against them in the plain, and surely we shall be stronger than they." He heeded their voice, and did so.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 20, 26, 'In the spring Ben-hadad mustered the Arameans and went up to Aphek to fight against Israel.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 20, 27, 'After the Israelites had been mustered and provisioned, they went out to engage them; the people of Israel encamped opposite them like two little flocks of goats, while the Arameans filled the country.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 20, 28, 'A man of God approached and said to the king of Israel, "Thus says the LORD: Because the Arameans have said, "The LORD is a god of the hills but he is not a god of the valleys," therefore I will give all this great multitude into your hand, and you shall know that I am the LORD."', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 20, 29, 'They encamped opposite one another seven days. Then on the seventh day the battle began; the Israelites killed one hundred thousand Aramean foot soldiers in one day.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 20, 30, 'The rest fled into the city of Aphek; and the wall fell on twenty-seven thousand men that were left.
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(11, '1 Raj', '1 Kings', 21, 1, 'Later the following events took place: Naboth the Jezreelite had a vineyard in Jezreel, beside the palace of King Ahab of Samaria.', 'en', 'NRSV-CE', 'Naboth"s Vineyard'),
(11, '1 Raj', '1 Kings', 21, 2, 'And Ahab said to Naboth, "Give me your vineyard, so that I may have it for a vegetable garden, because it is near my house; I will give you a better vineyard for it; or, if it seems good to you, I will give you its value in money."', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 21, 3, 'But Naboth said to Ahab, "The LORD forbid that I should give you my ancestral inheritance."', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 21, 4, 'Ahab went home resentful and sullen because of what Naboth the Jezreelite had said to him; for he had said, "I will not give you my ancestral inheritance." He lay down on his bed, turned away his face, and would not eat.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 21, 5, 'His wife Jezebel came to him and said, "Why are you so depressed that you will not eat?"', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 21, 6, 'He said to her, "Because I spoke to Naboth the Jezreelite and said to him, "Give me your vineyard for money; or else, if you prefer, I will give you another vineyard for it"; but he answered, "I will not give you my vineyard.""', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 21, 7, 'His wife Jezebel said to him, "Do you now govern Israel? Get up, eat some food, and be cheerful; I will give you the vineyard of Naboth the Jezreelite."', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 21, 8, 'So she wrote letters in Ahab"s name and sealed them with his seal; she sent the letters to the elders and the nobles who lived with Naboth in his city.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 21, 9, 'She wrote in the letters, "Proclaim a fast, and seat Naboth at the head of the assembly;', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 21, 10, 'seat two scoundrels opposite him, and have them bring a charge against him, saying, "You have cursed God and the king." Then take him out, and stone him to death."', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 21, 11, 'The men of his city, the elders and the nobles who lived in his city, did as Jezebel had sent word to them. Just as it was written in the letters that she had sent to them,', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 21, 12, 'they proclaimed a fast and seated Naboth at the head of the assembly.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 21, 13, 'The two scoundrels came in and sat opposite him; and the scoundrels brought a charge against Naboth, in the presence of the people, saying, "Naboth cursed God and the king." So they took him outside the city, and stoned him to death.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 21, 14, 'Then they sent to Jezebel, saying, "Naboth has been stoned; he is dead."', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 21, 15, 'As soon as Jezebel heard that Naboth had been stoned and was dead, Jezebel said to Ahab, "Go, take possession of the vineyard of Naboth the Jezreelite, which he refused to give you for money; for Naboth is not alive, but dead."', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 21, 16, 'As soon as Ahab heard that Naboth was dead, Ahab set out to go down to the vineyard of Naboth the Jezreelite, to take possession of it.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 21, 17, 'Then the word of the LORD came to Elijah the Tishbite, saying:', 'en', 'NRSV-CE', 'Elijah Pronounces God"s Sentence'),
(11, '1 Raj', '1 Kings', 21, 18, 'Go down to meet King Ahab of Israel, who rules in Samaria; he is now in the vineyard of Naboth, where he has gone to take possession.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 21, 19, 'You shall say to him, "Thus says the LORD: Have you killed, and also taken possession?" You shall say to him, "Thus says the LORD: In the place where dogs licked up the blood of Naboth, dogs will also lick up your blood."', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 21, 20, 'Ahab said to Elijah, "Have you found me, O my enemy?" He answered, "I have found you. Because you have sold yourself to do what is evil in the sight of the LORD,', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 21, 21, 'I will bring disaster on you; I will consume you, and will cut off from Ahab every male, bond or free, in Israel;', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 21, 22, 'and I will make your house like the house of Jeroboam son of Nebat, and like the house of Baasha son of Ahijah, because you have provoked me to anger and have caused Israel to sin.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 21, 23, 'Also concerning Jezebel the LORD said, "The dogs shall eat Jezebel within the bounds of Jezreel."', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 21, 24, 'Anyone belonging to Ahab who dies in the city the dogs shall eat; and anyone of his who dies in the open country the birds of the air shall eat."', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 21, 25, '(Indeed, there was no one like Ahab, who sold himself to do what was evil in the sight of the LORD, urged on by his wife Jezebel.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 21, 26, 'He acted most abominably in going after idols, as the Amorites had done, whom the LORD drove out before the Israelites.)', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 21, 27, 'When Ahab heard those words, he tore his clothes and put sackcloth over his bare flesh; he fasted, lay in the sackcloth, and went about dejectedly.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 21, 28, 'Then the word of the LORD came to Elijah the Tishbite:', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 21, 29, '"Have you seen how Ahab has humbled himself before me? Because he has humbled himself before me, I will not bring the disaster in his days; but in his son"s days I will bring the disaster on his house."', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(11, '1 Raj', '1 Kings', 22, 1, 'For three years Aram and Israel continued without war.', 'en', 'NRSV-CE', 'Joint Campaign with Judah against Aram'),
(11, '1 Raj', '1 Kings', 22, 2, 'But in the third year King Jehoshaphat of Judah came down to the king of Israel.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 22, 3, 'The king of Israel said to his servants, "Do you know that Ramoth-gilead belongs to us, yet we are doing nothing to take it out of the hand of the king of Aram?"', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 22, 4, 'He said to Jehoshaphat, "Will you go with me to battle at Ramoth-gilead?" Jehoshaphat replied to the king of Israel, "I am as you are; my people are your people, my horses are your horses."', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 22, 5, 'But Jehoshaphat also said to the king of Israel, "Inquire first for the word of the LORD."', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 22, 6, 'Then the king of Israel gathered the prophets together, about four hundred of them, and said to them, "Shall I go to battle against Ramoth-gilead, or shall I refrain?" They said, "Go up; for the LORD will give it into the hand of the king."', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 22, 7, 'But Jehoshaphat said, "Is there no other prophet of the LORD here of whom we may inquire?"', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 22, 8, 'The king of Israel said to Jehoshaphat, "There is still one other by whom we may inquire of the LORD, Micaiah son of Imlah; but I hate him, for he never prophesies anything favorable about me, but only disaster." Jehoshaphat said, "Let the king not say such a thing."', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 22, 9, 'Then the king of Israel summoned an officer and said, "Bring quickly Micaiah son of Imlah."', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 22, 10, 'Now the king of Israel and King Jehoshaphat of Judah were sitting on their thrones, arrayed in their robes, at the threshing floor at the entrance of the gate of Samaria; and all the prophets were prophesying before them.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 22, 11, 'Zedekiah son of Chenaanah made for himself horns of iron, and he said, "Thus says the LORD: With these you shall gore the Arameans until they are destroyed."', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 22, 12, 'All the prophets were prophesying the same and saying, "Go up to Ramoth-gilead and triumph; the LORD will give it into the hand of the king."', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 22, 13, 'The messenger who had gone to summon Micaiah said to him, "Look, the words of the prophets with one accord are favorable to the king; let your word be like the word of one of them, and speak favorably."', 'en', 'NRSV-CE', 'Micaiah Predicts Failure'),
(11, '1 Raj', '1 Kings', 22, 14, 'But Micaiah said, "As the LORD lives, whatever the LORD says to me, that I will speak."', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 22, 15, 'When he had come to the king, the king said to him, "Micaiah, shall we go to Ramoth-gilead to battle, or shall we refrain?" He answered him, "Go up and triumph; the LORD will give it into the hand of the king."', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 22, 16, 'But the king said to him, "How many times must I make you swear to tell me nothing but the truth in the name of the LORD?"', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 22, 17, 'Then Micaiah said, "I saw all Israel scattered on the mountains, like sheep that have no shepherd; and the LORD said, "These have no master; let each one go home in peace.""', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 22, 18, 'The king of Israel said to Jehoshaphat, "Did I not tell you that he would not prophesy anything favorable about me, but only disaster?"', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 22, 19, 'Then Micaiah said, "Therefore hear the word of the LORD: I saw the LORD sitting on his throne, with all the host of heaven standing beside him to the right and to the left of him.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 22, 20, 'And the LORD said, "Who will entice Ahab, so that he may go up and fall at Ramoth-gilead?" Then one said one thing, and another said another,', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 22, 21, 'until a spirit came forward and stood before the LORD, saying, "I will entice him."', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 22, 22, '"How?" the LORD asked him. He replied, "I will go out and be a lying spirit in the mouth of all his prophets." Then the LORD said, "You are to entice him, and you shall succeed; go out and do it."', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 22, 23, 'So you see, the LORD has put a lying spirit in the mouth of all these your prophets; the LORD has decreed disaster for you."', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 22, 24, 'Then Zedekiah son of Chenaanah came up to Micaiah, slapped him on the cheek, and said, "Which way did the spirit of the LORD pass from me to speak to you?"', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 22, 25, 'Micaiah replied, "You will find out on that day when you go in to hide in an inner chamber."', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 22, 26, 'The king of Israel then ordered, "Take Micaiah, and return him to Amon the governor of the city and to Joash the king"s son,', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 22, 27, 'and say, "Thus says the king: Put this fellow in prison, and feed him on reduced rations of bread and water until I come in peace.""', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 22, 28, 'Micaiah said, "If you return in peace, the LORD has not spoken by me." And he said, "Hear, you peoples, all of you!"', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 22, 29, 'So the king of Israel and King Jehoshaphat of Judah went up to Ramoth-gilead.', 'en', 'NRSV-CE', 'Defeat and Death of Ahab'),
(11, '1 Raj', '1 Kings', 22, 30, 'The king of Israel said to Jehoshaphat, "I will disguise myself and go into battle, but you wear your robes." So the king of Israel disguised himself and went into battle.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 22, 31, 'Now the king of Aram had commanded the thirty-two captains of his chariots, "Fight with no one small or great, but only with the king of Israel."', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 22, 32, 'When the captains of the chariots saw Jehoshaphat, they said, "It is surely the king of Israel." So they turned to fight against him; and Jehoshaphat cried out.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 22, 33, 'When the captains of the chariots saw that it was not the king of Israel, they turned back from pursuing him.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 22, 34, 'But a certain man drew his bow and unknowingly struck the king of Israel between the scale armor and the breastplate; so he said to the driver of his chariot, "Turn around, and carry me out of the battle, for I am wounded."', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 22, 35, 'The battle grew hot that day, and the king was propped up in his chariot facing the Arameans, until at evening he died; the blood from the wound had flowed into the bottom of the chariot.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 22, 36, 'Then about sunset a shout went through the army, "Every man to his city, and every man to his country!"', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 22, 37, 'So the king died, and was brought to Samaria; they buried the king in Samaria.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 22, 38, 'They washed the chariot by the pool of Samaria; the dogs licked up his blood, and the prostitutes washed themselves in it, according to the word of the LORD that he had spoken.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 22, 39, 'Now the rest of the acts of Ahab, and all that he did, and the ivory house that he built, and all the cities that he built, are they not written in the Book of the Annals of the Kings of Israel?', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 22, 40, 'So Ahab slept with his ancestors; and his son Ahaziah succeeded him.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 22, 41, 'Jehoshaphat son of Asa began to reign over Judah in the fourth year of King Ahab of Israel.', 'en', 'NRSV-CE', 'Jehoshaphat Reigns over Judah'),
(11, '1 Raj', '1 Kings', 22, 42, 'Jehoshaphat was thirty-five years old when he began to reign, and he reigned twenty-five years in Jerusalem. His mother"s name was Azubah daughter of Shilhi.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 22, 43, 'He walked in all the way of his father Asa; he did not turn aside from it, doing what was right in the sight of the LORD; yet the high places were not taken away, and the people still sacrificed and offered incense on the high places.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 22, 44, 'Jehoshaphat also made peace with the king of Israel.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 22, 45, 'Now the rest of the acts of Jehoshaphat, and his power that he showed, and how he waged war, are they not written in the Book of the Annals of the Kings of Judah?', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 22, 46, 'The remnant of the male temple prostitutes who were still in the land in the days of his father Asa, he exterminated.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 22, 47, 'There was no king in Edom; a deputy was king.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 22, 48, 'Jehoshaphat made ships of the Tarshish type to go to Ophir for gold; but they did not go, for the ships were wrecked at Ezion-geber.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 22, 49, 'Then Ahaziah son of Ahab said to Jehoshaphat, "Let my servants go with your servants in the ships," but Jehoshaphat was not willing.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 22, 50, 'Jehoshaphat slept with his ancestors and was buried with his ancestors in the city of his father David; his son Jehoram succeeded him.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 22, 51, 'Ahaziah son of Ahab began to reign over Israel in Samaria in the seventeenth year of King Jehoshaphat of Judah; he reigned two years over Israel.', 'en', 'NRSV-CE', 'Ahaziah Reigns over Israel'),
(11, '1 Raj', '1 Kings', 22, 52, 'He did what was evil in the sight of the LORD, and walked in the way of his father and mother, and in the way of Jeroboam son of Nebat, who caused Israel to sin.', 'en', 'NRSV-CE', NULL),
(11, '1 Raj', '1 Kings', 22, 53, 'He served Baal and worshiped him; he provoked the LORD, the God of Israel, to anger, just as his father had done.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(12, '2 Raj', '2 Kings', 1, 1, 'After the death of Ahab, Moab rebelled against Israel.', 'en', 'NRSV-CE', 'Elijah Denounces Ahaziah'),
(12, '2 Raj', '2 Kings', 1, 2, 'Ahaziah had fallen through the lattice in his upper chamber in Samaria, and lay injured; so he sent messengers, telling them, "Go, inquire of Baal-zebub, the god of Ekron, whether I shall recover from this injury."', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 1, 3, 'But the angel of the LORD said to Elijah the Tishbite, "Get up, go to meet the messengers of the king of Samaria, and say to them, "Is it because there is no God in Israel that you are going to inquire of Baal-zebub, the god of Ekron?"', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 1, 4, 'Now therefore thus says the LORD, "You shall not leave the bed to which you have gone, but you shall surely die."" So Elijah went.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 1, 5, 'The messengers returned to the king, who said to them, "Why have you returned?"', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 1, 6, 'They answered him, "There came a man to meet us, who said to us, "Go back to the king who sent you, and say to him: Thus says the LORD: Is it because there is no God in Israel that you are sending to inquire of Baal-zebub, the god of Ekron? Therefore you shall not leave the bed to which you have gone, but shall surely die.""', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 1, 7, 'He said to them, "What sort of man was he who came to meet you and told you these things?"', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 1, 8, 'They answered him, "A hairy man, with a leather belt around his waist." He said, "It is Elijah the Tishbite."', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 1, 9, 'Then the king sent to him a captain of fifty with his fifty men. He went up to Elijah, who was sitting on the top of a hill, and said to him, "O man of God, the king says, "Come down.""', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 1, 10, 'But Elijah answered the captain of fifty, "If I am a man of God, let fire come down from heaven and consume you and your fifty." Then fire came down from heaven, and consumed him and his fifty.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 1, 11, 'Again the king sent to him another captain of fifty with his fifty. He went up and said to him, "O man of God, this is the king"s order: Come down quickly!"', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 1, 12, 'But Elijah answered them, "If I am a man of God, let fire come down from heaven and consume you and your fifty." Then the fire of God came down from heaven and consumed him and his fifty.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 1, 13, 'Again the king sent the captain of a third fifty with his fifty. So the third captain of fifty went up, and came and fell on his knees before Elijah, and entreated him, "O man of God, please let my life, and the life of these fifty servants of yours, be precious in your sight.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 1, 14, 'Look, fire came down from heaven and consumed the two former captains of fifty men with their fifties; but now let my life be precious in your sight."', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 1, 15, 'Then the angel of the LORD said to Elijah, "Go down with him; do not be afraid of him." So he set out and went down with him to the king,', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 1, 16, 'and said to him, "Thus says the LORD: Because you have sent messengers to inquire of Baal-zebub, the god of Ekron,--is it because there is no God in Israel to inquire of his word?--therefore you shall not leave the bed to which you have gone, but you shall surely die."', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 1, 17, 'So he died according to the word of the LORD that Elijah had spoken. His brother, Jehoram succeeded him as king in the second year of King Jehoram son of Jehoshaphat of Judah, because Ahaziah had no son.', 'en', 'NRSV-CE', 'Death of Ahaziah'),
(12, '2 Raj', '2 Kings', 1, 18, 'Now the rest of the acts of Ahaziah that he did, are they not written in the Book of the Annals of the Kings of Israel?', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(12, '2 Raj', '2 Kings', 2, 1, 'Now when the LORD was about to take Elijah up to heaven by a whirlwind, Elijah and Elisha were on their way from Gilgal.', 'en', 'NRSV-CE', 'Elijah Ascends to Heaven'),
(12, '2 Raj', '2 Kings', 2, 2, 'Elijah said to Elisha, "Stay here; for the LORD has sent me as far as Bethel." But Elisha said, "As the LORD lives, and as you yourself live, I will not leave you." So they went down to Bethel.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 2, 3, 'The company of prophets who were in Bethel came out to Elisha, and said to him, "Do you know that today the LORD will take your master away from you?" And he said, "Yes, I know; keep silent."', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 2, 4, 'Elijah said to him, "Elisha, stay here; for the LORD has sent me to Jericho." But he said, "As the LORD lives, and as you yourself live, I will not leave you." So they came to Jericho.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 2, 5, 'The company of prophets who were at Jericho drew near to Elisha, and said to him, "Do you know that today the LORD will take your master away from you?" And he answered, "Yes, I know; be silent."', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 2, 6, 'Then Elijah said to him, "Stay here; for the LORD has sent me to the Jordan." But he said, "As the LORD lives, and as you yourself live, I will not leave you." So the two of them went on.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 2, 7, 'Fifty men of the company of prophets also went, and stood at some distance from them, as they both were standing by the Jordan.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 2, 8, 'Then Elijah took his mantle and rolled it up, and struck the water; the water was parted to the one side and to the other, until the two of them crossed on dry ground.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 2, 9, 'When they had crossed, Elijah said to Elisha, "Tell me what I may do for you, before I am taken from you." Elisha said, "Please let me inherit a double share of your spirit."', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 2, 10, 'He responded, "You have asked a hard thing; yet, if you see me as I am being taken from you, it will be granted you; if not, it will not."', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 2, 11, 'As they continued walking and talking, a chariot of fire and horses of fire separated the two of them, and Elijah ascended in a whirlwind into heaven.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 2, 12, 'Elisha kept watching and crying out, "Father, father! The chariots of Israel and its horsemen!" But when he could no longer see him, he grasped his own clothes and tore them in two pieces.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 2, 13, 'He picked up the mantle of Elijah that had fallen from him, and went back and stood on the bank of the Jordan.', 'en', 'NRSV-CE', 'Elisha Succeeds Elijah'),
(12, '2 Raj', '2 Kings', 2, 14, 'He took the mantle of Elijah that had fallen from him, and struck the water, saying, "Where is the LORD, the God of Elijah?" When he had struck the water, the water was parted to the one side and to the other, and Elisha went over.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 2, 15, 'When the company of prophets who were at Jericho saw him at a distance, they declared, "The spirit of Elijah rests on Elisha." They came to meet him and bowed to the ground before him.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 2, 16, 'They said to him, "See now, we have fifty strong men among your servants; please let them go and seek your master; it may be that the spirit of the LORD has caught him up and thrown him down on some mountain or into some valley." He responded, "No, do not send them."', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 2, 17, 'But when they urged him until he was ashamed, he said, "Send them." So they sent fifty men who searched for three days but did not find him.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 2, 18, 'When they came back to him (he had remained at Jericho), he said to them, "Did I not say to you, Do not go?"', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 2, 19, 'Now the people of the city said to Elisha, "The location of this city is good, as my lord sees; but the water is bad, and the land is unfruitful."', 'en', 'NRSV-CE', 'Elisha Performs Miracles'),
(12, '2 Raj', '2 Kings', 2, 20, 'He said, "Bring me a new bowl, and put salt in it." So they brought it to him.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 2, 21, 'Then he went to the spring of water and threw the salt into it, and said, "Thus says the LORD, I have made this water wholesome; from now on neither death nor miscarriage shall come from it."', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 2, 22, 'So the water has been wholesome to this day, according to the word that Elisha spoke.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 2, 23, 'He went up from there to Bethel; and while he was going up on the way, some small boys came out of the city and jeered at him, saying, "Go away, baldhead! Go away, baldhead!"', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 2, 24, 'When he turned around and saw them, he cursed them in the name of the LORD. Then two she-bears came out of the woods and mauled forty-two of the boys.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 2, 25, 'From there he went on to Mount Carmel, and then returned to Samaria.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(12, '2 Raj', '2 Kings', 3, 1, 'In the eighteenth year of King Jehoshaphat of Judah, Jehoram son of Ahab became king over Israel in Samaria; he reigned twelve years.', 'en', 'NRSV-CE', 'Jehoram Reigns over Israel'),
(12, '2 Raj', '2 Kings', 3, 2, 'He did what was evil in the sight of the LORD, though not like his father and mother, for he removed the pillar of Baal that his father had made.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 3, 3, 'Nevertheless he clung to the sin of Jeroboam son of Nebat, which he caused Israel to commit; he did not depart from it.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 3, 4, 'Now King Mesha of Moab was a sheep breeder, who used to deliver to the king of Israel one hundred thousand lambs, and the wool of one hundred thousand rams.', 'en', 'NRSV-CE', 'War with Moab'),
(12, '2 Raj', '2 Kings', 3, 5, 'But when Ahab died, the king of Moab rebelled against the king of Israel.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 3, 6, 'So King Jehoram marched out of Samaria at that time and mustered all Israel.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 3, 7, 'As he went he sent word to King Jehoshaphat of Judah, "The king of Moab has rebelled against me; will you go with me to battle against Moab?" He answered, "I will; I am with you, my people are your people, my horses are your horses."', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 3, 8, 'Then he asked, "By which way shall we march?" Jehoram answered, "By the way of the wilderness of Edom."', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 3, 9, 'So the king of Israel, the king of Judah, and the king of Edom set out; and when they had made a roundabout march of seven days, there was no water for the army or for the animals that were with them.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 3, 10, 'Then the king of Israel said, "Alas! The LORD has summoned us, three kings, only to be handed over to Moab."', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 3, 11, 'But Jehoshaphat said, "Is there no prophet of the LORD here, through whom we may inquire of the LORD?" Then one of the servants of the king of Israel answered, "Elisha son of Shaphat, who used to pour water on the hands of Elijah, is here."', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 3, 12, 'Jehoshaphat said, "The word of the LORD is with him." So the king of Israel and Jehoshaphat and the king of Edom went down to him.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 3, 13, 'Elisha said to the king of Israel, "What have I to do with you? Go to your father"s prophets or to your mother"s." But the king of Israel said to him, "No; it is the LORD who has summoned us, three kings, only to be handed over to Moab."', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 3, 14, 'Elisha said, "As the LORD of hosts lives, whom I serve, were it not that I have regard for King Jehoshaphat of Judah, I would give you neither a look nor a glance.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 3, 15, 'But get me a musician." And then, while the musician was playing, the power of the LORD came on him.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 3, 16, 'And he said, "Thus says the LORD, "I will make this wadi full of pools."', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 3, 17, 'For thus says the LORD, "You shall see neither wind nor rain, but the wadi shall be filled with water, so that you shall drink, you, your cattle, and your animals."', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 3, 18, 'This is only a trifle in the sight of the LORD, for he will also hand Moab over to you.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 3, 19, 'You shall conquer every fortified city and every choice city; every good tree you shall fell, all springs of water you shall stop up, and every good piece of land you shall ruin with stones."', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 3, 20, 'The next day, about the time of the morning offering, suddenly water began to flow from the direction of Edom, until the country was filled with water.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 3, 21, 'When all the Moabites heard that the kings had come up to fight against them, all who were able to put on armor, from the youngest to the oldest, were called out and were drawn up at the frontier.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 3, 22, 'When they rose early in the morning, and the sun shone upon the water, the Moabites saw the water opposite them as red as blood.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 3, 23, 'They said, "This is blood; the kings must have fought together, and killed one another. Now then, Moab, to the spoil!"', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 3, 24, 'But when they came to the camp of Israel, the Israelites rose up and attacked the Moabites, who fled before them; as they entered Moab they continued the attack.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 3, 25, 'The cities they overturned, and on every good piece of land everyone threw a stone, until it was covered; every spring of water they stopped up, and every good tree they felled. Only at Kir-hareseth did the stone walls remain, until the slingers surrounded and attacked it.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 3, 26, 'When the king of Moab saw that the battle was going against him, he took with him seven hundred swordsmen to break through, opposite the king of Edom; but they could not.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 3, 27, 'Then he took his firstborn son who was to succeed him, and offered him as a burnt offering on the wall. And great wrath came upon Israel, so they withdrew from him and returned to their own land.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(12, '2 Raj', '2 Kings', 4, 1, 'Now the wife of a member of the company of prophets cried to Elisha, "Your servant my husband is dead; and you know that your servant feared the LORD, but a creditor has come to take my two children as slaves."', 'en', 'NRSV-CE', 'Elisha and the Widow"s Oil'),
(12, '2 Raj', '2 Kings', 4, 2, 'Elisha said to her, "What shall I do for you? Tell me, what do you have in the house?" She answered, "Your servant has nothing in the house, except a jar of oil."', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 4, 3, 'He said, "Go outside, borrow vessels from all your neighbors, empty vessels and not just a few.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 4, 4, 'Then go in, and shut the door behind you and your children, and start pouring into all these vessels; when each is full, set it aside."', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 4, 5, 'So she left him and shut the door behind her and her children; they kept bringing vessels to her, and she kept pouring.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 4, 6, 'When the vessels were full, she said to her son, "Bring me another vessel." But he said to her, "There are no more." Then the oil stopped flowing.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 4, 7, 'She came and told the man of God, and he said, "Go sell the oil and pay your debts, and you and your children can live on the rest."', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 4, 8, 'One day Elisha was passing through Shunem, where a wealthy woman lived, who urged him to have a meal. So whenever he passed that way, he would stop there for a meal.', 'en', 'NRSV-CE', 'Elisha Raises the Shunammite"s Son'),
(12, '2 Raj', '2 Kings', 4, 9, 'She said to her husband, "Look, I am sure that this man who regularly passes our way is a holy man of God.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 4, 10, 'Let us make a small roof chamber with walls, and put there for him a bed, a table, a chair, and a lamp, so that he can stay there whenever he comes to us."', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 4, 11, 'One day when he came there, he went up to the chamber and lay down there.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 4, 12, 'He said to his servant Gehazi, "Call the Shunammite woman." When he had called her, she stood before him.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 4, 13, 'He said to him, "Say to her, Since you have taken all this trouble for us, what may be done for you? Would you have a word spoken on your behalf to the king or to the commander of the army?" She answered, "I live among my own people."', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 4, 14, 'He said, "What then may be done for her?" Gehazi answered, "Well, she has no son, and her husband is old."', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 4, 15, 'He said, "Call her." When he had called her, she stood at the door.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 4, 16, 'He said, "At this season, in due time, you shall embrace a son." She replied, "No, my lord, O man of God; do not deceive your servant."', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 4, 17, 'The woman conceived and bore a son at that season, in due time, as Elisha had declared to her.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 4, 18, 'When the child was older, he went out one day to his father among the reapers.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 4, 19, 'He complained to his father, "Oh, my head, my head!" The father said to his servant, "Carry him to his mother."', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 4, 20, 'He carried him and brought him to his mother; the child sat on her lap until noon, and he died.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 4, 21, 'She went up and laid him on the bed of the man of God, closed the door on him, and left.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 4, 22, 'Then she called to her husband, and said, "Send me one of the servants and one of the donkeys, so that I may quickly go to the man of God and come back again."', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 4, 23, 'He said, "Why go to him today? It is neither new moon nor sabbath." She said, "It will be all right."', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 4, 24, 'Then she saddled the donkey and said to her servant, "Urge the animal on; do not hold back for me unless I tell you."', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 4, 25, 'So she set out, and came to the man of God at Mount Carmel.
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(12, '2 Raj', '2 Kings', 5, 1, 'Naaman, commander of the army of the king of Aram, was a great man and in high favor with his master, because by him the LORD had given victory to Aram. The man, though a mighty warrior, suffered from leprosy.', 'en', 'NRSV-CE', 'The Healing of Naaman'),
(12, '2 Raj', '2 Kings', 5, 2, 'Now the Arameans on one of their raids had taken a young girl captive from the land of Israel, and she served Naaman"s wife.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 5, 3, 'She said to her mistress, "If only my lord were with the prophet who is in Samaria! He would cure him of his leprosy."', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 5, 4, 'So Naaman went in and told his lord just what the girl from the land of Israel had said.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 5, 5, 'And the king of Aram said, "Go then, and I will send along a letter to the king of Israel."
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(12, '2 Raj', '2 Kings', 6, 1, 'Now the company of prophets said to Elisha, "As you see, the place where we live under your charge is too small for us.', 'en', 'NRSV-CE', 'The Miracle of the Ax Head'),
(12, '2 Raj', '2 Kings', 6, 2, 'Let us go to the Jordan, and let us collect logs there, one for each of us, and build a place there for us to live." He answered, "Do so."', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 6, 3, 'Then one of them said, "Please come with your servants." And he answered, "I will."', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 6, 4, 'So he went with them. When they came to the Jordan, they cut down trees.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 6, 5, 'But as one was felling a log, his ax head fell into the water; he cried out, "Alas, master! It was borrowed."', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 6, 6, 'Then the man of God said, "Where did it fall?" When he showed him the place, he cut off a stick, and threw it in there, and made the iron float.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 6, 7, 'He said, "Pick it up." So he reached out his hand and took it.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 6, 8, 'Once when the king of Aram was at war with Israel, he took counsel with his officers. He said, "At such and such a place shall be my camp."', 'en', 'NRSV-CE', 'The Aramean Attack Is Thwarted'),
(12, '2 Raj', '2 Kings', 6, 9, 'But the man of God sent word to the king of Israel, "Take care not to pass this place, because the Arameans are going down there."', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 6, 10, 'The king of Israel sent word to the place of which the man of God spoke. More than once or twice he warned such a place so that it was on the alert.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 6, 11, 'The mind of the king of Aram was greatly perturbed because of this; he called his officers and said to them, "Now tell me who among us sides with the king of Israel?"', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 6, 12, 'Then one of his officers said, "No one, my lord king. It is Elisha, the prophet in Israel, who tells the king of Israel the words that you speak in your bedchamber."', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 6, 13, 'He said, "Go and find where he is; I will send and seize him." He was told, "He is in Dothan."', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 6, 14, 'So he sent horses and chariots there and a great army; they came by night, and surrounded the city.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 6, 15, 'When an attendant of the man of God rose early in the morning and went out, an army with horses and chariots was all around the city. His servant said, "Alas, master! What shall we do?"', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 6, 16, 'He replied, "Do not be afraid, for there are more with us than there are with them."', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 6, 17, 'Then Elisha prayed: "O LORD, please open his eyes that he may see." So the LORD opened the eyes of the servant, and he saw; the mountain was full of horses and chariots of fire all around Elisha.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 6, 18, 'When the Arameans came down against him, Elisha prayed to the LORD, and said, "Strike this people, please, with blindness." So he struck them with blindness as Elisha had asked.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 6, 19, 'Elisha said to them, "This is not the way, and this is not the city; follow me, and I will bring you to the man whom you seek." And he led them to Samaria.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 6, 20, 'As soon as they entered Samaria, Elisha said, "O LORD, open the eyes of these men so that they may see." The LORD opened their eyes, and they saw that they were inside Samaria.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 6, 21, 'When the king of Israel saw them he said to Elisha, "Father, shall I kill them? Shall I kill them?"', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 6, 22, 'He answered, "No! Did you capture with your sword and your bow those whom you want to kill? Set food and water before them so that they may eat and drink; and let them go to their master."', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 6, 23, 'So he prepared for them a great feast; after they ate and drank, he sent them on their way, and they went to their master. And the Arameans no longer came raiding into the land of Israel.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 6, 24, 'Some time later King Ben-hadad of Aram mustered his entire army; he marched against Samaria and laid siege to it.', 'en', 'NRSV-CE', 'Ben-hadad"s Siege of Samaria'),
(12, '2 Raj', '2 Kings', 6, 25, 'As the siege continued, famine in Samaria became so great that a donkey"s head was sold for eighty shekels of silver, and one-fourth of a kab of dove"s dung for five shekels of silver.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 6, 26, 'Now as the king of Israel was walking on the city wall, a woman cried out to him, "Help, my lord king!"', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 6, 27, 'He said, "No! Let the LORD help you. How can I help you? From the threshing floor or from the wine press?"', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 6, 28, 'But then the king asked her, "What is your complaint?" She answered, "This woman said to me, "Give up your son; we will eat him today, and we will eat my son tomorrow."', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 6, 29, 'So we cooked my son and ate him. The next day I said to her, "Give up your son and we will eat him." But she has hidden her son."', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 6, 30, 'When the king heard the words of the woman he tore his clothes--now since he was walking on the city wall, the people could see that he had sackcloth on his body underneath--', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 6, 31, 'and he said, "So may God do to me, and more, if the head of Elisha son of Shaphat stays on his shoulders today."', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 6, 32, 'So he dispatched a man from his presence.
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(12, '2 Raj', '2 Kings', 7, 1, 'But Elisha said, "Hear the word of the LORD: thus says the LORD, Tomorrow about this time a measure of choice meal shall be sold for a shekel, and two measures of barley for a shekel, at the gate of Samaria."', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 7, 2, 'Then the captain on whose hand the king leaned said to the man of God, "Even if the LORD were to make windows in the sky, could such a thing happen?" But he said, "You shall see it with your own eyes, but you shall not eat from it."', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 7, 3, 'Now there were four leprous men outside the city gate, who said to one another, "Why should we sit here until we die?', 'en', 'NRSV-CE', 'The Arameans Flee'),
(12, '2 Raj', '2 Kings', 7, 4, 'If we say, "Let us enter the city," the famine is in the city, and we shall die there; but if we sit here, we shall also die. Therefore, let us desert to the Aramean camp; if they spare our lives, we shall live; and if they kill us, we shall but die."', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 7, 5, 'So they arose at twilight to go to the Aramean camp; but when they came to the edge of the Aramean camp, there was no one there at all.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 7, 6, 'For the Lord had caused the Aramean army to hear the sound of chariots, and of horses, the sound of a great army, so that they said to one another, "The king of Israel has hired the kings of the Hittites and the kings of Egypt to fight against us."', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 7, 7, 'So they fled away in the twilight and abandoned their tents, their horses, and their donkeys leaving the camp just as it was, and fled for their lives.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 7, 8, 'When these leprous men had come to the edge of the camp, they went into a tent, ate and drank, carried off silver, gold, and clothing, and went and hid them. Then they came back, entered another tent, carried off things from it, and went and hid them.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 7, 9, 'Then they said to one another, "What we are doing is wrong. This is a day of good news; if we are silent and wait until the morning light, we will be found guilty; therefore let us go and tell the king"s household."', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 7, 10, 'So they came and called to the gatekeepers of the city, and told them, "We went to the Aramean camp, but there was no one to be seen or heard there, nothing but the horses tied, the donkeys tied, and the tents as they were."', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 7, 11, 'Then the gatekeepers called out and proclaimed it to the king"s household.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 7, 12, 'The king got up in the night, and said to his servants, "I will tell you what the Arameans have prepared against us. They know that we are starving; so they have left the camp to hide themselves in the open country, thinking, "When they come out of the city, we shall take them alive and get into the city.""', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 7, 13, 'One of his servants said, "Let some men take five of the remaining horses, since those left here will suffer the fate of the whole multitude of Israel that have perished already; let us send and find out."', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 7, 14, 'So they took two mounted men, and the king sent them after the Aramean army, saying, "Go and find out."', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 7, 15, 'So they went after them as far as the Jordan; the whole way was littered with garments and equipment that the Arameans had thrown away in their haste. So the messengers returned, and told the king.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 7, 16, 'Then the people went out, and plundered the camp of the Arameans. So a measure of choice meal was sold for a shekel, and two measures of barley for a shekel, according to the word of the LORD.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 7, 17, 'Now the king had appointed the captain on whose hand he leaned to have charge of the gate; the people trampled him to death in the gate, just as the man of God had said when the king came down to him.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 7, 18, 'For when the man of God had said to the king, "Two measures of barley shall be sold for a shekel, and a measure of choice meal for a shekel, about this time tomorrow in the gate of Samaria,"', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 7, 19, 'the captain had answered the man of God, "Even if the LORD were to make windows in the sky, could such a thing happen?" And he had answered, "You shall see it with your own eyes, but you shall not eat from it."', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 7, 20, 'It did indeed happen to him; the people trampled him to death in the gate.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(12, '2 Raj', '2 Kings', 8, 1, 'Now Elisha had said to the woman whose son he had restored to life, "Get up and go with your household, and settle wherever you can; for the LORD has called for a famine, and it will come on the land for seven years."', 'en', 'NRSV-CE', 'The Shunammite Woman"s Land Restored'),
(12, '2 Raj', '2 Kings', 8, 2, 'So the woman got up and did according to the word of the man of God; she went with her household and settled in the land of the Philistines seven years.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 8, 3, 'At the end of the seven years, when the woman returned from the land of the Philistines, she set out to appeal to the king for her house and her land.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 8, 4, 'Now the king was talking with Gehazi the servant of the man of God, saying, "Tell me all the great things that Elisha has done."', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 8, 5, 'While he was telling the king how Elisha had restored a dead person to life, the woman whose son he had restored to life appealed to the king for her house and her land. Gehazi said, "My lord king, here is the woman, and here is her son whom Elisha restored to life."', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 8, 6, 'When the king questioned the woman, she told him. So the king appointed an official for her, saying, "Restore all that was hers, together with all the revenue of the fields from the day that she left the land until now."', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 8, 7, 'Elisha went to Damascus while King Ben-hadad of Aram was ill. When it was told him, "The man of God has come here,"', 'en', 'NRSV-CE', 'Death of Ben-hadad'),
(12, '2 Raj', '2 Kings', 8, 8, 'the king said to Hazael, "Take a present with you and go to meet the man of God. Inquire of the LORD through him, whether I shall recover from this illness."', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 8, 9, 'So Hazael went to meet him, taking a present with him, all kinds of goods of Damascus, forty camel loads. When he entered and stood before him, he said, "Your son King Ben-hadad of Aram has sent me to you, saying, "Shall I recover from this illness?""', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 8, 10, 'Elisha said to him, "Go, say to him, "You shall certainly recover"; but the LORD has shown me that he shall certainly die."', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 8, 11, 'He fixed his gaze and stared at him, until he was ashamed. Then the man of God wept.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 8, 12, 'Hazael asked, "Why does my lord weep?" He answered, "Because I know the evil that you will do to the people of Israel; you will set their fortresses on fire, you will kill their young men with the sword, dash in pieces their little ones, and rip up their pregnant women."', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 8, 13, 'Hazael said, "What is your servant, who is a mere dog, that he should do this great thing?" Elisha answered, "The LORD has shown me that you are to be king over Aram."', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 8, 14, 'Then he left Elisha, and went to his master Ben-hadad, who said to him, "What did Elisha say to you?" And he answered, "He told me that you would certainly recover."', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 8, 15, 'But the next day he took the bed-cover and dipped it in water and spread it over the king"s face, until he died. And Hazael succeeded him.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 8, 16, 'In the fifth year of King Joram son of Ahab of Israel, Jehoram son of King Jehoshaphat of Judah began to reign.', 'en', 'NRSV-CE', 'Jehoram Reigns over Judah'),
(12, '2 Raj', '2 Kings', 8, 17, 'He was thirty-two years old when he became king, and he reigned eight years in Jerusalem.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 8, 18, 'He walked in the way of the kings of Israel, as the house of Ahab had done, for the daughter of Ahab was his wife. He did what was evil in the sight of the LORD.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 8, 19, 'Yet the LORD would not destroy Judah, for the sake of his servant David, since he had promised to give a lamp to him and to his descendants forever.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 8, 20, 'In his days Edom revolted against the rule of Judah, and set up a king of their own.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 8, 21, 'Then Joram crossed over to Zair with all his chariots. He set out by night and attacked the Edomites and their chariot commanders who had surrounded him; but his army fled home.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 8, 22, 'So Edom has been in revolt against the rule of Judah to this day. Libnah also revolted at the same time.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 8, 23, 'Now the rest of the acts of Joram, and all that he did, are they not written in the Book of the Annals of the Kings of Judah?', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 8, 24, 'So Joram slept with his ancestors, and was buried with them in the city of David; his son Ahaziah succeeded him.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 8, 25, 'In the twelfth year of King Joram son of Ahab of Israel, Ahaziah son of King Jehoram of Judah began to reign.', 'en', 'NRSV-CE', 'Ahaziah Reigns over Judah'),
(12, '2 Raj', '2 Kings', 8, 26, 'Ahaziah was twenty-two years old when he began to reign; he reigned one year in Jerusalem. His mother"s name was Athaliah, a granddaughter of King Omri of Israel.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 8, 27, 'He also walked in the way of the house of Ahab, doing what was evil in the sight of the LORD, as the house of Ahab had done, for he was son-in-law to the house of Ahab.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 8, 28, 'He went with Joram son of Ahab to wage war against King Hazael of Aram at Ramoth-gilead, where the Arameans wounded Joram.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 8, 29, 'King Joram returned to be healed in Jezreel of the wounds that the Arameans had inflicted on him at Ramah, when he fought against King Hazael of Aram. King Ahaziah son of Jehoram of Judah went down to see Joram son of Ahab in Jezreel, because he was wounded.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(12, '2 Raj', '2 Kings', 9, 1, 'Then the prophet Elisha called a member of the company of prophets and said to him, "Gird up your loins; take this flask of oil in your hand, and go to Ramoth-gilead.', 'en', 'NRSV-CE', 'Anointing of Jehu'),
(12, '2 Raj', '2 Kings', 9, 2, 'When you arrive, look there for Jehu son of Jehoshaphat, son of Nimshi; go in and get him to leave his companions, and take him into an inner chamber.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 9, 3, 'Then take the flask of oil, pour it on his head, and say, "Thus says the LORD: I anoint you king over Israel." Then open the door and flee; do not linger."', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 9, 4, 'So the young man, the young prophet, went to Ramoth-gilead.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 9, 5, 'He arrived while the commanders of the army were in council, and he announced, "I have a message for you, commander." "For which one of us?" asked Jehu. "For you, commander."', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 9, 6, 'So Jehu got up and went inside; the young man poured the oil on his head, saying to him, "Thus says the LORD the God of Israel: I anoint you king over the people of the LORD, over Israel.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 9, 7, 'You shall strike down the house of your master Ahab, so that I may avenge on Jezebel the blood of my servants the prophets, and the blood of all the servants of the LORD.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 9, 8, 'For the whole house of Ahab shall perish; I will cut off from Ahab every male, bond or free, in Israel.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 9, 9, 'I will make the house of Ahab like the house of Jeroboam son of Nebat, and like the house of Baasha son of Ahijah.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 9, 10, 'The dogs shall eat Jezebel in the territory of Jezreel, and no one shall bury her." Then he opened the door and fled.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 9, 11, 'When Jehu came back to his master"s officers, they said to him, "Is everything all right? Why did that madman come to you?" He answered them, "You know the sort and how they babble."', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 9, 12, 'They said, "Liar! Come on, tell us!" So he said, "This is just what he said to me: "Thus says the LORD, I anoint you king over Israel.""', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 9, 13, 'Then hurriedly they all took their cloaks and spread them for him on the bare steps; and they blew the trumpet, and proclaimed, "Jehu is king."', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 9, 14, 'Thus Jehu son of Jehoshaphat son of Nimshi conspired against Joram. Joram with all Israel had been on guard at Ramoth-gilead against King Hazael of Aram;', 'en', 'NRSV-CE', 'Joram of Israel Killed'),
(12, '2 Raj', '2 Kings', 9, 15, 'but King Joram had returned to be healed in Jezreel of the wounds that the Arameans had inflicted on him, when he fought against King Hazael of Aram. So Jehu said, "If this is your wish, then let no one slip out of the city to go and tell the news in Jezreel."', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 9, 16, 'Then Jehu mounted his chariot and went to Jezreel, where Joram was lying ill. King Ahaziah of Judah had come down to visit Joram.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 9, 17, 'In Jezreel, the sentinel standing on the tower spied the company of Jehu arriving, and said, "I see a company." Joram said, "Take a horseman; send him to meet them, and let him say, "Is it peace?""', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 9, 18, 'So the horseman went to meet him; he said, "Thus says the king, "Is it peace?"" Jehu responded, "What have you to do with peace? Fall in behind me." The sentinel reported, saying, "The messenger reached them, but he is not coming back."', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 9, 19, 'Then he sent out a second horseman, who came to them and said, "Thus says the king, "Is it peace?"" Jehu answered, "What have you to do with peace? Fall in behind me."', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 9, 20, 'Again the sentinel reported, "He reached them, but he is not coming back. It looks like the driving of Jehu son of Nimshi; for he drives like a maniac."', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 9, 21, 'Joram said, "Get ready." And they got his chariot ready. Then King Joram of Israel and King Ahaziah of Judah set out, each in his chariot, and went to meet Jehu; they met him at the property of Naboth the Jezreelite.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 9, 22, 'When Joram saw Jehu, he said, "Is it peace, Jehu?" He answered, "What peace can there be, so long as the many whoredoms and sorceries of your mother Jezebel continue?"', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 9, 23, 'Then Joram reined about and fled, saying to Ahaziah, "Treason, Ahaziah!"', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 9, 24, 'Jehu drew his bow with all his strength, and shot Joram between the shoulders, so that the arrow pierced his heart; and he sank in his chariot.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 9, 25, 'Jehu said to his aide Bidkar, "Lift him out, and throw him on the plot of ground belonging to Naboth the Jezreelite; for remember, when you and I rode side by side behind his father Ahab how the LORD uttered this oracle against him:', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 9, 26, '"For the blood of Naboth and for the blood of his children that I saw yesterday, says the LORD, I swear I will repay you on this very plot of ground." Now therefore lift him out and throw him on the plot of ground, in accordance with the word of the LORD."', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 9, 27, 'When King Ahaziah of Judah saw this, he fled in the direction of Beth-haggan. Jehu pursued him, saying, "Shoot him also!" And they shot him in the chariot at the ascent to Gur, which is by Ibleam. Then he fled to Megiddo, and died there.', 'en', 'NRSV-CE', 'Ahaziah of Judah Killed'),
(12, '2 Raj', '2 Kings', 9, 28, 'His officers carried him in a chariot to Jerusalem, and buried him in his tomb with his ancestors in the city of David.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 9, 29, 'In the eleventh year of Joram son of Ahab, Ahaziah began to reign over Judah.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 9, 30, 'When Jehu came to Jezreel, Jezebel heard of it; she painted her eyes, and adorned her head, and looked out of the window.', 'en', 'NRSV-CE', 'Jezebel"s Violent Death'),
(12, '2 Raj', '2 Kings', 9, 31, 'As Jehu entered the gate, she said, "Is it peace, Zimri, murderer of your master?"', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 9, 32, 'He looked up to the window and said, "Who is on my side? Who?" Two or three eunuchs looked out at him.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 9, 33, 'He said, "Throw her down." So they threw her down; some of her blood spattered on the wall and on the horses, which trampled on her.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 9, 34, 'Then he went in and ate and drank; he said, "See to that cursed woman and bury her; for she is a king"s daughter."', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 9, 35, 'But when they went to bury her, they found no more of her than the skull and the feet and the palms of her hands.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 9, 36, 'When they came back and told him, he said, "This is the word of the LORD, which he spoke by his servant Elijah the Tishbite, "In the territory of Jezreel the dogs shall eat the flesh of Jezebel;', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 9, 37, 'the corpse of Jezebel shall be like dung on the field in the territory of Jezreel, so that no one can say, This is Jezebel.""', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(12, '2 Raj', '2 Kings', 10, 1, 'Now Ahab had seventy sons in Samaria. So Jehu wrote letters and sent them to Samaria, to the rulers of Jezreel, to the elders, and to the guardians of the sons of Ahab, saying,', 'en', 'NRSV-CE', 'Massacre of Ahab"s Descendants'),
(12, '2 Raj', '2 Kings', 10, 2, '"Since your master"s sons are with you and you have at your disposal chariots and horses, a fortified city, and weapons,', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 10, 3, 'select the son of your master who is the best qualified, set him on his father"s throne, and fight for your master"s house."', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 10, 4, 'But they were utterly terrified and said, "Look, two kings could not withstand him; how then can we stand?"', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 10, 5, 'So the steward of the palace, and the governor of the city, along with the elders and the guardians, sent word to Jehu: "We are your servants; we will do anything you say. We will not make anyone king; do whatever you think right."', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 10, 6, 'Then he wrote them a second letter, saying, "If you are on my side, and if you are ready to obey me, take the heads of your master"s sons and come to me at Jezreel tomorrow at this time." Now the king"s sons, seventy persons, were with the leaders of the city, who were charged with their upbringing.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 10, 7, 'When the letter reached them, they took the king"s sons and killed them, seventy persons; they put their heads in baskets and sent them to him at Jezreel.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 10, 8, 'When the messenger came and told him, "They have brought the heads of the king"s sons," he said, "Lay them in two heaps at the entrance of the gate until the morning."', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 10, 9, 'Then in the morning when he went out, he stood and said to all the people, "You are innocent. It was I who conspired against my master and killed him; but who struck down all these?', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 10, 10, 'Know then that there shall fall to the earth nothing of the word of the LORD, which the LORD spoke concerning the house of Ahab; for the LORD has done what he said through his servant Elijah."', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 10, 11, 'So Jehu killed all who were left of the house of Ahab in Jezreel, all his leaders, close friends, and priests, until he left him no survivor.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 10, 12, 'Then he set out and went to Samaria. On the way, when he was at Beth-eked of the Shepherds,', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 10, 13, 'Jehu met relatives of King Ahaziah of Judah and said, "Who are you?" They answered, "We are kin of Ahaziah; we have come down to visit the royal princes and the sons of the queen mother."', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 10, 14, 'He said, "Take them alive." They took them alive, and slaughtered them at the pit of Beth-eked, forty-two in all; he spared none of them.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 10, 15, 'When he left there, he met Jehonadab son of Rechab coming to meet him; he greeted him, and said to him, "Is your heart as true to mine as mine is to yours?" Jehonadab answered, "It is." Jehu said, "If it is, give me your hand." So he gave him his hand. Jehu took him up with him into the chariot.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 10, 16, 'He said, "Come with me, and see my zeal for the LORD." So he had him ride in his chariot.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 10, 17, 'When he came to Samaria, he killed all who were left to Ahab in Samaria, until he had wiped them out, according to the word of the LORD that he spoke to Elijah.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 10, 18, 'Then Jehu assembled all the people and said to them, "Ahab offered Baal small service; but Jehu will offer much more.', 'en', 'NRSV-CE', 'Slaughter of Worshipers of Baal'),
(12, '2 Raj', '2 Kings', 10, 19, 'Now therefore summon to me all the prophets of Baal, all his worshipers, and all his priests; let none be missing, for I have a great sacrifice to offer to Baal; whoever is missing shall not live." But Jehu was acting with cunning in order to destroy the worshipers of Baal.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 10, 20, 'Jehu decreed, "Sanctify a solemn assembly for Baal." So they proclaimed it.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 10, 21, 'Jehu sent word throughout all Israel; all the worshipers of Baal came, so that there was no one left who did not come. They entered the temple of Baal, until the temple of Baal was filled from wall to wall.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 10, 22, 'He said to the keeper of the wardrobe, "Bring out the vestments for all the worshipers of Baal." So he brought out the vestments for them.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 10, 23, 'Then Jehu entered the temple of Baal with Jehonadab son of Rechab; he said to the worshipers of Baal, "Search and see that there is no worshiper of the LORD here among you, but only worshipers of Baal."', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 10, 24, 'Then they proceeded to offer sacrifices and burnt offerings.
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(12, '2 Raj', '2 Kings', 11, 1, 'Now when Athaliah, Ahaziah"s mother, saw that her son was dead, she set about to destroy all the royal family.', 'en', 'NRSV-CE', 'Athaliah Reigns over Judah'),
(12, '2 Raj', '2 Kings', 11, 2, 'But Jehosheba, King Joram"s daughter, Ahaziah"s sister, took Joash son of Ahaziah, and stole him away from among the king"s children who were about to be killed; she put him and his nurse in a bedroom. Thus she hid him from Athaliah, so that he was not killed;', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 11, 3, 'he remained with her six years, hidden in the house of the LORD, while Athaliah reigned over the land.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 11, 4, 'But in the seventh year Jehoiada summoned the captains of the Carites and of the guards and had them come to him in the house of the LORD. He made a covenant with them and put them under oath in the house of the LORD; then he showed them the king"s son.', 'en', 'NRSV-CE', 'Jehoiada Anoints the Child Joash'),
(12, '2 Raj', '2 Kings', 11, 5, 'He commanded them, "This is what you are to do: one-third of you, those who go off duty on the sabbath and guard the king"s house', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 11, 6, '(another third being at the gate Sur and a third at the gate behind the guards), shall guard the palace;', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 11, 7, 'and your two divisions that come on duty in force on the sabbath and guard the house of the LORD', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 11, 8, 'shall surround the king, each with weapons in hand; and whoever approaches the ranks is to be killed. Be with the king in his comings and goings."', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 11, 9, 'The captains did according to all that the priest Jehoiada commanded; each brought his men who were to go off duty on the sabbath, with those who were to come on duty on the sabbath, and came to the priest Jehoiada.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 11, 10, 'The priest delivered to the captains the spears and shields that had been King David"s, which were in the house of the LORD;', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 11, 11, 'the guards stood, every man with his weapons in his hand, from the south side of the house to the north side of the house, around the altar and the house, to guard the king on every side.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 11, 12, 'Then he brought out the king"s son, put the crown on him, and gave him the covenant; they proclaimed him king, and anointed him; they clapped their hands and shouted, "Long live the king!"', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 11, 13, 'When Athaliah heard the noise of the guard and of the people, she went into the house of the LORD to the people;', 'en', 'NRSV-CE', 'Death of Athaliah'),
(12, '2 Raj', '2 Kings', 11, 14, 'when she looked, there was the king standing by the pillar, according to custom, with the captains and the trumpeters beside the king, and all the people of the land rejoicing and blowing trumpets. Athaliah tore her clothes and cried, "Treason! Treason!"', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 11, 15, 'Then the priest Jehoiada commanded the captains who were set over the army, "Bring her out between the ranks, and kill with the sword anyone who follows her." For the priest said, "Let her not be killed in the house of the LORD."', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 11, 16, 'So they laid hands on her; she went through the horses" entrance to the king"s house, and there she was put to death.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 11, 17, 'Jehoiada made a covenant between the LORD and the king and people, that they should be the LORD"s people; also between the king and the people.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 11, 18, 'Then all the people of the land went to the house of Baal, and tore it down; his altars and his images they broke in pieces, and they killed Mattan, the priest of Baal, before the altars. The priest posted guards over the house of the LORD.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 11, 19, 'He took the captains, the Carites, the guards, and all the people of the land; then they brought the king down from the house of the LORD, marching through the gate of the guards to the king"s house. He took his seat on the throne of the kings.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 11, 20, 'So all the people of the land rejoiced; and the city was quiet after Athaliah had been killed with the sword at the king"s house.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 11, 21, 'Jehoash was seven years old when he began to reign.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(12, '2 Raj', '2 Kings', 12, 1, 'In the seventh year of Jehu, Jehoash began to reign; he reigned forty years in Jerusalem. His mother"s name was Zibiah of Beer-sheba.', 'en', 'NRSV-CE', 'The Temple Repaired'),
(12, '2 Raj', '2 Kings', 12, 2, 'Jehoash did what was right in the sight of the LORD all his days, because the priest Jehoiada instructed him.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 12, 3, 'Nevertheless the high places were not taken away; the people continued to sacrifice and make offerings on the high places.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 12, 4, 'Jehoash said to the priests, "All the money offered as sacred donations that is brought into the house of the LORD, the money for which each person is assessed--the money from the assessment of persons--and the money from the voluntary offerings brought into the house of the LORD,', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 12, 5, 'let the priests receive from each of the donors; and let them repair the house wherever any need of repairs is discovered."', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 12, 6, 'But by the twenty-third year of King Jehoash the priests had made no repairs on the house.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 12, 7, 'Therefore King Jehoash summoned the priest Jehoiada with the other priests and said to them, "Why are you not repairing the house? Now therefore do not accept any more money from your donors but hand it over for the repair of the house."', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 12, 8, 'So the priests agreed that they would neither accept more money from the people nor repair the house.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 12, 9, 'Then the priest Jehoiada took a chest, made a hole in its lid, and set it beside the altar on the right side as one entered the house of the LORD; the priests who guarded the threshold put in it all the money that was brought into the house of the LORD.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 12, 10, 'Whenever they saw that there was a great deal of money in the chest, the king"s secretary and the high priest went up, counted the money that was found in the house of the LORD, and tied it up in bags.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 12, 11, 'They would give the money that was weighed out into the hands of the workers who had the oversight of the house of the LORD; then they paid it out to the carpenters and the builders who worked on the house of the LORD,', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 12, 12, 'to the masons and the stonecutters, as well as to buy timber and quarried stone for making repairs on the house of the LORD, as well as for any outlay for repairs of the house.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 12, 13, 'But for the house of the LORD no basins of silver, snuffers, bowls, trumpets, or any vessels of gold, or of silver, were made from the money that was brought into the house of the LORD,', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 12, 14, 'for that was given to the workers who were repairing the house of the LORD with it.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 12, 15, 'They did not ask an accounting from those into whose hand they delivered the money to pay out to the workers, for they dealt honestly.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 12, 16, 'The money from the guilt offerings and the money from the sin offerings was not brought into the house of the LORD; it belonged to the priests.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 12, 17, 'At that time King Hazael of Aram went up, fought against Gath, and took it. But when Hazael set his face to go up against Jerusalem,', 'en', 'NRSV-CE', 'Hazael Threatens Jerusalem'),
(12, '2 Raj', '2 Kings', 12, 18, 'King Jehoash of Judah took all the votive gifts that Jehoshaphat, Jehoram, and Ahaziah, his ancestors, the kings of Judah, had dedicated, as well as his own votive gifts, all the gold that was found in the treasuries of the house of the LORD and of the king"s house, and sent these to King Hazael of Aram. Then Hazael withdrew from Jerusalem.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 12, 19, 'Now the rest of the acts of Joash, and all that he did, are they not written in the Book of the Annals of the Kings of Judah?', 'en', 'NRSV-CE', 'Death of Joash'),
(12, '2 Raj', '2 Kings', 12, 20, 'His servants arose, devised a conspiracy, and killed Joash in the house of Millo, on the way that goes down to Silla.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 12, 21, 'It was Jozacar son of Shimeath and Jehozabad son of Shomer, his servants, who struck him down, so that he died. He was buried with his ancestors in the city of David; then his son Amaziah succeeded him.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(12, '2 Raj', '2 Kings', 13, 1, 'In the twenty-third year of King Joash son of Ahaziah of Judah, Jehoahaz son of Jehu began to reign over Israel in Samaria; he reigned seventeen years.', 'en', 'NRSV-CE', 'Jehoahaz Reigns over Israel'),
(12, '2 Raj', '2 Kings', 13, 2, 'He did what was evil in the sight of the LORD, and followed the sins of Jeroboam son of Nebat, which he caused Israel to sin; he did not depart from them.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 13, 3, 'The anger of the LORD was kindled against Israel, so that he gave them repeatedly into the hand of King Hazael of Aram, then into the hand of Ben-hadad son of Hazael.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 13, 4, 'But Jehoahaz entreated the LORD, and the LORD heeded him; for he saw the oppression of Israel, how the king of Aram oppressed them.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 13, 5, 'Therefore the LORD gave Israel a savior, so that they escaped from the hand of the Arameans; and the people of Israel lived in their homes as formerly.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 13, 6, 'Nevertheless they did not depart from the sins of the house of Jeroboam, which he caused Israel to sin, but walked in them; the sacred pole also remained in Samaria.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 13, 7, 'So Jehoahaz was left with an army of not more than fifty horsemen, ten chariots and ten thousand footmen; for the king of Aram had destroyed them and made them like the dust at threshing.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 13, 8, 'Now the rest of the acts of Jehoahaz and all that he did, including his might, are they not written in the Book of the Annals of the Kings of Israel?', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 13, 9, 'So Jehoahaz slept with his ancestors, and they buried him in Samaria; then his son Joash succeeded him.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 13, 10, 'In the thirty-seventh year of King Joash of Judah, Jehoash son of Jehoahaz began to reign over Israel in Samaria; he reigned sixteen years.', 'en', 'NRSV-CE', 'Jehoash Reigns over Israel'),
(12, '2 Raj', '2 Kings', 13, 11, 'He also did what was evil in the sight of the LORD; he did not depart from all the sins of Jeroboam son of Nebat, which he caused Israel to sin, but he walked in them.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 13, 12, 'Now the rest of the acts of Joash, and all that he did, as well as the might with which he fought against King Amaziah of Judah, are they not written in the Book of the Annals of the Kings of Israel?', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 13, 13, 'So Joash slept with his ancestors, and Jeroboam sat upon his throne; Joash was buried in Samaria with the kings of Israel.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 13, 14, 'Now when Elisha had fallen sick with the illness of which he was to die, King Joash of Israel went down to him, and wept before him, crying, "My father, my father! The chariots of Israel and its horsemen!"', 'en', 'NRSV-CE', 'Death of Elisha'),
(12, '2 Raj', '2 Kings', 13, 15, 'Elisha said to him, "Take a bow and arrows"; so he took a bow and arrows.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 13, 16, 'Then he said to the king of Israel, "Draw the bow"; and he drew it. Elisha laid his hands on the king"s hands.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 13, 17, 'Then he said, "Open the window eastward"; and he opened it. Elisha said, "Shoot"; and he shot. Then he said, "The LORD"s arrow of victory, the arrow of victory over Aram! For you shall fight the Arameans in Aphek until you have made an end of them."', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 13, 18, 'He continued, "Take the arrows"; and he took them. He said to the king of Israel, "Strike the ground with them"; he struck three times, and stopped.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 13, 19, 'Then the man of God was angry with him, and said, "You should have struck five or six times; then you would have struck down Aram until you had made an end of it, but now you will strike down Aram only three times."', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 13, 20, 'So Elisha died, and they buried him. Now bands of Moabites used to invade the land in the spring of the year.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 13, 21, 'As a man was being buried, a marauding band was seen and the man was thrown into the grave of Elisha; as soon as the man touched the bones of Elisha, he came to life and stood on his feet.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 13, 22, 'Now King Hazael of Aram oppressed Israel all the days of Jehoahaz.', 'en', 'NRSV-CE', 'Israel Recaptures Cities from Aram'),
(12, '2 Raj', '2 Kings', 13, 23, 'But the LORD was gracious to them and had compassion on them; he turned toward them, because of his covenant with Abraham, Isaac, and Jacob, and would not destroy them; nor has he banished them from his presence until now.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 13, 24, 'When King Hazael of Aram died, his son Ben-hadad succeeded him.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 13, 25, 'Then Jehoash son of Jehoahaz took again from Ben-hadad son of Hazael the towns that he had taken from his father Jehoahaz in war. Three times Joash defeated him and recovered the towns of Israel.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(12, '2 Raj', '2 Kings', 14, 1, 'In the second year of King Joash son of Joahaz of Israel, King Amaziah son of Joash of Judah, began to reign.', 'en', 'NRSV-CE', 'Amaziah Reigns over Judah'),
(12, '2 Raj', '2 Kings', 14, 2, 'He was twenty-five years old when he began to reign, and he reigned twenty-nine years in Jerusalem. His mother"s name was Jehoaddin of Jerusalem.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 14, 3, 'He did what was right in the sight of the LORD, yet not like his ancestor David; in all things he did as his father Joash had done.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 14, 4, 'But the high places were not removed; the people still sacrificed and made offerings on the high places.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 14, 5, 'As soon as the royal power was firmly in his hand he killed his servants who had murdered his father the king.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 14, 6, 'But he did not put to death the children of the murderers; according to what is written in the book of the law of Moses, where the LORD commanded, "The parents shall not be put to death for the children, or the children be put to death for the parents; but all shall be put to death for their own sins."', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 14, 7, 'He killed ten thousand Edomites in the Valley of Salt and took Sela by storm; he called it Jokthe-el, which is its name to this day.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 14, 8, 'Then Amaziah sent messengers to King Jehoash son of Jehoahaz, son of Jehu, of Israel, saying, "Come, let us look one another in the face."', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 14, 9, 'King Jehoash of Israel sent word to King Amaziah of Judah, "A thornbush on Lebanon sent to a cedar on Lebanon, saying, "Give your daughter to my son for a wife"; but a wild animal of Lebanon passed by and trampled down the thornbush.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 14, 10, 'You have indeed defeated Edom, and your heart has lifted you up. Be content with your glory, and stay at home; for why should you provoke trouble so that you fall, you and Judah with you?"', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 14, 11, 'But Amaziah would not listen. So King Jehoash of Israel went up; he and King Amaziah of Judah faced one another in battle at Beth-shemesh, which belongs to Judah.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 14, 12, 'Judah was defeated by Israel; everyone fled home.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 14, 13, 'King Jehoash of Israel captured King Amaziah of Judah son of Jehoash, son of Ahaziah, at Beth-shemesh; he came to Jerusalem, and broke down the wall of Jerusalem from the Ephraim Gate to the Corner Gate, a distance of four hundred cubits.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 14, 14, 'He seized all the gold and silver, and all the vessels that were found in the house of the LORD and in the treasuries of the king"s house, as well as hostages; then he returned to Samaria.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 14, 15, 'Now the rest of the acts that Jehoash did, his might, and how he fought with King Amaziah of Judah, are they not written in the Book of the Annals of the Kings of Israel?', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 14, 16, 'Jehoash slept with his ancestors, and was buried in Samaria with the kings of Israel; then his son Jeroboam succeeded him.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 14, 17, 'King Amaziah son of Joash of Judah lived fifteen years after the death of King Jehoash son of Jehoahaz of Israel.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 14, 18, 'Now the rest of the deeds of Amaziah, are they not written in the Book of the Annals of the Kings of Judah?', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 14, 19, 'They made a conspiracy against him in Jerusalem, and he fled to Lachish. But they sent after him to Lachish, and killed him there.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 14, 20, 'They brought him on horses; he was buried in Jerusalem with his ancestors in the city of David.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 14, 21, 'All the people of Judah took Azariah, who was sixteen years old, and made him king to succeed his father Amaziah.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 14, 22, 'He rebuilt Elath and restored it to Judah, after King Amaziah slept with his ancestors.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 14, 23, 'In the fifteenth year of King Amaziah son of Joash of Judah, King Jeroboam son of Joash of Israel began to reign in Samaria; he reigned forty-one years.', 'en', 'NRSV-CE', 'Jeroboam II Reigns over Israel'),
(12, '2 Raj', '2 Kings', 14, 24, 'He did what was evil in the sight of the LORD; he did not depart from all the sins of Jeroboam son of Nebat, which he caused Israel to sin.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 14, 25, 'He restored the border of Israel from Lebo-hamath as far as the Sea of the Arabah, according to the word of the LORD, the God of Israel, which he spoke by his servant Jonah son of Amittai, the prophet, who was from Gath-hepher.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 14, 26, 'For the LORD saw that the distress of Israel was very bitter; there was no one left, bond or free, and no one to help Israel.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 14, 27, 'But the LORD had not said that he would blot out the name of Israel from under heaven, so he saved them by the hand of Jeroboam son of Joash.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 14, 28, 'Now the rest of the acts of Jeroboam, and all that he did, and his might, how he fought, and how he recovered for Israel Damascus and Hamath, which had belonged to Judah, are they not written in the Book of the Annals of the Kings of Israel?', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 14, 29, 'Jeroboam slept with his ancestors, the kings of Israel; his son Zechariah succeeded him.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(12, '2 Raj', '2 Kings', 15, 1, 'In the twenty-seventh year of King Jeroboam of Israel King Azariah son of Amaziah of Judah began to reign.', 'en', 'NRSV-CE', 'Azariah Reigns over Judah'),
(12, '2 Raj', '2 Kings', 15, 2, 'He was sixteen years old when he began to reign, and he reigned fifty-two years in Jerusalem. His mother"s name was Jecoliah of Jerusalem.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 15, 3, 'He did what was right in the sight of the LORD, just as his father Amaziah had done.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 15, 4, 'Nevertheless the high places were not taken away; the people still sacrificed and made offerings on the high places.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 15, 5, 'The LORD struck the king, so that he was leprous to the day of his death, and lived in a separate house. Jotham the king"s son was in charge of the palace, governing the people of the land.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 15, 6, 'Now the rest of the acts of Azariah, and all that he did, are they not written in the Book of the Annals of the Kings of Judah?', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 15, 7, 'Azariah slept with his ancestors; they buried him with his ancestors in the city of David; his son Jotham succeeded him.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 15, 8, 'In the thirty-eighth year of King Azariah of Judah, Zechariah son of Jeroboam reigned over Israel in Samaria six months.', 'en', 'NRSV-CE', 'Zechariah Reigns over Israel'),
(12, '2 Raj', '2 Kings', 15, 9, 'He did what was evil in the sight of the LORD, as his ancestors had done. He did not depart from the sins of Jeroboam son of Nebat, which he caused Israel to sin.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 15, 10, 'Shallum son of Jabesh conspired against him, and struck him down in public and killed him, and reigned in place of him.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 15, 11, 'Now the rest of the deeds of Zechariah are written in the Book of the Annals of the Kings of Israel.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 15, 12, 'This was the promise of the LORD that he gave to Jehu, "Your sons shall sit on the throne of Israel to the fourth generation." And so it happened.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 15, 13, 'Shallum son of Jabesh began to reign in the thirty-ninth year of King Uzziah of Judah; he reigned one month in Samaria.', 'en', 'NRSV-CE', 'Shallum Reigns over Israel'),
(12, '2 Raj', '2 Kings', 15, 14, 'Then Menahem son of Gadi came up from Tirzah and came to Samaria; he struck down Shallum son of Jabesh in Samaria and killed him; he reigned in place of him.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 15, 15, 'Now the rest of the deeds of Shallum, including the conspiracy that he made, are written in the Book of the Annals of the Kings of Israel.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 15, 16, 'At that time Menahem sacked Tiphsah, all who were in it and its territory from Tirzah on; because they did not open it to him, he sacked it. He ripped open all the pregnant women in it.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 15, 17, 'In the thirty-ninth year of King Azariah of Judah, Menahem son of Gadi began to reign over Israel; he reigned ten years in Samaria.', 'en', 'NRSV-CE', 'Menahem Reigns over Israel'),
(12, '2 Raj', '2 Kings', 15, 18, 'He did what was evil in the sight of the LORD; he did not depart all his days from any of the sins of Jeroboam son of Nebat, which he caused Israel to sin.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 15, 19, 'King Pul of Assyria came against the land; Menahem gave Pul a thousand talents of silver, so that he might help him confirm his hold on the royal power.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 15, 20, 'Menahem exacted the money from Israel, that is, from all the wealthy, fifty shekels of silver from each one, to give to the king of Assyria. So the king of Assyria turned back, and did not stay there in the land.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 15, 21, 'Now the rest of the deeds of Menahem, and all that he did, are they not written in the Book of the Annals of the Kings of Israel?', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 15, 22, 'Menahem slept with his ancestors, and his son Pekahiah succeeded him.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 15, 23, 'In the fiftieth year of King Azariah of Judah, Pekahiah son of Menahem began to reign over Israel in Samaria; he reigned two years.', 'en', 'NRSV-CE', 'Pekahiah Reigns over Israel'),
(12, '2 Raj', '2 Kings', 15, 24, 'He did what was evil in the sight of the LORD; he did not turn away from the sins of Jeroboam son of Nebat, which he caused Israel to sin.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 15, 25, 'Pekah son of Remaliah, his captain, conspired against him with fifty of the Gileadites, and attacked him in Samaria, in the citadel of the palace along with Argob and Arieh; he killed him, and reigned in place of him.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 15, 26, 'Now the rest of the deeds of Pekahiah, and all that he did, are written in the Book of the Annals of the Kings of Israel.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 15, 27, 'In the fifty-second year of King Azariah of Judah, Pekah son of Remaliah began to reign over Israel in Samaria; he reigned twenty years.', 'en', 'NRSV-CE', 'Pekah Reigns over Israel'),
(12, '2 Raj', '2 Kings', 15, 28, 'He did what was evil in the sight of the LORD; he did not depart from the sins of Jeroboam son of Nebat, which he caused Israel to sin.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 15, 29, 'In the days of King Pekah of Israel, King Tiglath-pileser of Assyria came and captured Ijon, Abel-beth-maacah, Janoah, Kedesh, Hazor, Gilead, and Galilee, all the land of Naphtali; and he carried the people captive to Assyria.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 15, 30, 'Then Hoshea son of Elah made a conspiracy against Pekah son of Remaliah, attacked him, and killed him; he reigned in place of him, in the twentieth year of Jotham son of Uzziah.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 15, 31, 'Now the rest of the acts of Pekah, and all that he did, are written in the Book of the Annals of the Kings of Israel.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 15, 32, 'In the second year of King Pekah son of Remaliah of Israel, King Jotham son of Uzziah of Judah began to reign.', 'en', 'NRSV-CE', 'Jotham Reigns over Judah'),
(12, '2 Raj', '2 Kings', 15, 33, 'He was twenty-five years old when he began to reign and reigned sixteen years in Jerusalem. His mother"s name was Jerusha daughter of Zadok.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 15, 34, 'He did what was right in the sight of the LORD, just as his father Uzziah had done.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 15, 35, 'Nevertheless the high places were not removed; the people still sacrificed and made offerings on the high places. He built the upper gate of the house of the LORD.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 15, 36, 'Now the rest of the acts of Jotham, and all that he did, are they not written in the Book of the Annals of the Kings of Judah?', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 15, 37, 'In those days the LORD began to send King Rezin of Aram and Pekah son of Remaliah against Judah.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 15, 38, 'Jotham slept with his ancestors, and was buried with his ancestors in the city of David, his ancestor; his son Ahaz succeeded him.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(12, '2 Raj', '2 Kings', 16, 1, 'In the seventeenth year of Pekah son of Remaliah, King Ahaz son of Jotham of Judah began to reign.', 'en', 'NRSV-CE', 'Ahaz Reigns over Judah'),
(12, '2 Raj', '2 Kings', 16, 2, 'Ahaz was twenty years old when he began to reign; he reigned sixteen years in Jerusalem. He did not do what was right in the sight of the LORD his God, as his ancestor David had done,', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 16, 3, 'but he walked in the way of the kings of Israel. He even made his son pass through fire, according to the abominable practices of the nations whom the LORD drove out before the people of Israel.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 16, 4, 'He sacrificed and made offerings on the high places, on the hills, and under every green tree.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 16, 5, 'Then King Rezin of Aram and King Pekah son of Remaliah of Israel came up to wage war on Jerusalem; they besieged Ahaz but could not conquer him.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 16, 6, 'At that time the king of Edom recovered Elath for Edom, and drove the Judeans from Elath; and the Edomites came to Elath, where they live to this day.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 16, 7, 'Ahaz sent messengers to King Tiglath-pileser of Assyria, saying, "I am your servant and your son. Come up, and rescue me from the hand of the king of Aram and from the hand of the king of Israel, who are attacking me."', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 16, 8, 'Ahaz also took the silver and gold found in the house of the LORD and in the treasures of the king"s house, and sent a present to the king of Assyria.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 16, 9, 'The king of Assyria listened to him; the king of Assyria marched up against Damascus, and took it, carrying its people captive to Kir; then he killed Rezin.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 16, 10, 'When King Ahaz went to Damascus to meet King Tiglath-pileser of Assyria, he saw the altar that was at Damascus. King Ahaz sent to the priest Uriah a model of the altar, and its pattern, exact in all its details.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 16, 11, 'The priest Uriah built the altar; in accordance with all that King Ahaz had sent from Damascus, just so did the priest Uriah build it, before King Ahaz arrived from Damascus.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 16, 12, 'When the king came from Damascus, the king viewed the altar. Then the king drew near to the altar, went up on it,', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 16, 13, 'and offered his burnt offering and his grain offering, poured his drink offering, and dashed the blood of his offerings of well-being against the altar.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 16, 14, 'The bronze altar that was before the LORD he removed from the front of the house, from the place between his altar and the house of the LORD, and put it on the north side of his altar.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 16, 15, 'King Ahaz commanded the priest Uriah, saying, "Upon the great altar offer the morning burnt offering, and the evening grain offering, and the king"s burnt offering, and his grain offering, with the burnt offering of all the people of the land, their grain offering, and their drink offering; then dash against it all the blood of the burnt offering, and all the blood of the sacrifice; but the bronze altar shall be for me to inquire by."', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 16, 16, 'The priest Uriah did everything that King Ahaz commanded.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 16, 17, 'Then King Ahaz cut off the frames of the stands, and removed the laver from them; he removed the sea from the bronze oxen that were under it, and put it on a pediment of stone.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 16, 18, 'The covered portal for use on the sabbath that had been built inside the palace, and the outer entrance for the king he removed from the house of the LORD. He did this because of the king of Assyria.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 16, 19, 'Now the rest of the acts of Ahaz that he did, are they not written in the Book of the Annals of the Kings of Judah?', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 16, 20, 'Ahaz slept with his ancestors, and was buried with his ancestors in the city of David; his son Hezekiah succeeded him.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(12, '2 Raj', '2 Kings', 17, 1, 'In the twelfth year of King Ahaz of Judah, Hoshea son of Elah began to reign in Samaria over Israel; he reigned nine years.', 'en', 'NRSV-CE', 'Hoshea Reigns over Israel'),
(12, '2 Raj', '2 Kings', 17, 2, 'He did what was evil in the sight of the LORD, yet not like the kings of Israel who were before him.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 17, 3, 'King Shalmaneser of Assyria came up against him; Hoshea became his vassal, and paid him tribute.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 17, 4, 'But the king of Assyria found treachery in Hoshea; for he had sent messengers to King So of Egypt, and offered no tribute to the king of Assyria, as he had done year by year; therefore the king of Assyria confined him and imprisoned him.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 17, 5, 'Then the king of Assyria invaded all the land and came to Samaria; for three years he besieged it.', 'en', 'NRSV-CE', 'Israel Carried Captive to Assyria'),
(12, '2 Raj', '2 Kings', 17, 6, 'In the ninth year of Hoshea the king of Assyria captured Samaria; he carried the Israelites away to Assyria. He placed them in Halah, on the Habor, the river of Gozan, and in the cities of the Medes.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 17, 7, 'This occurred because the people of Israel had sinned against the LORD their God, who had brought them up out of the land of Egypt from under the hand of Pharaoh king of Egypt. They had worshiped other gods', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 17, 8, 'and walked in the customs of the nations whom the LORD drove out before the people of Israel, and in the customs that the kings of Israel had introduced.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 17, 9, 'The people of Israel secretly did things that were not right against the LORD their God. They built for themselves high places at all their towns, from watchtower to fortified city;', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 17, 10, 'they set up for themselves pillars and sacred poles on every high hill and under every green tree;', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 17, 11, 'there they made offerings on all the high places, as the nations did whom the LORD carried away before them. They did wicked things, provoking the LORD to anger;', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 17, 12, 'they served idols, of which the LORD had said to them, "You shall not do this."', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 17, 13, 'Yet the LORD warned Israel and Judah by every prophet and every seer, saying, "Turn from your evil ways and keep my commandments and my statutes, in accordance with all the law that I commanded your ancestors and that I sent to you by my servants the prophets."', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 17, 14, 'They would not listen but were stubborn, as their ancestors had been, who did not believe in the LORD their God.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 17, 15, 'They despised his statutes, and his covenant that he made with their ancestors, and the warnings that he gave them. They went after false idols and became false; they followed the nations that were around them, concerning whom the LORD had commanded them that they should not do as they did.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 17, 16, 'They rejected all the commandments of the LORD their God and made for themselves cast images of two calves; they made a sacred pole, worshiped all the host of heaven, and served Baal.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 17, 17, 'They made their sons and their daughters pass through fire; they used divination and augury; and they sold themselves to do evil in the sight of the LORD, provoking him to anger.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 17, 18, 'Therefore the LORD was very angry with Israel and removed them out of his sight; none was left but the tribe of Judah alone.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 17, 19, 'Judah also did not keep the commandments of the LORD their God but walked in the customs that Israel had introduced.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 17, 20, 'The LORD rejected all the descendants of Israel; he punished them and gave them into the hand of plunderers, until he had banished them from his presence.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 17, 21, 'When he had torn Israel from the house of David, they made Jeroboam son of Nebat king. Jeroboam drove Israel from following the LORD and made them commit great sin.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 17, 22, 'The people of Israel continued in all the sins that Jeroboam committed; they did not depart from them', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 17, 23, 'until the LORD removed Israel out of his sight, as he had foretold through all his servants the prophets. So Israel was exiled from their own land to Assyria until this day.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 17, 24, 'The king of Assyria brought people from Babylon, Cuthah, Avva, Hamath, and Sepharvaim, and placed them in the cities of Samaria in place of the people of Israel; they took possession of Samaria, and settled in its cities.', 'en', 'NRSV-CE', 'Assyria Resettles Samaria'),
(12, '2 Raj', '2 Kings', 17, 25, 'When they first settled there, they did not worship the LORD; therefore the LORD sent lions among them, which killed some of them.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 17, 26, 'So the king of Assyria was told, "The nations that you have carried away and placed in the cities of Samaria do not know the law of the god of the land; therefore he has sent lions among them; they are killing them, because they do not know the law of the god of the land."', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 17, 27, 'Then the king of Assyria commanded, "Send there one of the priests whom you carried away from there; let him go and live there, and teach them the law of the god of the land."', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 17, 28, 'So one of the priests whom they had carried away from Samaria came and lived in Bethel; he taught them how they should worship the LORD.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 17, 29, 'But every nation still made gods of its own and put them in the shrines of the high places that the people of Samaria had made, every nation in the cities in which they lived;', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 17, 30, 'the people of Babylon made Succoth-benoth, the people of Cuth made Nergal, the people of Hamath made Ashima;', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 17, 31, 'the Avvites made Nibhaz and Tartak; the Sepharvites burned their children in the fire to Adrammelech and Anammelech, the gods of Sepharvaim.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 17, 32, 'They also worshiped the LORD and appointed from among themselves all sorts of people as priests of the high places, who sacrificed for them in the shrines of the high places.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 17, 33, 'So they worshiped the LORD but also served their own gods, after the manner of the nations from among whom they had been carried away.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 17, 34, 'To this day they continue to practice their former customs.
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(12, '2 Raj', '2 Kings', 18, 1, 'In the third year of King Hoshea son of Elah of Israel, Hezekiah son of King Ahaz of Judah began to reign.', 'en', 'NRSV-CE', 'Hezekiah"s Reign over Judah'),
(12, '2 Raj', '2 Kings', 18, 2, 'He was twenty-five years old when he began to reign; he reigned twenty-nine years in Jerusalem. His mother"s name was Abi daughter of Zechariah.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 18, 3, 'He did what was right in the sight of the LORD just as his ancestor David had done.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 18, 4, 'He removed the high places, broke down the pillars, and cut down the sacred pole. He broke in pieces the bronze serpent that Moses had made, for until those days the people of Israel had made offerings to it; it was called Nehushtan.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 18, 5, 'He trusted in the LORD the God of Israel; so that there was no one like him among all the kings of Judah after him, or among those who were before him.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 18, 6, 'For he held fast to the LORD; he did not depart from following him but kept the commandments that the LORD commanded Moses.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 18, 7, 'The LORD was with him; wherever he went, he prospered. He rebelled against the king of Assyria and would not serve him.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 18, 8, 'He attacked the Philistines as far as Gaza and its territory, from watchtower to fortified city.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 18, 9, 'In the fourth year of King Hezekiah, which was the seventh year of King Hoshea son of Elah of Israel, King Shalmaneser of Assyria came up against Samaria, besieged it,', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 18, 10, 'and at the end of three years, took it. In the sixth year of Hezekiah, which was the ninth year of King Hoshea of Israel, Samaria was taken.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 18, 11, 'The king of Assyria carried the Israelites away to Assyria, settled them in Halah, on the Habor, the river of Gozan, and in the cities of the Medes,', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 18, 12, 'because they did not obey the voice of the LORD their God but transgressed his covenant--all that Moses the servant of the LORD had commanded; they neither listened nor obeyed.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 18, 13, 'In the fourteenth year of King Hezekiah, King Sennacherib of Assyria came up against all the fortified cities of Judah and captured them.', 'en', 'NRSV-CE', 'Sennacherib Invades Judah'),
(12, '2 Raj', '2 Kings', 18, 14, 'King Hezekiah of Judah sent to the king of Assyria at Lachish, saying, "I have done wrong; withdraw from me; whatever you impose on me I will bear." The king of Assyria demanded of King Hezekiah of Judah three hundred talents of silver and thirty talents of gold.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 18, 15, 'Hezekiah gave him all the silver that was found in the house of the LORD and in the treasuries of the king"s house.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 18, 16, 'At that time Hezekiah stripped the gold from the doors of the temple of the LORD, and from the doorposts that King Hezekiah of Judah had overlaid and gave it to the king of Assyria.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 18, 17, 'The king of Assyria sent the Tartan, the Rabsaris, and the Rabshakeh with a great army from Lachish to King Hezekiah at Jerusalem. They went up and came to Jerusalem. When they arrived, they came and stood by the conduit of the upper pool, which is on the highway to the Fuller"s Field.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 18, 18, 'When they called for the king, there came out to them Eliakim son of Hilkiah, who was in charge of the palace, and Shebnah the secretary, and Joah son of Asaph, the recorder.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 18, 19, 'The Rabshakeh said to them, "Say to Hezekiah: Thus says the great king, the king of Assyria: On what do you base this confidence of yours?', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 18, 20, 'Do you think that mere words are strategy and power for war? On whom do you now rely, that you have rebelled against me?', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 18, 21, 'See, you are relying now on Egypt, that broken reed of a staff, which will pierce the hand of anyone who leans on it. Such is Pharaoh king of Egypt to all who rely on him.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 18, 22, 'But if you say to me, "We rely on the LORD our God," is it not he whose high places and altars Hezekiah has removed, saying to Judah and to Jerusalem, "You shall worship before this altar in Jerusalem"?', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 18, 23, 'Come now, make a wager with my master the king of Assyria: I will give you two thousand horses, if you are able on your part to set riders on them.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 18, 24, 'How then can you repulse a single captain among the least of my master"s servants, when you rely on Egypt for chariots and for horsemen?', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 18, 25, 'Moreover, is it without the LORD that I have come up against this place to destroy it? The LORD said to me, Go up against this land, and destroy it."', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 18, 26, 'Then Eliakim son of Hilkiah, and Shebnah, and Joah said to the Rabshakeh, "Please speak to your servants in the Aramaic language, for we understand it; do not speak to us in the language of Judah within the hearing of the people who are on the wall."', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 18, 27, 'But the Rabshakeh said to them, "Has my master sent me to speak these words to your master and to you, and not to the people sitting on the wall, who are doomed with you to eat their own dung and to drink their own urine?"', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 18, 28, 'Then the Rabshakeh stood and called out in a loud voice in the language of Judah, "Hear the word of the great king, the king of Assyria!', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 18, 29, 'Thus says the king: "Do not let Hezekiah deceive you, for he will not be able to deliver you out of my hand.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 18, 30, 'Do not let Hezekiah make you rely on the LORD by saying, The LORD will surely deliver us, and this city will not be given into the hand of the king of Assyria."', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 18, 31, 'Do not listen to Hezekiah; for thus says the king of Assyria: "Make your peace with me and come out to me; then every one of you will eat from your own vine and your own fig tree, and drink water from your own cistern,', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 18, 32, 'until I come and take you away to a land like your own land, a land of grain and wine, a land of bread and vineyards, a land of olive oil and honey, that you may live and not die. Do not listen to Hezekiah when he misleads you by saying, The LORD will deliver us.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 18, 33, 'Has any of the gods of the nations ever delivered its land out of the hand of the king of Assyria?', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 18, 34, 'Where are the gods of Hamath and Arpad? Where are the gods of Sepharvaim, Hena, and Ivvah? Have they delivered Samaria out of my hand?', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 18, 35, 'Who among all the gods of the countries have delivered their countries out of my hand, that the LORD should deliver Jerusalem out of my hand?""', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 18, 36, 'But the people were silent and answered him not a word, for the king"s command was, "Do not answer him."', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 18, 37, 'Then Eliakim son of Hilkiah, who was in charge of the palace, and Shebna the secretary, and Joah son of Asaph, the recorder, came to Hezekiah with their clothes torn and told him the words of the Rabshakeh.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(12, '2 Raj', '2 Kings', 19, 1, 'When King Hezekiah heard it, he tore his clothes, covered himself with sackcloth, and went into the house of the LORD.', 'en', 'NRSV-CE', 'Hezekiah Consults Isaiah'),
(12, '2 Raj', '2 Kings', 19, 2, 'And he sent Eliakim, who was in charge of the palace, and Shebna the secretary, and the senior priests, covered with sackcloth, to the prophet Isaiah son of Amoz.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 19, 3, 'They said to him, "Thus says Hezekiah, This day is a day of distress, of rebuke, and of disgrace; children have come to the birth, and there is no strength to bring them forth.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 19, 4, 'It may be that the LORD your God heard all the words of the Rabshakeh, whom his master the king of Assyria has sent to mock the living God, and will rebuke the words that the LORD your God has heard; therefore lift up your prayer for the remnant that is left."', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 19, 5, 'When the servants of King Hezekiah came to Isaiah,', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 19, 6, 'Isaiah said to them, "Say to your master, "Thus says the LORD: Do not be afraid because of the words that you have heard, with which the servants of the king of Assyria have reviled me.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 19, 7, 'I myself will put a spirit in him, so that he shall hear a rumor and return to his own land; I will cause him to fall by the sword in his own land.""', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 19, 8, 'The Rabshakeh returned, and found the king of Assyria fighting against Libnah; for he had heard that the king had left Lachish.', 'en', 'NRSV-CE', 'Sennacherib"s Threat'),
(12, '2 Raj', '2 Kings', 19, 9, 'When the king heard concerning King Tirhakah of Ethiopia, "See, he has set out to fight against you," he sent messengers again to Hezekiah, saying,', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 19, 10, '"Thus shall you speak to King Hezekiah of Judah: Do not let your God on whom you rely deceive you by promising that Jerusalem will not be given into the hand of the king of Assyria.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 19, 11, 'See, you have heard what the kings of Assyria have done to all lands, destroying them utterly. Shall you be delivered?', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 19, 12, 'Have the gods of the nations delivered them, the nations that my predecessors destroyed, Gozan, Haran, Rezeph, and the people of Eden who were in Telassar?', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 19, 13, 'Where is the king of Hamath, the king of Arpad, the king of the city of Sepharvaim, the king of Hena, or the king of Ivvah?"', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 19, 14, 'Hezekiah received the letter from the hand of the messengers and read it; then Hezekiah went up to the house of the LORD and spread it before the LORD.', 'en', 'NRSV-CE', 'Hezekiah"s Prayer'),
(12, '2 Raj', '2 Kings', 19, 15, 'And Hezekiah prayed before the LORD, and said: "O LORD the God of Israel, who are enthroned above the cherubim, you are God, you alone, of all the kingdoms of the earth; you have made heaven and earth.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 19, 16, 'Incline your ear, O LORD, and hear; open your eyes, O LORD, and see; hear the words of Sennacherib, which he has sent to mock the living God.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 19, 17, 'Truly, O LORD, the kings of Assyria have laid waste the nations and their lands,', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 19, 18, 'and have hurled their gods into the fire, though they were no gods but the work of human hands--wood and stone--and so they were destroyed.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 19, 19, 'So now, O LORD our God, save us, I pray you, from his hand, so that all the kingdoms of the earth may know that you, O LORD, are God alone."', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 19, 20, 'Then Isaiah son of Amoz sent to Hezekiah, saying, "Thus says the LORD, the God of Israel: I have heard your prayer to me about King Sennacherib of Assyria.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 19, 21, 'This is the word that the LORD has spoken concerning him:
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(12, '2 Raj', '2 Kings', 20, 1, 'In those days Hezekiah became sick and was at the point of death. The prophet Isaiah son of Amoz came to him, and said to him, "Thus says the LORD: Set your house in order, for you shall die; you shall not recover."', 'en', 'NRSV-CE', 'Hezekiah"s Illness'),
(12, '2 Raj', '2 Kings', 20, 2, 'Then Hezekiah turned his face to the wall and prayed to the LORD:', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 20, 3, '"Remember now, O LORD, I implore you, how I have walked before you in faithfulness with a whole heart, and have done what is good in your sight." Hezekiah wept bitterly.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 20, 4, 'Before Isaiah had gone out of the middle court, the word of the LORD came to him:', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 20, 5, '"Turn back, and say to Hezekiah prince of my people, Thus says the LORD, the God of your ancestor David: I have heard your prayer, I have seen your tears; indeed, I will heal you; on the third day you shall go up to the house of the LORD.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 20, 6, 'I will add fifteen years to your life. I will deliver you and this city out of the hand of the king of Assyria; I will defend this city for my own sake and for my servant David"s sake."', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 20, 7, 'Then Isaiah said, "Bring a lump of figs. Let them take it and apply it to the boil, so that he may recover."', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 20, 8, 'Hezekiah said to Isaiah, "What shall be the sign that the LORD will heal me, and that I shall go up to the house of the LORD on the third day?"', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 20, 9, 'Isaiah said, "This is the sign to you from the LORD, that the LORD will do the thing that he has promised: the shadow has now advanced ten intervals; shall it retreat ten intervals?"', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 20, 10, 'Hezekiah answered, "It is normal for the shadow to lengthen ten intervals; rather let the shadow retreat ten intervals."', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 20, 11, 'The prophet Isaiah cried to the LORD; and he brought the shadow back the ten intervals, by which the sun had declined on the dial of Ahaz.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 20, 12, 'At that time King Merodach-baladan son of Baladan of Babylon sent envoys with letters and a present to Hezekiah, for he had heard that Hezekiah had been sick.', 'en', 'NRSV-CE', 'Envoys from Babylon'),
(12, '2 Raj', '2 Kings', 20, 13, 'Hezekiah welcomed them; he showed them all his treasure house, the silver, the gold, the spices, the precious oil, his armory, all that was found in his storehouses; there was nothing in his house or in all his realm that Hezekiah did not show them.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 20, 14, 'Then the prophet Isaiah came to King Hezekiah, and said to him, "What did these men say? From where did they come to you?" Hezekiah answered, "They have come from a far country, from Babylon."', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 20, 15, 'He said, "What have they seen in your house?" Hezekiah answered, "They have seen all that is in my house; there is nothing in my storehouses that I did not show them."', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 20, 16, 'Then Isaiah said to Hezekiah, "Hear the word of the LORD:', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 20, 17, 'Days are coming when all that is in your house, and that which your ancestors have stored up until this day, shall be carried to Babylon; nothing shall be left, says the LORD.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 20, 18, 'Some of your own sons who are born to you shall be taken away; they shall be eunuchs in the palace of the king of Babylon."', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 20, 19, 'Then Hezekiah said to Isaiah, "The word of the LORD that you have spoken is good." For he thought, "Why not, if there will be peace and security in my days?"', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 20, 20, 'The rest of the deeds of Hezekiah, all his power, how he made the pool and the conduit and brought water into the city, are they not written in the Book of the Annals of the Kings of Judah?', 'en', 'NRSV-CE', 'Death of Hezekiah'),
(12, '2 Raj', '2 Kings', 20, 21, 'Hezekiah slept with his ancestors; and his son Manasseh succeeded him.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(12, '2 Raj', '2 Kings', 21, 1, 'Manasseh was twelve years old when he began to reign; he reigned fifty-five years in Jerusalem. His mother"s name was Hephzibah.', 'en', 'NRSV-CE', 'Manasseh Reigns over Judah'),
(12, '2 Raj', '2 Kings', 21, 2, 'He did what was evil in the sight of the LORD, following the abominable practices of the nations that the LORD drove out before the people of Israel.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 21, 3, 'For he rebuilt the high places that his father Hezekiah had destroyed; he erected altars for Baal, made a sacred pole, as King Ahab of Israel had done, worshiped all the host of heaven, and served them.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 21, 4, 'He built altars in the house of the LORD, of which the LORD had said, "In Jerusalem I will put my name."', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 21, 5, 'He built altars for all the host of heaven in the two courts of the house of the LORD.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 21, 6, 'He made his son pass through fire; he practiced soothsaying and augury, and dealt with mediums and with wizards. He did much evil in the sight of the LORD, provoking him to anger.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 21, 7, 'The carved image of Asherah that he had made he set in the house of which the LORD said to David and to his son Solomon, "In this house, and in Jerusalem, which I have chosen out of all the tribes of Israel, I will put my name forever;', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 21, 8, 'I will not cause the feet of Israel to wander any more out of the land that I gave to their ancestors, if only they will be careful to do according to all that I have commanded them, and according to all the law that my servant Moses commanded them."', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 21, 9, 'But they did not listen; Manasseh misled them to do more evil than the nations had done that the LORD destroyed before the people of Israel.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 21, 10, 'The LORD said by his servants the prophets,', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 21, 11, '"Because King Manasseh of Judah has committed these abominations, has done things more wicked than all that the Amorites did, who were before him, and has caused Judah also to sin with his idols;', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 21, 12, 'therefore thus says the LORD, the God of Israel, I am bringing upon Jerusalem and Judah such evil that the ears of everyone who hears of it will tingle.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 21, 13, 'I will stretch over Jerusalem the measuring line for Samaria, and the plummet for the house of Ahab; I will wipe Jerusalem as one wipes a dish, wiping it and turning it upside down.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 21, 14, 'I will cast off the remnant of my heritage, and give them into the hand of their enemies; they shall become a prey and a spoil to all their enemies,', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 21, 15, 'because they have done what is evil in my sight and have provoked me to anger, since the day their ancestors came out of Egypt, even to this day."', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 21, 16, 'Moreover Manasseh shed very much innocent blood, until he had filled Jerusalem from one end to another, besides the sin that he caused Judah to sin so that they did what was evil in the sight of the LORD.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 21, 17, 'Now the rest of the acts of Manasseh, all that he did, and the sin that he committed, are they not written in the Book of the Annals of the Kings of Judah?', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 21, 18, 'Manasseh slept with his ancestors, and was buried in the garden of his house, in the garden of Uzza. His son Amon succeeded him.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 21, 19, 'Amon was twenty-two years old when he began to reign; he reigned two years in Jerusalem. His mother"s name was Meshullemeth daughter of Haruz of Jotbah.', 'en', 'NRSV-CE', 'Amon Reigns over Judah'),
(12, '2 Raj', '2 Kings', 21, 20, 'He did what was evil in the sight of the LORD, as his father Manasseh had done.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 21, 21, 'He walked in all the way in which his father walked, served the idols that his father served, and worshiped them;', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 21, 22, 'he abandoned the LORD, the God of his ancestors, and did not walk in the way of the LORD.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 21, 23, 'The servants of Amon conspired against him, and killed the king in his house.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 21, 24, 'But the people of the land killed all those who had conspired against King Amon, and the people of the land made his son Josiah king in place of him.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 21, 25, 'Now the rest of the acts of Amon that he did, are they not written in the Book of the Annals of the Kings of Judah?', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 21, 26, 'He was buried in his tomb in the garden of Uzza; then his son Josiah succeeded him.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(12, '2 Raj', '2 Kings', 22, 1, 'Josiah was eight years old when he began to reign; he reigned thirty-one years in Jerusalem. His mother"s name was Jedidah daughter of Adaiah of Bozkath.', 'en', 'NRSV-CE', 'Josiah Reigns over Judah'),
(12, '2 Raj', '2 Kings', 22, 2, 'He did what was right in the sight of the LORD, and walked in all the way of his father David; he did not turn aside to the right or to the left.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 22, 3, 'In the eighteenth year of King Josiah, the king sent Shaphan son of Azaliah, son of Meshullam, the secretary, to the house of the LORD, saying,', 'en', 'NRSV-CE', 'Hilkiah Finds the Book of the Law'),
(12, '2 Raj', '2 Kings', 22, 4, '"Go up to the high priest Hilkiah, and have him count the entire sum of the money that has been brought into the house of the LORD, which the keepers of the threshold have collected from the people;', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 22, 5, 'let it be given into the hand of the workers who have the oversight of the house of the LORD; let them give it to the workers who are at the house of the LORD, repairing the house,', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 22, 6, 'that is, to the carpenters, to the builders, to the masons; and let them use it to buy timber and quarried stone to repair the house.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 22, 7, 'But no accounting shall be asked from them for the money that is delivered into their hand, for they deal honestly."', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 22, 8, 'The high priest Hilkiah said to Shaphan the secretary, "I have found the book of the law in the house of the LORD." When Hilkiah gave the book to Shaphan, he read it.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 22, 9, 'Then Shaphan the secretary came to the king, and reported to the king, "Your servants have emptied out the money that was found in the house, and have delivered it into the hand of the workers who have oversight of the house of the LORD."', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 22, 10, 'Shaphan the secretary informed the king, "The priest Hilkiah has given me a book." Shaphan then read it aloud to the king.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 22, 11, 'When the king heard the words of the book of the law, he tore his clothes.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 22, 12, 'Then the king commanded the priest Hilkiah, Ahikam son of Shaphan, Achbor son of Micaiah, Shaphan the secretary, and the king"s servant Asaiah, saying,', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 22, 13, '"Go, inquire of the LORD for me, for the people, and for all Judah, concerning the words of this book that has been found; for great is the wrath of the LORD that is kindled against us, because our ancestors did not obey the words of this book, to do according to all that is written concerning us."', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 22, 14, 'So the priest Hilkiah, Ahikam, Achbor, Shaphan, and Asaiah went to the prophetess Huldah the wife of Shallum son of Tikvah, son of Harhas, keeper of the wardrobe; she resided in Jerusalem in the Second Quarter, where they consulted her.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 22, 15, 'She declared to them, "Thus says the LORD, the God of Israel: Tell the man who sent you to me,', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 22, 16, 'Thus says the LORD, I will indeed bring disaster on this place and on its inhabitants--all the words of the book that the king of Judah has read.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 22, 17, 'Because they have abandoned me and have made offerings to other gods, so that they have provoked me to anger with all the work of their hands, therefore my wrath will be kindled against this place, and it will not be quenched.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 22, 18, 'But as to the king of Judah, who sent you to inquire of the LORD, thus shall you say to him, Thus says the LORD, the God of Israel: Regarding the words that you have heard,', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 22, 19, 'because your heart was penitent, and you humbled yourself before the LORD, when you heard how I spoke against this place, and against its inhabitants, that they should become a desolation and a curse, and because you have torn your clothes and wept before me, I also have heard you, says the LORD.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 22, 20, 'Therefore, I will gather you to your ancestors, and you shall be gathered to your grave in peace; your eyes shall not see all the disaster that I will bring on this place." They took the message back to the king.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(12, '2 Raj', '2 Kings', 23, 1, 'Then the king directed that all the elders of Judah and Jerusalem should be gathered to him.', 'en', 'NRSV-CE', 'Josiah"s Reformation'),
(12, '2 Raj', '2 Kings', 23, 2, 'The king went up to the house of the LORD, and with him went all the people of Judah, all the inhabitants of Jerusalem, the priests, the prophets, and all the people, both small and great; he read in their hearing all the words of the book of the covenant that had been found in the house of the LORD.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 23, 3, 'The king stood by the pillar and made a covenant before the LORD, to follow the LORD, keeping his commandments, his decrees, and his statutes, with all his heart and all his soul, to perform the words of this covenant that were written in this book. All the people joined in the covenant.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 23, 4, 'The king commanded the high priest Hilkiah, the priests of the second order, and the guardians of the threshold, to bring out of the temple of the LORD all the vessels made for Baal, for Asherah, and for all the host of heaven; he burned them outside Jerusalem in the fields of the Kidron, and carried their ashes to Bethel.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 23, 5, 'He deposed the idolatrous priests whom the kings of Judah had ordained to make offerings in the high places at the cities of Judah and around Jerusalem; those also who made offerings to Baal, to the sun, the moon, the constellations, and all the host of the heavens.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 23, 6, 'He brought out the image of Asherah from the house of the LORD, outside Jerusalem, to the Wadi Kidron, burned it at the Wadi Kidron, beat it to dust and threw the dust of it upon the graves of the common people.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 23, 7, 'He broke down the houses of the male temple prostitutes that were in the house of the LORD, where the women did weaving for Asherah.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 23, 8, 'He brought all the priests out of the towns of Judah, and defiled the high places where the priests had made offerings, from Geba to Beer-sheba; he broke down the high places of the gates that were at the entrance of the gate of Joshua the governor of the city, which were on the left at the gate of the city.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 23, 9, 'The priests of the high places, however, did not come up to the altar of the LORD in Jerusalem, but ate unleavened bread among their kindred.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 23, 10, 'He defiled Topheth, which is in the valley of Ben-hinnom, so that no one would make a son or a daughter pass through fire as an offering to Molech.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 23, 11, 'He removed the horses that the kings of Judah had dedicated to the sun, at the entrance to the house of the LORD, by the chamber of the eunuch Nathan-melech, which was in the precincts; then he burned the chariots of the sun with fire.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 23, 12, 'The altars on the roof of the upper chamber of Ahaz, which the kings of Judah had made, and the altars that Manasseh had made in the two courts of the house of the LORD, he pulled down from there and broke in pieces, and threw the rubble into the Wadi Kidron.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 23, 13, 'The king defiled the high places that were east of Jerusalem, to the south of the Mount of Destruction, which King Solomon of Israel had built for Astarte the abomination of the Sidonians, for Chemosh the abomination of Moab, and for Milcom the abomination of the Ammonites.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 23, 14, 'He broke the pillars in pieces, cut down the sacred poles, and covered the sites with human bones.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 23, 15, 'Moreover, the altar at Bethel, the high place erected by Jeroboam son of Nebat, who caused Israel to sin--he pulled down that altar along with the high place. He burned the high place, crushing it to dust; he also burned the sacred pole.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 23, 16, 'As Josiah turned, he saw the tombs there on the mount; and he sent and took the bones out of the tombs, and burned them on the altar, and defiled it, according to the word of the LORD that the man of God proclaimed, when Jeroboam stood by the altar at the festival; he turned and looked up at the tomb of the man of God who had predicted these things.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 23, 17, 'Then he said, "What is that monument that I see?" The people of the city told him, "It is the tomb of the man of God who came from Judah and predicted these things that you have done against the altar at Bethel."', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 23, 18, 'He said, "Let him rest; let no one move his bones." So they let his bones alone, with the bones of the prophet who came out of Samaria.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 23, 19, 'Moreover, Josiah removed all the shrines of the high places that were in the towns of Samaria, which kings of Israel had made, provoking the LORD to anger; he did to them just as he had done at Bethel.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 23, 20, 'He slaughtered on the altars all the priests of the high places who were there, and burned human bones on them. Then he returned to Jerusalem.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 23, 21, 'The king commanded all the people, "Keep the passover to the LORD your God as prescribed in this book of the covenant."', 'en', 'NRSV-CE', 'The Passover Celebrated'),
(12, '2 Raj', '2 Kings', 23, 22, 'No such passover had been kept since the days of the judges who judged Israel, even during all the days of the kings of Israel and of the kings of Judah;', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 23, 23, 'but in the eighteenth year of King Josiah this passover was kept to the LORD in Jerusalem.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 23, 24, 'Moreover Josiah put away the mediums, wizards, teraphim, idols, and all the abominations that were seen in the land of Judah and in Jerusalem, so that he established the words of the law that were written in the book that the priest Hilkiah had found in the house of the LORD.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 23, 25, 'Before him there was no king like him, who turned to the LORD with all his heart, with all his soul, and with all his might, according to all the law of Moses; nor did any like him arise after him.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 23, 26, 'Still the LORD did not turn from the fierceness of his great wrath, by which his anger was kindled against Judah, because of all the provocations with which Manasseh had provoked him.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 23, 27, 'The LORD said, "I will remove Judah also out of my sight, as I have removed Israel; and I will reject this city that I have chosen, Jerusalem, and the house of which I said, My name shall be there."', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 23, 28, 'Now the rest of the acts of Josiah, and all that he did, are they not written in the Book of the Annals of the Kings of Judah?', 'en', 'NRSV-CE', 'Josiah Dies in Battle'),
(12, '2 Raj', '2 Kings', 23, 29, 'In his days Pharaoh Neco king of Egypt went up to the king of Assyria to the river Euphrates. King Josiah went to meet him; but when Pharaoh Neco met him at Megiddo, he killed him.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 23, 30, 'His servants carried him dead in a chariot from Megiddo, brought him to Jerusalem, and buried him in his own tomb. The people of the land took Jehoahaz son of Josiah, anointed him, and made him king in place of his father.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 23, 31, 'Jehoahaz was twenty-three years old when he began to reign; he reigned three months in Jerusalem. His mother"s name was Hamutal daughter of Jeremiah of Libnah.', 'en', 'NRSV-CE', 'Reign and Captivity of Jehoahaz'),
(12, '2 Raj', '2 Kings', 23, 32, 'He did what was evil in the sight of the LORD, just as his ancestors had done.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 23, 33, 'Pharaoh Neco confined him at Riblah in the land of Hamath, so that he might not reign in Jerusalem, and imposed tribute on the land of one hundred talents of silver and a talent of gold.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 23, 34, 'Pharaoh Neco made Eliakim son of Josiah king in place of his father Josiah, and changed his name to Jehoiakim. But he took Jehoahaz away; he came to Egypt, and died there.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 23, 35, 'Jehoiakim gave the silver and the gold to Pharaoh, but he taxed the land in order to meet Pharaoh"s demand for money. He exacted the silver and the gold from the people of the land, from all according to their assessment, to give it to Pharaoh Neco.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 23, 36, 'Jehoiakim was twenty-five years old when he began to reign; he reigned eleven years in Jerusalem. His mother"s name was Zebidah daughter of Pedaiah of Rumah.', 'en', 'NRSV-CE', 'Jehoiakim Reigns over Judah'),
(12, '2 Raj', '2 Kings', 23, 37, 'He did what was evil in the sight of the LORD, just as all his ancestors had done.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(12, '2 Raj', '2 Kings', 24, 1, 'In his days King Nebuchadnezzar of Babylon came up; Jehoiakim became his servant for three years; then he turned and rebelled against him.', 'en', 'NRSV-CE', 'Judah Overrun by Enemies'),
(12, '2 Raj', '2 Kings', 24, 2, 'The LORD sent against him bands of the Chaldeans, bands of the Arameans, bands of the Moabites, and bands of the Ammonites; he sent them against Judah to destroy it, according to the word of the LORD that he spoke by his servants the prophets.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 24, 3, 'Surely this came upon Judah at the command of the LORD, to remove them out of his sight, for the sins of Manasseh, for all that he had committed,', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 24, 4, 'and also for the innocent blood that he had shed; for he filled Jerusalem with innocent blood, and the LORD was not willing to pardon.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 24, 5, 'Now the rest of the deeds of Jehoiakim, and all that he did, are they not written in the Book of the Annals of the Kings of Judah?', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 24, 6, 'So Jehoiakim slept with his ancestors; then his son Jehoiachin succeeded him.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 24, 7, 'The king of Egypt did not come again out of his land, for the king of Babylon had taken over all that belonged to the king of Egypt from the Wadi of Egypt to the River Euphrates.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 24, 8, 'Jehoiachin was eighteen years old when he began to reign; he reigned three months in Jerusalem. His mother"s name was Nehushta daughter of Elnathan of Jerusalem.', 'en', 'NRSV-CE', 'Reign and Captivity of Jehoiachin'),
(12, '2 Raj', '2 Kings', 24, 9, 'He did what was evil in the sight of the LORD, just as his father had done.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 24, 10, 'At that time the servants of King Nebuchadnezzar of Babylon came up to Jerusalem, and the city was besieged.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 24, 11, 'King Nebuchadnezzar of Babylon came to the city, while his servants were besieging it;', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 24, 12, 'King Jehoiachin of Judah gave himself up to the king of Babylon, himself, his mother, his servants, his officers, and his palace officials. The king of Babylon took him prisoner in the eighth year of his reign.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 24, 13, 'He carried off all the treasures of the house of the LORD, and the treasures of the king"s house; he cut in pieces all the vessels of gold in the temple of the LORD, which King Solomon of Israel had made, all this as the LORD had foretold.', 'en', 'NRSV-CE', 'Capture of Jerusalem'),
(12, '2 Raj', '2 Kings', 24, 14, 'He carried away all Jerusalem, all the officials, all the warriors, ten thousand captives, all the artisans and the smiths; no one remained, except the poorest people of the land.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 24, 15, 'He carried away Jehoiachin to Babylon; the king"s mother, the king"s wives, his officials, and the elite of the land, he took into captivity from Jerusalem to Babylon.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 24, 16, 'The king of Babylon brought captive to Babylon all the men of valor, seven thousand, the artisans and the smiths, one thousand, all of them strong and fit for war.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 24, 17, 'The king of Babylon made Mattaniah, Jehoiachin"s uncle, king in his place, and changed his name to Zedekiah.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 24, 18, 'Zedekiah was twenty-one years old when he began to reign; he reigned eleven years in Jerusalem. His mother"s name was Hamutal daughter of Jeremiah of Libnah.', 'en', 'NRSV-CE', 'Zedekiah Reigns over Judah'),
(12, '2 Raj', '2 Kings', 24, 19, 'He did what was evil in the sight of the LORD, just as Jehoiakim had done.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 24, 20, 'Indeed, Jerusalem and Judah so angered the LORD that he expelled them from his presence.
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(12, '2 Raj', '2 Kings', 25, 1, 'And in the ninth year of his reign, in the tenth month, on the tenth day of the month, King Nebuchadnezzar of Babylon came with all his army against Jerusalem, and laid siege to it; they built siegeworks against it all around.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 25, 2, 'So the city was besieged until the eleventh year of King Zedekiah.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 25, 3, 'On the ninth day of the fourth month the famine became so severe in the city that there was no food for the people of the land.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 25, 4, 'Then a breach was made in the city wall; the king with all the soldiers fled by night by the way of the gate between the two walls, by the king"s garden, though the Chaldeans were all around the city. They went in the direction of the Arabah.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 25, 5, 'But the army of the Chaldeans pursued the king, and overtook him in the plains of Jericho; all his army was scattered, deserting him.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 25, 6, 'Then they captured the king and brought him up to the king of Babylon at Riblah, who passed sentence on him.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 25, 7, 'They slaughtered the sons of Zedekiah before his eyes, then put out the eyes of Zedekiah; they bound him in fetters and took him to Babylon.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 25, 8, 'In the fifth month, on the seventh day of the month--which was the nineteenth year of King Nebuchadnezzar, king of Babylon--Nebuzaradan, the captain of the bodyguard, a servant of the king of Babylon, came to Jerusalem.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 25, 9, 'He burned the house of the LORD, the king"s house, and all the houses of Jerusalem; every great house he burned down.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 25, 10, 'All the army of the Chaldeans who were with the captain of the guard broke down the walls around Jerusalem.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 25, 11, 'Nebuzaradan the captain of the guard carried into exile the rest of the people who were left in the city and the deserters who had defected to the king of Babylon--all the rest of the population.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 25, 12, 'But the captain of the guard left some of the poorest people of the land to be vinedressers and tillers of the soil.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 25, 13, 'The bronze pillars that were in the house of the LORD, as well as the stands and the bronze sea that were in the house of the LORD, the Chaldeans broke in pieces, and carried the bronze to Babylon.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 25, 14, 'They took away the pots, the shovels, the snuffers, the dishes for incense, and all the bronze vessels used in the temple service,', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 25, 15, 'as well as the firepans and the basins. What was made of gold the captain of the guard took away for the gold, and what was made of silver, for the silver.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 25, 16, 'As for the two pillars, the one sea, and the stands, which Solomon had made for the house of the LORD, the bronze of all these vessels was beyond weighing.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 25, 17, 'The height of the one pillar was eighteen cubits, and on it was a bronze capital; the height of the capital was three cubits; latticework and pomegranates, all of bronze, were on the capital all around. The second pillar had the same, with the latticework.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 25, 18, 'The captain of the guard took the chief priest Seraiah, the second priest Zephaniah, and the three guardians of the threshold;', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 25, 19, 'from the city he took an officer who had been in command of the soldiers, and five men of the king"s council who were found in the city; the secretary who was the commander of the army who mustered the people of the land; and sixty men of the people of the land who were found in the city.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 25, 20, 'Nebuzaradan the captain of the guard took them, and brought them to the king of Babylon at Riblah.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 25, 21, 'The king of Babylon struck them down and put them to death at Riblah in the land of Hamath. So Judah went into exile out of its land.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 25, 22, 'He appointed Gedaliah son of Ahikam son of Shaphan as governor over the people who remained in the land of Judah, whom King Nebuchadnezzar of Babylon had left.', 'en', 'NRSV-CE', 'Gedaliah Made Governor of Judah'),
(12, '2 Raj', '2 Kings', 25, 23, 'Now when all the captains of the forces and their men heard that the king of Babylon had appointed Gedaliah as governor, they came with their men to Gedaliah at Mizpah, namely, Ishmael son of Nethaniah, Johanan son of Kareah, Seraiah son of Tanhumeth the Netophathite, and Jaazaniah son of the Maacathite.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 25, 24, 'Gedaliah swore to them and their men, saying, "Do not be afraid because of the Chaldean officials; live in the land, serve the king of Babylon, and it shall be well with you."', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 25, 25, 'But in the seventh month, Ishmael son of Nethaniah son of Elishama, of the royal family, came with ten men; they struck down Gedaliah so that he died, along with the Judeans and Chaldeans who were with him at Mizpah.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 25, 26, 'Then all the people, high and low, and the captains of the forces set out and went to Egypt; for they were afraid of the Chaldeans.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 25, 27, 'In the thirty-seventh year of the exile of King Jehoiachin of Judah, in the twelfth month, on the twenty-seventh day of the month, King Evil-merodach of Babylon, in the year that he began to reign, released King Jehoiachin of Judah from prison;', 'en', 'NRSV-CE', 'Jehoiachin Released from Prison'),
(12, '2 Raj', '2 Kings', 25, 28, 'he spoke kindly to him, and gave him a seat above the other seats of the kings who were with him in Babylon.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 25, 29, 'So Jehoiachin put aside his prison clothes. Every day of his life he dined regularly in the king"s presence.', 'en', 'NRSV-CE', NULL),
(12, '2 Raj', '2 Kings', 25, 30, 'For his allowance, a regular allowance was given him by the king, a portion every day, as long as he lived.', 'en', 'NRSV-CE', NULL);
